rticulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"CAPÍTULO XII DE LOS ÓRGANOS ADMINISTRATIVOS DESCONCENTRADOS","seccion_nombre":null,"id":"11b52162-b3a7-4434-b823-320befb1d4c1","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","orden":77,"contenido_md5":"4c9e450678c518e3ee66ccf63f0cfec8"},{"identificador":"Artículo 77","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"CAPÍTULO XII DE LOS ÓRGANOS ADMINISTRATIVOS DESCONCENTRADOS","seccion_nombre":null,"id":"5f694cbc-38e9-4a9b-828b-b61750b9b05a","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","orden":78,"contenido_md5":"14aa3e472210c1369102fc4ebafad20c"},{"identificador":"Artículo 78","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"CAPÍTULO XII DE LOS ÓRGANOS ADMINISTRATIVOS DESCONCENTRADOS","seccion_nombre":null,"id":"f7150d19-2ff3-4f1a-95c7-e4f1e086d70e","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","orden":79,"contenido_md5":"34f8855bc9aaa2f51284373dbdfcdc50"},{"identificador":"Transitorio Primero","tipo_articulo":"transitorio","titulo_nombre":"Transitorios","capitulo_nombre":null,"seccion_nombre":null,"id":"e8f0a441-11e5-44e5-859c-d7e242429d74","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","orden":80,"contenido_md5":"b2d01516b670d76038b66b409b22c9b3"},{"identificador":"Transitorio Segundo","tipo_articulo":"transitorio","titulo_nombre":"Transitorios","capitulo_nombre":null,"seccion_nombre":null,"id":"9aa0c822-9739-4353-bc90-837862bd6270","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","orden":81,"contenido_md5":"b3624367501a9f9ea91a07a3f8f8afdd"},{"identificador":"Transitorio Tercero","tipo_articulo":"transitorio","titulo_nombre":"Transitorios","capitulo_nombre":null,"seccion_nombre":null,"id":"6984065d-70d0-45f5-8cf1-c38b72a63327","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","orden":82,"contenido_md5":"7ce64c2d6601c7737a489493c697022e"},{"identificador":"Transitorio Cuarto","tipo_articulo":"transitorio","titulo_nombre":"Transitorios","capitulo_nombre":null,"seccion_nombre":null,"id":"7590c6ac-a206-48a6-9585-c2e7a62ae79a","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","orden":83,"contenido_md5":"4616325aae6213a9e8f3107ebaccb2a0"},{"identificador":"Transitorio Quinto","tipo_articulo":"transitorio","titulo_nombre":"Transitorios","capitulo_nombre":null,"seccion_nombre":null,"id":"6deaaf3c-6306-4fad-982a-7f2607d3d167","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","orden":84,"contenido_md5":"afdb54d4d29cb2069343fa0c57ad0d20"},{"identificador":"Transitorio Sexto","tipo_articulo":"transitorio","titulo_nombre":"Transitorios","capitulo_nombre":null,"seccion_nombre":null,"id":"be98630c-ba00-4910-80ce-bbbebf74e7ef","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","orden":85,"contenido_md5":"f67f992d855ce63bda34e776f576b4a3"},{"identificador":"Transitorio Séptimo","tipo_articulo":"transitorio","titulo_nombre":"Transitorios","capitulo_nombre":null,"seccion_nombre":null,"id":"2091dd5d-64a3-469c-8f79-13a7bc677ba3","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","orden":86,"contenido_md5":"dc9dc74080d47dd26982f45e17dd4c81"},{"identificador":"Firmas y promulgación","tipo_articulo":"complementario","titulo_nombre":"Documentos complementarios","capitulo_nombre":null,"seccion_nombre":null,"id":"6af52cfe-fef1-5a68-ab3d-9a10a283fcce","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","orden":87,"contenido_md5":"cd433aa30db2951373b5186108f2ff6e"}],"after":[{"id":"adb117fa-e491-4a0b-86a5-f164a7d9e6f5","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Preámbulo/Considerandos","contenido":"DOF: 17/04/2025 DECRETO por el que se expide el Reglamento Interior de la Secretaría de Energía. Al margen un sello con el Escudo Nacional, que dice: Estados Unidos Mexicanos.- Presidencia de la República. CLAUDIA SHEINBAUM PARDO, Presidenta de los Estados Unidos Mexicanos, en ejercicio de la facultad que me confiere el artículo 89, fracción I, de la Constitución Política de los Estados Unidos Mexicanos, y con fundamento en los artículos 14, 17, 17 Bis, 18, 20 y 33 de la Ley Orgánica de la Administración Pública Federal, he tenido a bien emitir el siguiente DECRETO POR EL QUE SE EXPIDE EL REGLAMENTO INTERIOR DE LA SECRETARÍA DE ENERGÍA","tipo_articulo":"preambulo","titulo_nombre":null,"capitulo_nombre":null,"seccion_nombre":null,"orden":0},{"id":"4fd95411-7304-4320-9b6f-ace777e383f5","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"ARTÍCULO ÚNICO.","contenido":"Se expide el Reglamento Interior de la Secretaría de Energía, para quedar como sigue: REGLAMENTO INTERIOR DE LA SECRETARÍA DE ENERGÍA CAPÍTULO I DE LA COMPETENCIA Y ORGANIZACIÓN DE LA SECRETARÍA","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":null,"seccion_nombre":null,"orden":1},{"id":"d5b08ef9-9541-470e-b5ba-c91d4c4fcc1c","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 1.","contenido":"- El presente Reglamento tiene por objeto establecer la organización y funcionamiento de la Secretaría de Energía, en lo sucesivo la Secretaría, así como determinar la competencia, estructura y atribuciones de sus unidades administrativas y órganos administrativos desconcentrados sectorizados. La Secretaría es una dependencia del Poder Ejecutivo Federal que tiene a su cargo el ejercicio de las atribuciones y facultades que le confieren la Ley Orgánica de la Administración Pública Federal, otras leyes, reglamentos, decretos, acuerdos y demás disposiciones jurídicas aplicables.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LA COMPETENCIA Y ORGANIZACIÓN DE LA SECRETARÍA","seccion_nombre":null,"orden":2},{"id":"2969500c-9d3e-4a62-a4f0-4482118d4141","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 2.","contenido":"- La persona titular de la Secretaría, para el despacho, estudio, planeación y desahogo de los asuntos de su competencia, se auxilia de las unidades administrativas y órganos administrativos desconcentrados siguientes: A. Subsecretaría de Planeación y Transición Energética: I. Unidad del Sistema Nacional de Información Energética: I.1. Dirección General de Registros e Información Geoespacial del Sistema Nacional de Información Energética, y I.2. Dirección General de Metodologías y Estadísticas del Sistema Nacional de Información Energética; II. Dirección General de Planeación e Integración Energética; III. Dirección General de Energías Renovables; IV. Dirección General de Eficiencia y Sustentabilidad Energética; V. Dirección General de Transición Energética, y VI. Dirección General de Desarrollo Tecnológico y Acceso a la Energía; B. Subsecretaría de Electricidad: I. Unidad del Sistema Eléctrico Nacional y Política Nuclear: I.1 Dirección General de Evaluación Financiera de la Unidad del Sistema Eléctrico Nacional y Política Nuclear; II. Dirección General de Confiabilidad y Seguridad del Sector Eléctrico; III. Dirección General de Distribución, Usos Finales de Energía Eléctrica y Vinculación Social; IV. Dirección General de Generación y Transmisión de Energía Eléctrica, y V. Dirección General de Análisis y Evaluación del Mercado Eléctrico Mayorista; C. Subsecretaría de Hidrocarburos: I. Unidad de Desarrollo de Modelos Contractuales y de Asignaciones, Proyectos Regulatorios y Argumentación Técnica: I.1 Dirección General de Diseño, Desarrollo e Implementación de Asignaciones y Contratos de Exploración y Extracción; I.2 Dirección General de Proyectos de Regulación, Normas Oficiales Mexicanas y Estándares, y I.3 Dirección General de Desarrollo de Argumentación Técnica para la Implementación de la Política Regulatoria del Sector Hidrocarburos; II. Unidad Técnica de Exploración: II.1 Dirección General de Registro de Recursos Energéticos y Prospectivos de la Nación; II.2 Dirección General de Evaluación del Potencial de Hidrocarburos; II.3 Dirección General de Autorizaciones de Estudios y Pozos Exploratorios, y II.4 Dirección General de Planes de Exploración y Programas de Evaluación; III. Unidad Técnica de Extracción de Hidrocarburos: III.1 Dirección General de Medición y Balances de la Producción; III.2 Dirección General de Reservas de Hidrocarburos; III.3 Dirección General de Planes y Programas de Extracción, y III.4 Dirección General de Administración de Campos de Extracción; IV. Unidad de Políticas de Transformación Industrial: IV.1 Dirección General de Gas Natural y Petroquímicos; IV.2 Dirección General de Petrolíferos, y IV.3 Dirección General de Permisos de Importación y Exportación de Hidrocarburos, Petroquímicos y Petrolíferos; V. Unidad de Seguimiento y Supervisión de Asignaciones, Contratos y Permisos: V.1 Dirección General de Evaluación del Cumplimiento de Obligaciones de las Asignaciones y Contratos; V.2 Dirección General de Seguimiento de Asignaciones; V.3 Dirección General de Seguimiento de Contratos, y V.4 Dirección General de Supervisión Técnica; D. Unidad de Administración y Finanzas: I. Dirección General de Programación y Presupuesto; II. Dirección General de Recursos Humanos; III. Dirección General de Recursos Materiales y Servicios Generales, y IV. Dirección General de Desarrollo de Sistemas, Infraestructura y Comunicaciones; E. Oficina de la persona titular de la Secretaría: I. Unidad de Asuntos Jurídicos: I.1 Dirección General de lo Consultivo; I.2 Dirección General de Normatividad, y I.3 Dirección General de Representación Legal y de lo Contencioso; II. Unidad de Enlace Legislativo; III. Unidad de Estrategia, Vinculación Interinstitucional y Seguimiento de Proyectos e Inversiones: III.1 Dirección General de Evaluación, Análisis y Seguimiento de Proyectos; III.2 Dirección General de Estrategia y Vinculación Interinstitucional, y III.3 Dirección General de Innovación y Gobierno Ágil; IV. Dirección General de Asuntos Internacionales; V. Dirección General de Comunicación Social; VI. Dirección General de Impacto Social, Consulta Previa y Ocupación Superficial, y VII. Dirección General de Transparencia y Protección de Datos Personales, y F. Órganos administrativos desconcentrados: I. Comisión Nacional de Seguridad Nuclear y Salvaguardias; II. Comisión Nacional para el Uso Eficiente de la Energía, y III. Comisión Nacional de Energía. La Secretaría cuenta con las demás unidades administrativas subalternas y personas servidoras públicas que requiera, siempre y cuando tenga la autorización presupuestal y organizacional correspondiente, de conformidad con las disposiciones jurídicas aplicables, cuyas funciones deberán especificarse y regularse en el Manual de Organización General de la Secretaría y, en su caso, en los manuales específicos de sus unidades administrativas y de sus órganos administrativos desconcentrados.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LA COMPETENCIA Y ORGANIZACIÓN DE LA SECRETARÍA","seccion_nombre":null,"orden":3},{"id":"4f9a36f0-397d-4caf-9deb-23a0d2948cab","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 3.","contenido":"- La Secretaría de Energía debe planear y conducir sus actividades con sujeción a lo dispuesto en los instrumentos que se emitan en el marco del Sistema Nacional de Planeación Democrática y con base en las políticas que, para el logro de los objetivos y prioridades del desarrollo nacional, determine la persona titular del Ejecutivo Federal. CAPÍTULO II DE LAS FACULTADES DE LA PERSONA TITULAR DE LA SECRETARÍA","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LA COMPETENCIA Y ORGANIZACIÓN DE LA SECRETARÍA","seccion_nombre":null,"orden":4},{"id":"e078a927-b9c9-4169-9dec-048d926e2f71","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 4.","contenido":"- La representación, trámite y resolución de los asuntos que competen a la Secretaría corresponden originalmente a la persona titular de la Secretaría. La persona titular de la Secretaría, sin perjuicio de su ejercicio directo, puede delegar sus facultades en personas servidoras públicas subalternas, salvo aquellas que las disposiciones jurídicas aplicables señalen como indelegables. La persona titular de la Secretaría puede asumir, en cualquier momento, las atribuciones señaladas en el presente reglamento para las Subsecretarías, la Unidad de Administración y Finanzas, jefaturas de unidad, direcciones generales, y demás unidades administrativas subalternas de la Secretaría.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LAS FACULTADES DE LA PERSONA TITULAR DE LA SECRETARÍA","seccion_nombre":null,"orden":5},{"id":"17125d56-37d1-445e-a657-877bb1438651","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 5.","contenido":"- La persona titular de la Secretaría tiene las facultades indelegables siguientes: I. Acordar con la persona titular del Ejecutivo Federal el despacho de los asuntos que correspondan a la competencia de la Secretaría; II. Establecer, conducir y coordinar la política energética del país; III. Someter a la consideración y, en su caso, aprobación de la persona titular del Ejecutivo Federal el Programa Sectorial de Energía y los demás programas y proyectos que correspondan a la Secretaría, en términos de las disposiciones aplicables; IV. Proponer a la persona titular del Ejecutivo Federal, por conducto de la Consejería Jurídica del Ejecutivo Federal, los proyectos de iniciativas de leyes, reglamentos, decretos, acuerdos, órdenes y demás instrumentos normativos y sus modificaciones, cuya suscripción o expedición corresponda a la persona titular del Ejecutivo Federal, cuando sus disposiciones incidan en las materias de la competencia de la Secretaría, sus órganos administrativos desconcentrados, así como de las entidades paraestatales y empresas públicas del Estado sectorizadas a esta. V. Refrendar los reglamentos, decretos y acuerdos cuya expedición corresponda a la persona titular del Ejecutivo Federal, en el ámbito de competencia de la Secretaría; VI. Informar acerca del estado que guardan los asuntos de su competencia y del sector a su cargo, para la integración del informe que la persona titular del Ejecutivo Federal presenta ante el Congreso de la Unión; VII. Informar al Congreso de la Unión del estado que guarda la Secretaría, sus órganos administrativos desconcentrados, así como de las entidades paraestatales y empresas públicas del Estado sectorizadas a esta. VIII. Acudir a la convocatoria que, en su caso, le comunique cualquiera de las Cámaras del Congreso de la Unión, para que informe cuando se discuta una ley o se estudie un negocio concerniente a la competencia de la Secretaría, sus órganos administrativos desconcentrados, así como de las entidades paraestatales y empresas públicas del Estado sectorizadas a esta, o para que responda a interpelaciones o preguntas de las personas legisladoras; IX. Presidir los órganos de gobierno de las entidades paraestatales coordinadas del sector, así como los consejos de administración de las empresas públicas del Estado que se establezcan en el ámbito de competencia de la Secretaría; X. Ordenar la creación de los comités y comisiones internas, transitorias o permanentes, que se requieran para el mejor despacho de los asuntos a su cargo, así como designar a sus integrantes y presidirlas cuando lo estime conveniente; XI. Nombrar o designar a las personas representantes propietarias de la Secretaría, ante cualquier órgano colegiado, foros nacionales e internacionales o para la atención de asuntos específicos; XII. Designar o proponer, cuando corresponda, a las personas titulares de las entidades paraestatales del sector; XIII. Autorizar el anteproyecto de presupuesto anual de egresos de la Secretaría y sus modificaciones de conformidad con las disposiciones jurídicas aplicables; XIV. Adscribir orgánicamente las unidades administrativas de la Secretaría, en términos de la Ley Orgánica de la Administración Pública Federal; XV. Expedir el Manual de Organización General de la Secretaría y disponer su publicación en el Diario Oficial de la Federación, así como expedir los manuales de procedimientos y de servicios al público de la Secretaría; XVI. Designar y remover a las personas servidoras públicas que no sean nombradas por la persona titular del Ejecutivo Federal, y cuyos nombramientos sean de libre designación o de designación directa, en los niveles superiores o equivalentes a dirección general; XVII. Fijar las Condiciones Generales de Trabajo de la Secretaría; XVIII. Proponer a la persona titular del Ejecutivo Federal el establecimiento de zonas de salvaguarda a que se refiere la Ley del Sector Hidrocarburos; XIX. Proponer a la persona titular del Ejecutivo Federal la plataforma anual de producción de petróleo y de gas; XX. Emitir el código de conducta de la Secretaría e instruir su publicación y difusión en términos del presente Reglamento; XXI. Instruir la realización de los proyectos necesarios para la generación de beneficios sociales y como mecanismos de promoción de desarrollo económico, en términos de las disposiciones jurídicas aplicables y de la política pública en materia energética del país; XXII. Establecer la política de restitución de reservas de hidrocarburos, así como la relativa en materia de geotermia; XXIII. Proponer a la persona titular del Ejecutivo Federal la intervención o requisa de las instalaciones para la presentación del servicio u operación del sector energético en los casos previstos en las disposiciones jurídicas aplicables; XXIV. Designar, en su caso, a la persona que se hará cargo de la administración y operación temporal de las instalaciones de las personas permisionarias que realicen actividades del sector eléctrico, en los casos en que se determine la intervención conforme a la Ley del Sector Eléctrico; XXV. Ejercer los derechos de la Nación en materia de petróleo y todos los carburos de hidrógeno sólidos, líquidos y gaseosos; de minerales radioactivos, así como respecto del aprovechamiento de los bienes y recursos naturales que se requieran para generar, transmitir, distribuir, comercializar y suministrar energía eléctrica; XXVI. Fijar la política de desarrollo del sector eléctrico y establecer los requerimientos obligatorios en materia de fuentes renovables de energía para la generación de energía eléctrica, y XXVII. Las demás que con tal carácter se establezcan por ley, por reglamento o le confiera expresamente la persona titular del Ejecutivo Federal. CAPÍTULO III DE LAS FACULTADES GENÉRICAS DE LAS PERSONAS TITULARES DE LAS SUBSECRETARÍAS Y DE LA UNIDAD DE ADMINISTRACIÓN Y FINANZAS","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LAS FACULTADES DE LA PERSONA TITULAR DE LA SECRETARÍA","seccion_nombre":null,"orden":6},{"id":"6580822b-facd-4c73-a5cd-877f6d8e7b07","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 6.","contenido":"- A las personas titulares de las Subsecretarías y de la Unidad de Administración y Finanzas corresponde originalmente el trámite y la resolución de los asuntos de su competencia y de las unidades administrativas que les estén adscritas y tienen además las siguientes facultades: I. Acordar con la persona titular de la Secretaría el despacho de los asuntos que les correspondan; II. Someter a consideración de la persona titular de la Secretaría las políticas que deban emitirse con relación a los asuntos de su competencia; III. Dar cuenta del estado que guardan los asuntos a su cargo para la integración de los informes que la persona titular de la Secretaría deba rendir; IV. Someter a consideración de la persona titular de la Secretaría la información que le corresponda para la elaboración del Plan Nacional de Desarrollo, del Programa Sectorial y demás programas y proyectos, así como dar cuenta de las acciones realizadas para la ejecución de los mismos; V. Presentar a la persona titular de la Unidad de Administración y Finanzas el proyecto de programa anual de trabajo, anteproyecto anual de presupuesto, estudios, así como los proyectos de manuales de organización, procedimientos y servicios al público aplicables a su cargo; VI. Someter a la consideración de la persona titular de la Secretaría, con la opinión de la Unidad de Asuntos Jurídicos, los anteproyectos de iniciativas de leyes, reglamentos, decretos, acuerdos, tratados y convenios internacionales y demás disposiciones jurídicas, que contengan disposiciones en el ámbito de competencia de la Secretaría; VII. Programar, organizar, dirigir, coordinar y evaluar las actividades de las unidades administrativas que le estén adscritas; VIII. Intervenir en la selección, nombramiento, desarrollo, capacitación, promoción y adscripción del personal a su cargo, así como autorizar los movimientos internos del personal, conforme a las disposiciones jurídicas aplicables; IX. Coordinar la formulación de los requerimientos presupuestarios de las unidades administrativas que le estén adscritas; X. Emitir los actos administrativos de su competencia, incluyendo disposiciones técnico-operativas de observancia general; XI. Intervenir en la operación de las entidades paraestatales del sector, cuando proceda, conforme a las disposiciones jurídicas aplicables; XII. Autorizar y, en su caso, emitir los criterios y procedimientos que deban observar las unidades administrativas a su cargo para el despacho de sus asuntos; XIII. Representar, por designación expresa o previsión normativa a la Secretaría, por sí o a través de las personas titulares de las unidades administrativas que les estén adscritas, en los órganos de gobierno y demás órganos colegiados en los que participe la Secretaría, y designar a sus suplentes; XIV. Participar, en su caso, en el Consejo de Planeación Energética, en el Comité Técnico de la Comisión Nacional de Energía, así como en los comités consultivos nacionales de normalización y cualquier otro órgano colegiado de su competencia; XV. Designar a las personas servidoras públicas subalternas, para representar a la Secretaría en los órganos de gobierno y demás órganos colegiados en los que ésta participe, cuando las disposiciones jurídicas aplicables no lo impidan; XVI. Tramitar y resolver los recursos administrativos que conforme a las disposiciones jurídicas les correspondan; XVII. Coordinar al interior de la Secretaría y en el ámbito de su competencia, las acciones relativas a la planeación y programación, así como, con las autoridades federales, estatales y municipales y proponer a la persona titular de la Secretaría criterios para su ejecución; XVIII. Proporcionar y requerir información y cooperación en el ámbito federal, estatal y municipal; XIX. Expedir copias certificadas de documentos que obren en los archivos de la unidad administrativa a su cargo; XX. Someter a la consideración de la persona titular de la Secretaría los estudios y análisis previos, así como los anteproyectos de instrumentos jurídicos, cuyo objeto sea crear, modificar, disolver, liquidar, extinguir, fusionar, enajenar o transferir entidades paraestatales del sector, con la opinión de la Unidad de Asuntos Jurídicos; XXI. Suscribir o celebrar en representación de la Secretaría, con la opinión de la Unidad de Asuntos Jurídicos, los documentos, actos e instrumentos jurídicos que procedan en el ámbito de su competencia, o los que les correspondan por virtud de delegación de facultades o por suplencia; XXII. Atender y resolver, dentro del ámbito de sus facultades, toda clase de asuntos que sean competencia de la Secretaría, siempre y cuando no formen parte de las facultades indelegables de la persona titular de la Secretaría, y XXIII. Las demás que les señalen otras disposiciones jurídicas aplicables y las que correspondan a sus unidades administrativas, así como las funciones que le encomiende su superior jerárquico. Sin perjuicio de lo dispuesto por el artículo 2, último párrafo del presente Reglamento, para el eficaz despacho de los asuntos a su cargo y para un mejor desempeño en el ejercicio de sus facultades, las personas titulares de las Subsecretarías y de la Unidad de Administración y Finanzas se pueden auxiliar de las personas titulares de jefatura de unidad, direcciones generales, y demás personal subalterno que se requiera en virtud de las necesidades del servicio, de conformidad con las disposiciones jurídicas aplicables. CAPÍTULO IV DE LAS FACULTADES DE LA PERSONA TITULAR DE LA UNIDAD DE ADMINISTRACIÓN Y FINANZAS","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LAS FACULTADES GENÉRICAS DE LAS PERSONAS TITULARES DE LAS SUBSECRETARÍAS Y DE LA UNIDAD","seccion_nombre":null,"orden":7},{"id":"b562b6eb-4e26-4198-a452-044cd074a9fc","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 7.","contenido":"- La persona titular de la Unidad de Administración y Finanzas tiene las facultades siguientes: I. Administrar los recursos financieros, humanos, materiales, servicios generales, tecnológicos y de gestión documental de la Secretaría, que asegure su eficiente utilización para el logro de las metas y objetivos institucionales; II. Determinar y emitir, conforme a las disposiciones jurídicas aplicables, las políticas, los instrumentos normativos y técnicos, así como los procedimientos de carácter administrativo que deban regir a las unidades administrativas y órganos administrativos desconcentrados de la Secretaría, para la gestión y ejecución de los servicios de apoyo administrativo en materia de planeación, programación, presupuesto, tecnologías de la información, recursos humanos, materiales, financieros, contabilidad, gestión documental y administración de archivos de la Secretaría; III. Coordinar el proceso de planeación, programación, presupuestación, control y evaluación del gasto, de las unidades administrativas y órganos administrativos desconcentrados de la Secretaría, así como de las entidades paraestatales sectorizadas a esta, y vigilar su ejercicio; IV. Someter a la consideración de la persona titular de la Secretaría, el anteproyecto de presupuesto anual de egresos de la dependencia, que asegure la consolidación de información presupuestaria de las unidades administrativas, órganos administrativos desconcentrados y entidades paraestatales sectorizadas, así como definir las directrices de la coordinación sectorial en materia presupuestaria; V. Coordinar y aprobar la formulación de los programas anuales de adquisiciones, arrendamientos y servicios, obra pública y servicios relacionados con las mismas, así como el programa anual de recursos materiales y servicios generales, de conformidad con las disposiciones normativas y políticas establecidas en la materia; VI. Impulsar, en el ámbito de su competencia, los mecanismos de colaboración institucionales con el sector coordinado, con el propósito de que la Secretaría cuente con la información financiera y presupuestal oportuna y suficiente; VII. Coordinar el ejercicio del gasto de las unidades administrativas y órganos administrativos desconcentrados de la Secretaría, así como consolidar su información, de conformidad con las disposiciones jurídicas aplicables; VIII. Definir y establecer los mecanismos de control presupuestario y ejercicio del gasto que fueren necesarios; IX. Someter a la aprobación de la persona titular de la Secretaría, las propuestas de modificación a la estructura orgánica y ocupacional; X. Someter a consideración de la persona titular de la Secretaría, el proyecto de Reglamento Interior de la Secretaría y sus modificaciones, previa opinión de la Unidad de Asuntos Jurídicos, así como el Manual de Organización General de la Secretaría, así como definir los criterios para la elaboración de manuales específicos de organización, de procedimientos, y de servicios al público; XI. Implementar la política de administración de personal y desarrollo organizacional; XII. Autorizar las constancias de los nombramientos de las personas servidoras públicas que desempeñen cargos dentro de la Secretaría y expedir los nombramientos del personal sujeto al servicio profesional de carrera; XIII. Acordar con la persona titular de la Secretaría las propuestas de condiciones generales de trabajo y, una vez aprobadas, difundirlas y promover su cumplimiento; XIV. Conducir las relaciones laborales de la Secretaría, los cambios de adscripción y la separación, de conformidad con las disposiciones jurídicas aplicables, así como designar y remover a las personas representantes de la Secretaría ante las comisiones mixtas, estableciendo las reglas de actuación de dichos representantes; XV. Establecer los mecanismos correspondientes con el fin de proveer los recursos necesarios para otorgar los premios, estímulos y recompensas previstos en la ley y en las Condiciones Generales de Trabajo, conforme a la disponibilidad presupuestaria; XVI. Elaborar, instruir, imponer y revocar medidas con motivo de incumplimiento a las obligaciones laborales en que incurran las personas servidoras publicas adscritas a la Secretaría, en coordinación con la Unidad de Asuntos Jurídicos; XVII. Elaborar, implementar y mantener actualizados los programas institucionales de capacitación para contribuir a la profesionalización, desarrollo y desempeño de las personas servidoras públicas adscritas de la Secretaría; asimismo, promover las acciones necesarias para el fortalecimiento de la seguridad e higiene en el trabajo; XVIII. Presidir los comités que por disposición jurídica, legal, reglamentaria o administrativa le correspondan, así como participar en los órganos colegiados de conformidad con las disposiciones jurídicas aplicables, y en su caso nombrar a sus suplentes; XIX. Establecer los mecanismos para dar cumplimiento a las políticas, bases y lineamientos en materia de adquisiciones, arrendamientos y servicios, obra pública y servicios relacionados con las mismas, así como para la contratación de los servicios de la Secretaría, atendiendo las disposiciones normativas aplicables en la materia; XX. Suscribir contratos, convenios y demás instrumentos jurídicos que determinen obligaciones a la Secretaría o que afecten su presupuesto, en representación de la Secretaría, y en su caso, determinar su modificación, rescisión, suspensión o terminación, previa opinión de la Unidad de Asuntos Jurídicos cuando se requiera. Esta facultad puede ser ejercida en forma indistinta por la persona titular de la Dirección General de Recursos Materiales y Servicios Generales; XXI. Establecer y coordinar la ejecución del Programa Interno de Protección Civil para salvaguardar el personal, instalaciones, bienes e información de la Secretaría, conforme con las disposiciones jurídicas aplicables; XXII. Coordinar en las unidades administrativas y órganos administrativos desconcentrados de la Secretaría, así como de las entidades paraestatales sectorizadas a esta, los programas transversales de control interno, ética e integridad, igualdad de género, no discriminación e inclusión, combate a la corrupción, mejora regulatoria y gestión documental y demás que se instrumenten en la Administración Pública Federal; XXIII. Coordinar la formulación y ejecución de programas vinculados a la estrategia de gobierno digital y automatización de la Secretaría, y brindar la asesoría, que en su caso requieran sus órganos administrativos desconcentrados, así como de las entidades paraestatales sectorizadas a esta; XXIV. Coordinar la integración y evaluar el cumplimiento del Plan Estratégico de Tecnologías de la Información y Comunicaciones de la Secretaría, y proporcionar el soporte técnico a la infraestructura de las unidades administrativas de la Secretaría; XXV. Fungir como responsable oficial de mejora regulatoria de la Secretaría ante la autoridad competente en materia de mejora regulatoria, de conformidad con las disposiciones jurídicas aplicables; XXVI. Establecer el sistema de comunicación interna, con la participación de la Dirección General de Comunicación Social de la Secretaría, conforme con las disposiciones jurídicas aplicables; XXVII. Solicitar y requerir información en el ámbito de su competencia a las unidades administrativas y órganos administrativos desconcentrados de la Secretaría, así como de las entidades paraestatales y empresas públicas del Estado sectorizadas a esta, con el fin de brindar el trámite y la gestión respectiva a sus solicitudes ante las autoridades correspondientes; XXVIII. Promover el cumplimiento de los Códigos de Ética y de Conducta de la Secretaría, así como instrumentar acciones para incorporar la perspectiva de género, integridad y prevención de conflictos de interés en la cultura organizacional; XXIX. Aprobar y verificar el cumplimiento del Programa de Seguridad y Salud en el Trabajo de la Secretaría; XXX. Constituir, de conformidad con las disposiciones jurídicas aplicables y dentro del ámbito de su competencia, los órganos colegiados que se requieran para el cumplimiento al objeto de la Secretaría y determinar las directrices para su funcionamiento y operación, y XXXI. Coordinar los programas y estrategias para la innovación, desarrollo administrativo, calidad de los procesos y organización interna de la Secretaría. CAPÍTULO V DE LAS FACULTADES GENÉRICAS DE LAS PERSONAS TITULARES DE LAS JEFATURAS DE UNIDAD Y DE LAS DIRECCIONES GENERALES","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LAS FACULTADES DE LA PERSONA TITULAR DE LA UNIDAD DE ADMINISTRACIÓN Y FINANZAS","seccion_nombre":null,"orden":8},{"id":"8c8430f2-8d8b-44fc-b483-c4f81aae0f26","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 8.","contenido":"- A las personas titulares de las jefaturas de Unidad y direcciones generales, corresponde originalmente el trámite y resolución de los asuntos competencia de las unidades administrativas que le sean adscritas, y tienen además, en el ámbito de sus respectivas competencias, las siguientes facultades: I. Ac ordar con su superior jerárquico el despacho de los asuntos que corresponda; II. Programar, organizar, dirigir, controlar y evaluar el funcionamiento de la unidad administrativa a su cargo; III. Revisar y supervisar, la integración de la agenda y el programa de mejora regulatoria, así como la elaboración de los proyectos de regulación y demás instrumentos jurídicos que contengan disposiciones en el ámbito de su competencia, y de los dictámenes de impacto presupuestario, organizacional y análisis de impacto regulatorio, cuando corresponda; IV. Proporcionar a la Secretaría de Hacienda y Crédito Público la información necesaria para la elaboración del Plan Nacional de Desarrollo y demás programas que derivan de éste; V. Revisar y aprobar el proyecto de programa anual de trabajo, anteproyecto anual de presupuesto, así como los proyectos de manuales de organización, de procedimientos y de servicios al público a su cargo; VI. Proponer a la persona superior jerárquica, la creación, reestructuración y eliminación de las unidades administrativas a su cargo; VII. Intervenir en la selección, nombramiento, desarrollo, capacitación, promoción y adscripción del personal a su cargo, así como autorizar los movimientos internos del personal conforme a las disposiciones jurídicas aplicables; VIII. Proponer y participar en la organización de cursos de capacitación, seminarios y conferencias; IX. Aprobar la información de trámites y servicios que se presten en su unidad administrativa, para su inscripción, actualización y baja en el medio que se señala en las disposiciones normativas en materia de mejora regulatoria, por conducto de la Unidad de Administración y Finanzas, y previa opinión de la Unidad de Asuntos Jurídicos; X. Participar, en el ámbito de su competencia, en los procesos de licitación pública y sus excepciones que lleve a cabo la Secretaría; XI. Suscribir contratos y convenios, en el ámbito de su competencia, con la opinión de la Unidad de Asuntos Jurídicos; XII. Suscribir los actos administrativos y demás documentos relativos al ejercicio de sus facultades o de las que le sean delegadas o les correspondan por suplencia; XIII. Proponer a su superior jerárquic o las disposiciones administrativas y cualquier otro acto administrativo de carácter general, en el ámbito de su competencia; XIV. Participar en los comités consultivos nacionales de normalización y, en su caso, presidirlos por designación de la persona superior jerárquica; XV. Expedir, modificar o cancelar las normas oficiales mexicanas, previa aprobación del Comité Consultivo Nacional de Normalización correspondiente, así como verificar su cumplimiento; XVI. Requerir información, solicitar opinión o apoyo técnico a dependencias, órganos administrativos desconcentrados y entidades paraestatales de la Administración Pública Federal, así como a empresas públicas del Estado, instituciones y organismos federales, cuando dicha información se requiera para el ejercicio de sus funciones; XVII. Solicitar a los Organismos de Evaluación de la Conformidad, Unidades de inspección, Laboratorios de ensayos y pruebas u Organismos de Certificación, aprobados o autorizados por la Secretaría, que efectúen revisiones a las instalaciones, equipos, procesos, métodos y cualquier otro relacionado con las actividades previstas en las disposiciones jurídicas aplicables; XVIII. Habilitar días y horas inhábiles para la práctica de notificaciones, actuaciones y diligencias administrativas, incluidas visitas de verificación o inspección, con base en las disposiciones jurídicas aplicables; XIX. Ordenar la práctica de notificaciones, actuaciones y diligencias administrativas, incluidas visitas de verificación o inspección, así como habilitar a personas notificadoras, inspectoras y verificadoras para realizarlas y facultarlas, cuando proceda, para imponer, ejecutar, modificar o revocar los actos administrativos previstos en las disposiciones jurídicas aplicables; XX. Tramitar y resolver los recursos administrativos que se interpongan en contra de las determinaciones de las personas servidoras públicas adscritas a la unidad administrativa a su cargo; XXI. Proporcionar, en tiempo y forma, la información y documentación necesarias, para que la Unidad de Asuntos Jurídicos cuente con los elementos para comparecer, instar o ejercer las acciones jurídicas ante autoridades administrativas y jurisdiccionales, incluida la destinada para elaborar informes previos y justificados que se deban rendir en los juicios de amparo y suscribir aquellos que les correspondan cuando sean señaladas como autoridades responsables; XXII. Verificar la correcta integración y clasificación del archivo de trámite y demás documentos que se tramiten en la unidad administrativa a su cargo, atendiendo a las disposiciones de la Ley General de Archivos; XXIII. Expedir copias certificadas de los documentos que obren en sus archivos cuando proceda o a petición de autoridad competente; XXIV. Coordinar la elaboración de los estudios y análisis previos que se requieran y, en su caso, elaborar los anteproyectos de instrumentos jurídicos, a efecto de crear, modificar, disolver, liquidar, extinguir, fusionar, enajenar o transferir entidades paraestatales sectorizadas; someterlos a consideración de su superior jerárquico, e intervenir, participar, dar seguimiento y, en su caso, ejercer, en el ámbito de su competencia, los actos que correspondan en el proceso respectivo; XXV. Representar, por designación expresa o previsión normativa a la Secretaría, por sí o a través de las personas titulares de las unidades administrativas que le estén adscritas, en los órganos de gobierno y demás órganos colegiados en los que participe la Secretaría, y designar a sus suplentes; XXVI. Proporcionar, cuando jurídicamente sea procedente, la información y documentación que les sea requerida, en los asuntos de su competencia; XXVII. Participar con la Dirección General de Asuntos Internacionales de la Secretaría, en la negociación y celebración de acuerdos internacionales, en el ámbito de competencia de la Secretaría; XXVIII. Participar, previo ac uerdo con su superior jerárquico , en foros y eventos nacionales relacionados con los asuntos de su competencia; XXIX. Ejercer en el territorio nacional, las facultades que este reglamento y los demás ordenamientos jurídicos aplicables les confieren; XXX. Realizar la evaluación de la conformidad de las normas oficiales mexicanas que expidan; definir los términos para la aprobación de los Organismos de Evaluación de la Conformidad, aprobar y revocar a las personas acreditadas para realizar dicha evaluación, en el ámbito de su competencia; XXXI. Requerir la exhibición de dictámenes, reportes técnicos, informes de pruebas, certificados o cualquier otro documento de evaluación de la conformidad, emitidos por los Organismos de Evaluación de la Conformidad, Unidades de inspección, Laboratorios de ensayos y pruebas u Organismos de certificación, aprobados por la Secretaría, en el ámbito de su competencia; XXXII. Requerir la información necesaria para el desarrollo de sus funciones, a toda persona física o moral que realice cualquiera de las actividades relacionadas con el sector energético en el ámbito de su competencia; XXXIII. Proponer a la persona titular de la Secretaría, la delegación de facultades indispensables en su personal para la adecuada atención de las funciones que tienen encomendadas, mediante acuerdo publicado en el Diario Oficial de la Federación, así como establecer los criterios que sean necesarios para el trámite y la resolución de los asuntos que les correspondan; XXXIV. Atender y resolver, dentro del ámbito de sus facultades, toda clase de asuntos que sean competencia de la Secretaría, siempre y que no formen parte de las facultades indelegables de la persona titular de la Secretaría; XXXV. Desempeñar las funciones que les designe la persona titular de la Secretaría ante representaciones diplomáticas o consulares, foros, organismos y mecanismos internacionales, a propuesta de la Dirección General de Asuntos Internacionales, y XXXVI. Las demás que les señalen otras disposiciones jurídicas aplicables y las que correspondan a sus áreas administrativas, así como las funciones que les encomiende su superior jerárquico. Sin perjuicio de lo dispuesto por el artículo 2, último párrafo del presente Reglamento, para el eficaz despacho de los asuntos a su cargo y para un mejor desempeño en el ejercicio de sus facultades, las personas titulares de Jefaturas de Unidad y Direcciones Generales se auxiliarán del personal subalterno que se requiera en virtud de las necesidades del servicio, de conformidad con las disposiciones jurídicas aplicables. CAPÍTULO VI DE LA SUBSECRETARÍA DE PLANEACIÓN Y TRANSICIÓN ENERGÉTICA Y SUS UNIDADES ADMINISTRATIVAS","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LAS FACULTADES GENÉRICAS DE LAS PERSONAS TITULARES DE LAS JEFATURAS DE UNIDAD Y DE LAS","seccion_nombre":null,"orden":9},{"id":"109ddd26-ec6c-4594-85f4-70e0e6f8612a","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 9.","contenido":"- Corresponde a la persona titular de la Subsecretaría de Planeación y Transición Energética el trámite y la resolución de los asuntos de su competencia y de las unidades administrativas que le estén adscritas, además tiene las facultades siguientes: I. Someter a consideración de la persona titular de la Secretaría la política energética del país en materia de planeación y transición energética; II. Participar en el Consejo de Planeación Energética y en el Comité Técnico de la Comisión Nacional de Energía; III. Coordinar el Sistema Nacional de Información Energética, con el apoyo del Consejo de Planeación Energética; IV. Someter a consideración de la persona titular de la Secretaría, los instrumentos de planeación de corto, mediano y largo plazo a los que se refiere la Ley de Planeación y Transición Energética y demás ordenamientos jurídicos aplicables; V. Coordinar y definir con las unidades administrativas y órganos administrativos desconcentrados de la Secretaría, así como de las entidades paraestatales y empresas públicas del Estado sectorizadas a esta, la elaboración de los instrumentos de planeación de corto, mediano y largo plazo a los que se refiere la Ley de Planeación y Transición Energética y demás ordenamientos jurídicos aplicables; VI. Asegurar que los instrumentos de planeación de mediano y largo plazo se actualicen con la periodicidad establecida en la Ley de Planeación y Transición Energética y demás ordenamientos jurídicos aplicables; VII. Someter a la consideración de la persona titular de la Secretaría, las políticas, planes, programas, estrategias y acciones en materia de eficiencia energética, transición energética y el uso de energías renovables, para reducir la pobreza energética, la descarbonización de los usos finales de la energía, la incorporación de tecnologías para la reducción de emisiones y del impacto ambiental, que propicien la economía circular y la sustentabilidad energética; VIII. Coordinar con la Comisión Nacional para el Uso Eficiente de la Energía la elaboración e implementación de políticas, planes, programas, estrategias y acciones en materia de eficiencia y sustentabilidad energética; IX. Someter a consideración de la persona titular de la Secretaría, previa opinión de la Unidad de Asuntos Jurídicos, la regulación en materia de transición energética y las políticas para la implementación de tecnologías habilitadoras y renovables emergentes en el ámbito de su competencia; X. Promover las acciones para la formación de recursos humanos especializados y la investigación científica relacionados con el desarrollo tecnológico y la innovación del sector energético incluyendo a sus órganos administrativos desconcentrados, así como de las entidades paraestatales y empresas públicas del Estado sectorizadas a esta; XI. Someter a la consideración de la persona titular de la Secretaría, los lineamientos para la integración de la política energética en las dependencias y entidades de la Administración Pública Federal e impulsar los proyectos de colaboración interinstitucionales necesarios; XII. Someter a la consideración de la persona titular de la Secretaría los lineamientos para el análisis estratégico del sector energético; XIII. Coordinar y dar seguimiento a los trabajos de la Comisión Intersecretarial de Cambio Climático, de conformidad con las atribuciones que le correspondan a la Secretaría; XIV. Someter a consideración de la persona titular de la Secretaría, previa opinión de la Unidad de Asuntos Jurídicos, los convenios y acuerdos con los tres órdenes de gobierno para la implementación de los proyectos de infraestructura estratégicos a fin de cumplir con la política energética nacional, así como con los acuerdos de concertación con los sectores público, social y privado para impulsar las energías renovables, en el ámbito de su competencia; XV. Coordinar con las entidades federativas y los municipios, estrategias y líneas de acción de los instrumentos de planeación de corto, mediano y largo plazo a los que se refiere la Ley de Planeación y Transición Energética y demás ordenamientos jurídicos aplicables para el desarrollo de los Proyectos de Infraestructura estratégicos necesarios para cumplir con la política energética nacional; XVI. Consolidar la información para integrar los proyectos de informes que rinden las persona s titulares del Ejecutivo Federal y de la Secretaría en materia energética; XVII. Someter a consideración del Comité de Asignaciones, Contratos y Permisos los proyectos de otorgamiento, prórroga, modificación, actualización, reasignación, revocación, caducidad y terminación de permisos o concesiones en materia de biocombustibles y geotermia, respectivamente, en términos de las atribuciones otorgadas a la Secretaría en la Ley de Biocombustibles, la Ley de Geotermia y demás ordenamientos jurídicos aplicables; XVIII. Formalizar el otorgamiento, prórroga, modificación, actualización, reasignación, suspensión, revocación, caducidad y terminación de los permisos y concesiones en materia de biocombustibles y geotermia, respectivamente, en términos de la Ley de Biocombustibles, la Ley de Geotermia y demás ordenamientos jurídicos aplicables, previa aprobación del Comité de Asignaciones, Contratos y Permisos; XIX. Autorizar la producción de Biocombustibles para actividades de investigación científica o tecnológica, de conformidad con lo establecido en la Ley de Biocombustibles y demás ordenamientos jurídicos aplicables; XX. Autorizar las actividades de Aprovechamiento Geotérmico Exento de conformidad con lo establecido en la Ley de Geotermia y demás ordenamientos jurídicos aplicables; XXI. Dirigir la integración de expedientes de los procedimientos administrativos por el presunto incumplimiento de obligaciones o por violaciones a la Ley de Planeación y Transición Energética, la Ley de Biocombustibles, la Ley de Geote r mia y demás disposiciones jurídicas aplicables; XXII. Someter a consideración del Comité de Asignaciones, Contratos y Permisos, a través de la Unidad de Asuntos Jurídicos, el inicio y resolución del procedimiento administrativo de sanción o por posibles incumplimientos, en términos de las atribuciones que se otorgan a la Secretaría en la Ley de Planeación y Transición Energética, la Ley de Biocombustibles, la Ley de Geotermia y demás ordenamientos jurídicos aplicables; XXIII. Conducir la administración del Fondo para la Transición Energética y el Aprovechamiento Sustentable de la Energía, así como del Fondo de Servicio Universal Energético; XXIV. Vigilar la administración de los recursos destinados a proyectos de investigación, desarrollo tecnológico e innovación que incluya la formación de recursos humanos en materia de Hidrocarburos y Sustentabilidad Energética, en términos de la normativa aplicable; XXV. Informar a la persona titular de la Secretaría, los programas o proyectos que sean sujetos de apoyo del Financiamiento para el Aprovechamiento Sustentable de la Energía a que hace referencia la Ley de Planeación y Transición Energética y demás ordenamientos jurídicos aplicables; XXVI. Coordinar con el organismo público descentralizado que determine el Ejecutivo Federal en términos de las disposiciones aplicables, los mecanismos para alcanzar los objetivos en materia de transición energética en los procesos de exploración, explotación, beneficio y aprovechamiento de litio, conforme a la Ley de Planeación y Transición Energética y demás ordenamientos aplicables; XXVII. Coordinar asuntos en materia de cooperación internacional técnica y financiera, dentro del ámbito de sus facultades, así como dar seguimiento a las acciones desarrolladas por las Direcciones Generales a su cargo, y XXVIII. Supervisar el desempeño de los institutos de investigación del sector energético y promover las acciones para el fortalecimiento de sus capacidades.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LA SUBSECRETARÍA DE PLANEACIÓN Y TRANSICIÓN ENERGÉTICA Y SUS UNIDADES ADMINISTRATIVAS","seccion_nombre":null,"orden":10},{"id":"708670e6-1cc3-470d-ba51-ce4b40b3bdc6","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 10.","contenido":"- Corresponde a la Unidad del Sistema Nacional de Información Energética, el ejercicio de las atribuciones siguientes: I. Implementar y administrar el Sistema Nacional de Información Energética con el apoyo del Consejo de Planeación Energética; II. Emitir las disposiciones para la entrega y actualización de información al Sistema Nacional de Información Energética; III. Implementar los mecanismos para el acopio, resguardo, seguridad, confidencialidad, organización e integración, de los registros e información geoespacial del Sistema Nacional de Información Energética; IV. Emitir opinión a sus órganos administrativos desconcentrados, así como de las entidades paraestatales y empresas públicas del Estado sectorizadas a esta, sobre la emisión de formatos y requisitos para la recopilación de registros de información en forma electrónica; V. Celebrar acuerdos para recibir información estratégica del sector energético, de actores del sector público, privado y social; VI. Publicar la información del Sector Energético de acuerdo con la política energética Nacional; VII. Coordinar el apoyo técnico para la actualización y operación del Sistema Nacional de Información Energética; VIII. Aprobar los requerimientos de seguridad de la información y de infraestructura del Sistema Nacional de Información Energética, para su adecuada integración con los diferentes sistemas de información del Sector Energético; IX. Aprobar las políticas y estándares para la gestión de la confidencialidad de los registros e información geoespacial; X. Coordinar la integración y actualización de información en materia energética que requiera la persona titular de la Subsecretaria de Planeación y Transición Energética, para integrar propuestas de soluciones estratégicas a los problemas identificados en el Consejo de Planeación Energética; XI. Aprobar la metodología para el análisis de la información estadística del Sistema Nacional de Información Energética; XII. Coordinar el desarrollo de análisis estadísticos y metodologías sobre actividades competencia del Sistema Nacional de Información Energética, con el fin de poner a disposición de las personas interesadas la información relevante del sector; XIII. Coadyuvar con la Dirección General de Planeación e Integración Energética en la calidad de la información utilizada para la elaboración del Balance Nacional de Energía, así como en los instrumentos de planeación de corto, mediano y largo plazo a los que se refiere la Ley de Planeación y Transición Energética; XIV. Supervisar la elaboración y actualización del Atlas Nacional de Zonas con potencial de Energías Renovables; XV. Emitir opinión a la Subsecretaria de Hidrocarburos para el desarrollo de metodologías orientadas a estimar las reservas, la relación entre producción y reservas, los recursos contingentes y prospectivos a los que hace referencia la Ley del Sector Hidrocarburos; XVI. Coordinar el seguimiento de la información y los resultados para la realización de estudios de coyuntura que permitan el adecuado desarrollo de la agenda del Consejo de Planeación Energética; XVII. Supervisar la atención de solicitudes de información relacionadas con el Sistema Nacional de Información Energética en términos de la normatividad aplicable, y XVIII. Evaluar los incumplimientos en la entrega de información que conforme al Sistema Nacional de Información Energética sea considerada de interés nacional.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LA SUBSECRETARÍA DE PLANEACIÓN Y TRANSICIÓN ENERGÉTICA Y SUS UNIDADES ADMINISTRATIVAS","seccion_nombre":null,"orden":11},{"id":"845462d3-f6e6-4093-863d-ee4fad616751","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo   11.","contenido":"- Corresponde a la Dirección General de Registros e Información Geoespacial del Sistema Nacional de Información Energética, el ejercicio de las atribuciones siguientes: I. Emitir las disposiciones para la entrega y actualización de los registros e información geoespacial del Sistema Nacional de Información Energética; II. Coordinar el acopio, resguardo y uso de los registros e información geoespacial; III. Elaborar y publicar los registros e información geoespacial del sector energético en el marco del Sistema Nacional de Información Energética; IV. Actualizar los registros e información geoespacial del sector energético; V. Coadyuvar con sus órganos administrativos desconcentrados, así como de las entidades paraestatales y empresas públicas del Estado sectorizadas a esta, en la emisión de formatos y requisitos para la recopilación de registros e información geoespacial, en forma electrónica; VI. Elaborar y actualizar el Atlas Nacional de Zonas con potencial de Energías Renovables; VII. Coadyuvar con la Subsecretaría de Hidrocarburos en la sistematización de registros e información geoespacial para estimar las reservas y los recursos contingentes prospectivos a los que hace referencia la Ley del Sector Hidrocarburos; VIII. Determinar los requerimientos de seguridad de la información y de infraestructura del Sistema Nacional de Información Energética, para su adecuada integración con los diferentes sistemas de información del Sector Energético; IX. Implementar las políticas y estándares para la gestión de la confidencialidad de los registros e información geoespacial; X. Proponer, dirigir y actualizar la infraestructura y los servicios en materia de registros e información geoespacial que den soporte a las funciones sustantivas del Sistema Nacional de Información Energética; XI. Proponer, dirigir e implementar el desarrollo de soluciones de software en materia de registros e información geoespacial; XII. Proponer y desarrollar tableros institucionales con información geoespacial, para informar al Consejo de Planeación Energética de forma visual, interactiva y mediante indicadores de desempeño , el estado que guarda el Sector Energético Nacional; XIII. Establecer lineamientos de mejora continua que impulsen el aprovechamiento de las tecnologías de la información y comunicaciones; XIV. Implementar lineamientos de mejora continua con base en la mejor ciencia y el estado del arte de las tecnologías de la información y comunicaciones; XV. Asignar la atención de las asesorías técnicas a las áreas del Sistema Nacional de Información Energética, para asegurar una gestión eficiente de los procesos de registros e información geoespacial; XVI. Coadyuvar con la Dirección General de Planeación e Integración Energética en la elaboración de los instrumentos de planeación, establecidos en la Ley de Planeación y Transición Energética y demás ordenamientos jurídicos aplicables, en el ámbito de su competencia, y XVII. Coadyuvar con la Dirección General de Planeación e Integración Energética, en el seguimiento a las metas, indicadores y Proyectos de Infraestructura estratégicos necesarios para cumplir con la política energética nacional, de los instrumentos de planeación establecidos en la Ley de Planeación y Transición Energética y demás ordenamientos jurídicos aplicables.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LA SUBSECRETARÍA DE PLANEACIÓN Y TRANSICIÓN ENERGÉTICA Y SUS UNIDADES ADMINISTRATIVAS","seccion_nombre":null,"orden":12},{"id":"d0bee46f-147a-4030-8d26-f3208dd77094","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 12.","contenido":"- Corresponde a la Dirección General de Metodologías y Estadísticas del Sistema Nacional de Información Energética, el ejercicio de las atribuciones siguientes: I. Emitir las disposiciones de la metodología para el análisis estadístico de la información del sistema energético; II. Elaborar la metodología para el análisis de la información estadística del Sistema Nacional de Información Energética; III. Elaborar y publicar las estadísticas del sector energético, incluyendo en las páginas de internet oficiales; IV. Actualizar las estadísticas del sector energético; V. Emitir opiniones técnicas al Consejo de Planeación Energética, en materia de su competencia; VI. Coordinar la elaboración de informes, proyectos, análisis, investigaciones, estudios o documentos que conforme a su competencia les sean requeridos por el Consejo de Planeación Energética; VII. Coadyuvar con la Dirección General de Planeación e Integración Energética en la elaboración de los instrumentos de planeación, establecidos en la Ley de Planeación y Transición Energética y demás ordenamientos jurídicos aplicables, en el ámbito de su competencia; VIII. Coadyuvar con la Dirección General de Planeación e Integración Energética, en el seguimiento a las metas, indicadores y Proyectos de Infraestructura estratégicos necesarios para cumplir con la política energética nacional, de los instrumentos de planeación establecidos en la Ley de Planeación y Transición Energética y demás ordenamientos jurídicos aplicables; IX. Establecer lineamientos de mejora continua para la sistematización de estadísticas del Sistema Nacional de Información Energética; X. Implementar lineamientos de mejora continua con base en la mejor ciencia y el estado del arte en la sistematización de estadísticas; XI. Desarrollar las metodologías para estimar el potencial técnico y económico de los recursos de energía renovable para la generación de electricidad y aplicaciones térmicas; XII. Coadyuvar con la Subsecretarí a de Hidrocarburos en el desarrollo de metodologías para estimar las reservas, la relación entre producción y reservas, los recursos contingentes y prospectivos a los que hace referencia la Ley del Sector Hidrocarburos, y X III . Desarrollar y actualizar los catálogos de tecnologías y registros con la información sobre parámetros técnicos, de operación, gastos e inversiones asociados a los instrumentos de planeación de corto, mediano y largo plazo a los que se refiere la Ley de Planeación y Transición Energética y demás ordenamientos jurídicos aplicables.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LA SUBSECRETARÍA DE PLANEACIÓN Y TRANSICIÓN ENERGÉTICA Y SUS UNIDADES ADMINISTRATIVAS","seccion_nombre":null,"orden":13},{"id":"6c21d7bf-425f-444d-b289-920436e6a940","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 13.","contenido":"- Corresponde a la Dirección General de Planeación e Integración Energética, el ejercicio de las atribuciones siguientes: I. Aplicar los ordenamientos legales y demás normas jurídicas aplicables en materia de planeación energética y coadyuvar al procesamiento de la información del Sistema Nacional de Información Energética, así como elaborar y dar seguimiento a los proyectos de políticas y programas en dichas materias; II. Coordinar la elaboración de los instrumentos de planeación de corto, mediano y largo plazo a los que se refiere la Ley de Planeación y Transición Energética y demás ordenamientos jurídicos aplicables, con el apoyo de las Subsecretarías de Electricidad y la Subsecretaría de Hidrocarburos de la Secretaría, sus órganos administrativos desconcentrados, así como de las entidades paraestatales y empresas públicas del Estado sectorizadas a esta, que participen en el Consejo de Planeación Energética, así como otras unidades técnicas y administrativas de la Secretaría; III. Coordinar el desarrollo de lineamientos y metodologías para la modelación de las proyecciones de oferta y demanda del sector energético en horizontes de mediano y largo plazo a los que hace referencia la Ley de Planeación y Transición Energética y demás ordenamientos jurídicos aplicables, así como para el análisis técnico y económico de los Proyectos de Infraestructura estratégicos; IV. Analizar modelos y proponer, con base en la mejor ciencia disponible y el estado del arte, aquellos para su uso en la elaboración de los instrumentos de planeación de corto, mediano y largo plazo a los que se refiere la Ley de Planeación y Transición Energética y demás ordenamientos jurídicos aplicables; V. Dirigir propuestas y el desarrollo de estudios económicos, financieros y de análisis relacionados con el sector energético; VI. Coordinar la integración de las opiniones del Consejo de Planeación Energética, en los ejercicios de modelación de los Proyectos de Infraestructura estratégicos necesarios para cumplir con la política energética nacional a los que hace referencia la Ley del Sector Eléctrico, la Ley del Sector Hidrocarburos y demás ordenamientos jurídicos aplicables; VII. Coadyuvar con la Unidad del Sistema Nacional de Información Energética, en el seguimiento a temas prioritarios y estratégicos del Consejo de Planeación Energética; VIII. Integrar y consolidar el Programa Sectorial de Energía para su gestión ante la Secretaría de Hacienda y Crédito Público, así como de los reportes de avance de las metas que en él se incluyen, de conformidad con la normativa aplicable; IX. Participar en la formulación de los informes de logros, de avance y resultados del Plan Nacional de Desarrollo, así como llevar a cabo la revisión periódica del programa sectorial, y demás programas derivados del referido Plan; X. Coordinar y concertar acciones, en materia energética, con los gobiernos de las entidades federativas, los municipios, sus órganos administrativos desconcentrados, así como de las entidades paraestatales y empresas públicas del Estado sectorizadas a esta, así como con los sectores social y privado, para integrar y consolidar el programa sectorial y demás programas derivados del Plan Nacional de Desarrollo; XI. Integrar la información para elaborar los proyectos de informes de labores anuales que rinde la persona titular del Ejecutivo Federal al Congreso de la Unión, sobre el estado general que guarda la administración pública federal y sobre las acciones y resultados de la ejecución del Plan Nacional de Desarrollo y el programa sectorial, así como de los proyectos de informes que la persona titular de la Secretaría presenta al Congreso de la Unión respecto del estado que guarda el sector energético; XII. Coordinar la participación de la Secretaría, sus órganos administrativos desconcentrados, así como de las entidades paraestatales y empresas públicas del Estado sectorizadas a esta, en el Sistema Nacional de Información Estadística y Geográfica, y actualizar la Información de Interés Nacional e indicadores clave; XIII. Coadyuvar con el Sistema Nacional de Información Energética en la Integración de los requerimientos de información en materia de estadística energética que realicen los organismos internacionales y participar en los grupos de trabajo y organismos, en el ámbito de su competencia, en coordinación con la Dirección General de Asuntos Internacionales; XIV. Elaborar y publicar el Balance Nacional de Energía con escenarios prospectivos de mediano plazo como lo establece la Ley de Planeación y Transición Energética y demás ordenamientos jurídicos aplicables; XV. Coordinar la aplicación de los lineamientos para la formulación de planes y programas del sector, derivados del Plan Nacional de Desarrollo y elaborar los mecanismos para su seguimiento, supervisión y ejecución de acciones e integrar los reportes que se generen de los mismos, y XVI. Coordinar el seguimiento a la planeación de los Proyectos de Infraestructura estratégicos necesarios para cumplir con la política energética nacional, de los instrumentos de planeación establecidos en la Ley de Planeación y Transición Energética y demás disposiciones jurídicas aplicables, en el ámbito de sus atribuciones.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LA SUBSECRETARÍA DE PLANEACIÓN Y TRANSICIÓN ENERGÉTICA Y SUS UNIDADES ADMINISTRATIVAS","seccion_nombre":null,"orden":14},{"id":"ee7e66bf-8b86-4005-b92e-e9ef70e11339","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 14.","contenido":"- Corresponde a la Dirección General de Energías Renovables, el ejercicio de las atribuciones siguientes: I. Aplicar los ordenamientos legales y demás normas jurídicas, cuyas disposiciones regulen los biocombustibles, geotermia, y en general las energías renovables, así como elaborar y evaluar proyectos de políticas, programas, disposiciones técnicas, económicas, sociales y administrativas en dichas materias; II. Coadyuvar con la Dirección General de Transición Energética, en los temas relacionados con otras tecnologías emergentes de energías renovables; III. Coadyuvar con la Dirección General de Planeación e Integración Energética en la elaboración de los instrumentos de planeación, establecidos en la Ley de Planeación y Transición Energética y demás disposiciones jurídicas aplicables, en el ámbito de su competencia; IV. Coadyuvar con la Dirección General de Planeación e Integración Energética, en el seguimiento a las metas, indicadores y Proyectos de Infraestructura estratégicos necesarios para cumplir con la política energética nacional, de los instrumentos de planeación establecidos en la Ley de Planeación y Transición Energética y demás disposiciones jurídicas aplicables; V. Coordinar el registro de permisos y autorizaciones, y aplicar las atribuciones que se otorgan a la Secretaría en la Ley de Biocombustibles, la Ley de Geotermia y demás disposiciones jurídicas aplicables; VI. Elaborar el Inventario Nacional y el Catálogo de Tecnologías de Energías Renovables; VII. Coadyuvar con las Direcciones Generales de Registros e información geoespacial y de metodologías y estadísticas del Sistema Nacional de Información Energética en la elaboración y actualización del Atlas Nacional de Zonas con potencial de Energías Renovables; VIII. Proponer la celebración de convenios y acuerdos de coordinación y concertación de acciones con los gobiernos de las entidades federativas y con los municipios en lo referente a los programas nacionales y regionales para impulsar los biocombustibles, la geotermia y en general las energías renovables, en el ámbito de su competencia; IX. Proponer la celebración de acuerdos de concertación con los sectores público, social y privado, en el ámbito de su competencia; X. Coordinar las acciones, planes, proyectos y programas, que utilicen energías renovables para la reducción de la Pobreza Energética; XI. Regular y vigilar el cumplimiento de las condiciones técnicas, así como de las demás normas relacionadas con la producción de biocombustibles; XII. Someter a consideración de la persona titular de la Subsecretaría de Planeación y Transición Energética o, en su caso, del Comité de Asignaciones, Contratos y Permisos los proyectos de otorgamiento, prórroga, modificación, actualización, reasignación, revocación, caducidad y terminación de permisos o concesiones en materia de biocombustibles y geotermia, respectivamente, en términos de las atribuciones otorgadas a la Secretaría en la Ley de Biocombustibles, la Ley de Geotermia y demás ordenamientos jurídicos aplicables; XIII. Formalizar el otorgamiento, prórroga, modificación, actualización, reasignación, suspensión, revocación, caducidad y terminación de los permisos y t í tulos concesiones en materia de biocombustibles y geotermia, previa aprobación del Comité de Asignaciones, Contratos y Permisos; XIV. Autorizar la producción de Biocombustibles para actividades de investigación científica o tecnológica, de conformidad con lo establecido en la Ley de Biocombustibles y demás ordenamientos jurídicos aplicables; XV. Autorizar las actividades de Aprovechamiento Geotérmico Exento de conformidad con lo establecido en la Ley de Geotermia y demás ordenamientos jurídicos aplicables; XVI. Ejercer las facultades de verificación previstas en la Ley de Geotermia, la Ley de Biocombustibles, sus reglamentos y demás disposiciones jurídicas aplicables; XVII. Imponer las medidas de seguridad o precautorias en el ejercicio de sus facultades de inspección, supervisión y vigilancia de conformidad con lo establecido en la Ley de Biocombustibles, la Ley de Geotermia y demás ordenamientos jurídicos aplicables; XVIII. Coordinar la integración de expedientes de los procedimientos administrativos por el presunto incumplimiento de obligaciones o por violaciones a la Ley de Planeación y Transición Energética, la Ley de Biocombustibles, la Ley de Geotermia y demás disposiciones jurídicas aplicables; XIX. Promover y desarrollar programas para la adopción y desarrollo de tecnologías y prácticas de aprovechamiento térmico a través de biocombustibles, y XX. Fortalecer el aprovechamiento y seguimiento a los usos diversos de la geotermia en los distintos sectores productivos del país.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LA SUBSECRETARÍA DE PLANEACIÓN Y TRANSICIÓN ENERGÉTICA Y SUS UNIDADES ADMINISTRATIVAS","seccion_nombre":null,"orden":15},{"id":"f241ab99-d63a-4916-99a3-9356b02c5104","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 15.","contenido":"- Corresponde a la Dirección General de Eficiencia y Sustentabilidad Energética, el ejercicio de las atribuciones siguientes: I. Aplicar los ordenamientos legales y demás normas jurídicas aplicables, que faculten a la Secretaría en materias de eficiencia energética, uso de energías renovables y descarbonización de los usos finales de la energía, incorporación de tecnologías para la reducción de emisiones y de impacto ambiental, que propicien la economía circular, así como la sustentabilidad energética; II. Emitir los criterios aplicables a la fracción anterior; así como elaborar y evaluar políticas y programas en dichas materias; III. Conjuntar, integrar y elaborar propuestas para el programa de normalización, en el ámbito de su competencia; IV. Coadyuvar con la Dirección General de Planeación e Integración Energética en la elaboración de los instrumentos de planeación, establecidos en la Ley de Planeación y Transición Energética y otras disposiciones jurídicas aplicables, en el ámbito de su competencia; V. Coadyuvar con la Dirección General de Planeación e Integración Energética, en el seguimiento a las metas e indicadores para cumplir con la política energética nacional en materia de eficiencia energética, el uso de energías renovables y descarbonización de los usos finales de la energía; VI. Coordinar con la Comisión Nacional para el Uso Eficiente de la Energía las actividades del sector en materia de eficiencia energética, promoción y elaboración de políticas para el uso eficiente de la energía en los usos finales, y la incorporación de tecnologías para el ahorro y uso eficiente de la energía que propicien la economía circular; VII. Coadyuvar con la Dirección General de Planeación e Integración Energética, en el seguimiento a las metas e indicadores para cumplir con la política energética nacional en materia de tecnologías para la reducción de emisiones y de impacto ambiental y que propicien la sustentabilidad energética; VIII. Coordinar con la Comisión Nacional para el Uso Eficiente de la Energía la celebración de convenios y acuerdos, según corresponda, con los tres niveles de gobiernos para promover una gobernanza efectiva en materia de eficiencia energética, promoción y elaboración de políticas para el uso eficiente de la energía en los usos finales, y la incorporación de tecnologías para el ahorro y uso eficiente de la energía que propicien la sustentabilidad energética; IX. Celebración de convenios y acuerdos de coordinación y concertación, según corresponda, con los sectores social y privado para promover una gobernanza efectiva en materia de eficiencia energética, promoción y elaboración de políticas para el uso eficiente de la energía en los usos finales, y la incorporación de tecnologías para el ahorro y uso eficiente de la energía que propicien la sustentabilidad energética; X. Participar con la Secretaría de Medio Ambiente y Recursos Naturales, en los asuntos de mitigación y adaptación a los efectos negativos del cambio climático con relación a la infraestructura energética, en materia de uso eficiente de la energía y de la sustentabilidad energética; XI. Promover y desarrollar programas para impulsar el uso de tecnologías energéticamente eficientes y bajas en emisiones en aplicaciones térmicas; XII. Promover y desarrollar programas para impulsar tecnologías que aprovechen residuos como plásticos, llantas, coque y otras tecnologías para la producción de energía limpia, y XIII. Coadyuvar con el Sistema Nacional de Información Energética en la Integración de los requerimientos en materia de estadística relacionada con eficiencia energética que soliciten los organismos internacionales.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LA SUBSECRETARÍA DE PLANEACIÓN Y TRANSICIÓN ENERGÉTICA Y SUS UNIDADES ADMINISTRATIVAS","seccion_nombre":null,"orden":16},{"id":"fd0473b2-4536-4c25-9f85-2eff043291ae","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 16.","contenido":"- Corresponde a la Dirección General de Transición Energética, el ejercicio de las atribuciones siguientes: I. Someter a consideración de la persona titular de la Subsecretaria de Planeación y Transición Energética, la regulación en materia de transición energética, las políticas y modalidades para la implementación de tecnologías habilitadoras y renovables emergentes, en el ámbito de su competencia; II. Asegurar la factibilidad técnica de los proyectos regulatorios y de política pública en materia de transición energética que se presenten a la persona titular de la Subsecretaría de Planeación y Transición Energética, para su aprobación, mediante el uso de diversas metodologías y evaluación de las mejores prácticas internacionales; III. Definir las acciones tendientes a fomentar y promover la transición energética, mediante un marco regulatorio y de políticas públicas adecuado para la entrada de tecnologías habilitadoras y renovables emergentes; IV. Asegurar la actualización y mejora continua de la regulación, disposiciones administrativas de carácter general y políticas públicas en materia de transición energética; V. Asistir en los actos que le sean turnados por la persona titular de la Subsecretaría de Planeación y Transición Energética, en lo relacionado con el Comité Técnico de la Comisión Nacional de Energía; VI. Asegurar que la persona titular de la Subsecretaría de Planeación y Transición Energética, cuente con la información y la documentación para su participación en el Comité Técnico de la Comisión Nacional de Energía; VII. Participar con la Secretaría de Medio Ambiente y Recursos Naturales y otras áreas técnicas de la Secretaría, en el desarrollo de metodologías para el cálculo del factor de emisión del Sistema Eléctrico Nacional; VIII. Coadyuvar con la Secretaría del Medio Ambiente y Recursos Naturales en el establecimiento de las obligaciones de reducción de emisiones contaminantes relativas al sector eléctrico; IX. Elaborar la metodología para valorar las externalidades asociadas a la generación de electricidad; X. Determinar con la Secretaría de Medio Ambiente y Recursos Naturales otras tecnologías que se consideran energías limpias; XI. Elaborar las disposiciones de carácter general en materia de Certificados de Energías Limpias, transición energética y descarbonización del Sector eléctrico; XII. Elaborar los requisitos para la trazabilidad y adquisición de Certificados de Energías Limpias; XIII. Revisar y ajustar los requisitos para la adquisición de Certificados de Energías Limpias, conforme a lo establecido en la Ley del Sector Eléctrico y demás disposiciones jurídicas aplicables, y XIV. Coadyuvar sus órganos administrativos desconcentrados, así como de las entidades paraestatales y empresas públicas del Estado sectorizadas a esta y con las unidades administrativas de la Secretaría, respecto a los Certificados de Energías Limpias, créditos de carbono, bonos e impuestos verdes, así como otros incentivos relacionados con tecnologías habilitadoras y emergentes de transición, en el ámbito de su competencia.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LA SUBSECRETARÍA DE PLANEACIÓN Y TRANSICIÓN ENERGÉTICA Y SUS UNIDADES ADMINISTRATIVAS","seccion_nombre":null,"orden":17},{"id":"dfdfed8c-76a0-4d2f-a41b-644351da30b8","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 17.","contenido":"- Corresponde a la Dirección General de Desarrollo Tecnológico y Acceso a la Energía, el ejercicio de las atribuciones siguientes: I. Aplicar los ordenamientos legales y demás normas jurídicas que regulen la investigación científica, el desarrollo tecnológico, la innovación y la formación de recursos humanos especializados en el sector energético y emitir los criterios de aplicación, así como elaborar y evaluar los proyectos de políticas y programas en dichas materias; II. Evaluar y determinar, en el ámbito de su competencia, las áreas de oportunidad que afronta el sector energético, a corto, mediano y largo plazo; III. Identificar, en el ámbito de su competencia, las áreas que tendrán mayor desarrollo y que requerirán de mayor inversión de recursos humanos especializados y desarrollo tecnológico en el sector energético; IV. Promover y difundir acciones y programas con la finalidad de incentivar el desarrollo de la investigación científica, el desarrollo tecnológico y la innovación, en materia de hidrocarburos y sustentabilidad energética y la participación en los comités técnicos de estandarización por competencias; V. Gestionar la obtención de recursos para financiar proyectos con el objetivo de satisfacer las necesidades de desarrollo tecnológico y formación de recursos humanos especializados del sector energético y, particularmente, de las empresas y organismos del estado; VI. Evaluar y dar seguimiento a las acciones para la formación de recursos humanos especializados y el fomento a la investigación científica relacionados con el desarrollo tecnológico y la innovación del sector energético; VII. Coordinar las acciones para el apoyo de las actividades de investigación científica, de desarrollo tecnológico e innovación en materia de sustentabilidad energética e hidrocarburos; VIII. Coordinar los recursos que se transfieran del Fondo Mexicano del Petróleo para la Estabilidad y el Desarrollo para el apoyo de proyectos de investigación científica, desarrollo tecnológico e innovación que incluya la formación de recursos humanos en materia de Hidrocarburos y Sustentabilidad Energética; IX. Conducir y coordinar la implementación de las políticas de investigación científica, desarrollo tecnológico e innovación, en las áreas de su competencia; X. Representar a la Secretaría en temas relacionados con la Secretaría de Ciencia, Humanidades, Tecnología e Innovación, que incidan en el ámbito de su competencia; XI. Dar seguimiento al desempeño de los institutos de investigación del sector energético y promover su fortalecimiento; XII. Administrar y coordinar el Fondo de Servicio Universal Energético, para la reducción de la pobreza energética; XIII. Administrar y coordinar el Fondo para la Transición Energética y el Aprovechamiento Sustentable de la Energía para contribuir al cumplimiento de la Estrategia Nacional de Transición Energética y la reducción de la pobreza energética; XIV. Desarrollar metodologías, directrices, encuestas e investigación para el diagnóstico de la pobreza energética y la evaluación de políticas públicas en la materia, y XV. Coordinar, formular e implementar políticas para reducir la pobreza energética en coordinación con otras áreas de la Secretaría y otras dependencias de la Administración Pública Federal. CAPÍTULO VII DE LA SUBSECRETARÍA DE ELECTRICIDAD Y SUS UNIDADES ADMINISTRATIVAS","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LA SUBSECRETARÍA DE PLANEACIÓN Y TRANSICIÓN ENERGÉTICA Y SUS UNIDADES ADMINISTRATIVAS","seccion_nombre":null,"orden":18},{"id":"96faa4a5-6a21-4361-8413-463bdfa213e7","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 18.","contenido":"- Corresponde a la persona titular de la Subsecretaría de Electricidad el trámite y la resolución de los asuntos de su competencia y de las unidades administrativas que le estén adscritas, además tiene las facultades siguientes: I. Participar en el establecimiento de la política energética del país; II. Proponer la política energética del país en materia de energía eléctrica; III. Formular mecanismos de coordinación con la Comisión Nacional de Energía, el Centro Nacional de Control de Energía, el Centro Nacional de Control de Gas Natural, y las demás autoridades relevantes para el sector eléctrico; IV. Establecer la política en materia de eficiencia, calidad, confiabilidad, continuidad, seguridad y sostenibilidad en el Sistema Eléctrico Nacional, incluyendo los criterios para establecer el equilibrio entre estos objetivos; V. Conducir y coordinar el proceso de planeación del Sistema Eléctrico Nacional; VI. Conducir y coordinar la elaboración del Plan de Desarrollo del Sector Eléctrico; VII. Desarrollar los programas vinculantes para la instalación y retiro de centrales eléctricas tendientes a satisfacer las necesidades del país; VIII. Autorizar los programas de ampliación y modernización de la Red Nacional de Transmisión y de las Redes Generales de Distribución que sean sometidos por el Centro Nacional de Control de Energía, la transportista y la distribuidora y solicitar cambios a los mismos, con la opinión que, en su caso emita la Comisión Nacional de Energía; IX. Instruir a la empresa pública del Estado, Comisión Federal de Electricidad, la ejecución de los proyectos contenidos en los programas vinculantes de ampliación y modernización de la Red Nacional de Transmisión y las Redes Generales de Distribución, así como dar seguimiento de su ejecución hasta su entrada en operación; X. Establecer los términos de separación legal establecidos en la Ley del Sector Eléctrico, así como vigilar su cumplimiento para los particulares; XI. Autorizar y dar seguimiento a los proyectos estratégicos y de infraestructura necesarios para cumplir con la política energética nacional en materia de electricidad; XII. Emitir opinión sobre las reglas y operación del Mercado Eléctrico Mayorista; XIII. Participar en la elaboración de instrumentos, obligaciones, criterios, convenios y requisitos para la adquisición y otorgamiento de Certificados de Energías Limpias para dar cumplimiento a la Ley del Sector Eléctrico y demás instrumentos jurídicos aplicables; XIV. Participar en el establecimiento de las metas de transición energética, descarbonización en el sector eléctrico, así como en los compromisos internacionales en la materia; XV. Elaborar y publicar un informe pormenorizado anual sobre el desempeño y las tendencias del sector eléctrico nacional; XVI. Constituir y participar en el comité de evaluación del desempeño del Centro Nacional de Control de Energía y del Mercado Eléctrico Mayorista; XVII. Coordinar, con la Comisión Nacional de Energía, la determinación de las tarifas reguladas de conformidad con la Ley del Sector Eléctrico; XVIII. Participar en la emisión de las políticas y lineamientos en materia de redes eléctricas inteligentes, generación, electromovilidad, sistemas de almacenamiento de energía eléctrica y cualquier otra de conformidad con el marco jurídico aplicable; XIX. Dirigir los actos, estudios e investigaciones sobre la eficiencia, calidad, continuidad, accesibilidad, seguridad, confiabilidad y sostenibilidad del Sistema Eléctrico Nacional; XX. Verificar y requerir la presentación de información e informes y citar a comparecer a los integrantes del sector eléctrico, a fin de supervisar y vigilar, en el ámbito de su competencia, el cumplimiento de las disposiciones jurídicas aplicables; XXI. Definir los mecanismos bajo los cuales los integrantes del sector eléctrico deben colaborar dentro de los pequeños sistemas eléctricos, a fin de prestar el suministro eléctrico en condiciones de calidad, continuidad, accesibilidad, seguridad, confiabilidad y sostenibilidad; XXII. Realizar, de forma conjunta con la Secretaría de Economía, el estudio técnico para determinar la coexistencia de las actividades mineras con las actividades estratégicas del servicio público de transmisión y distribución de energía eléctrica; XXIII. Autorizar al Centro Nacional de Control de Energía la celebración de convenios con los organismos o autoridades que sean responsables de operar los mercados y sistemas eléctricos en el extranjero; XXIV. Definir los términos para la aprobación de las unidades de verificación y las unidades de inspección de conformidad con la Ley del Sector Eléctrico y expedir los formatos correspondientes; XXV. Regular, supervisar, autorizar y ejecutar el proceso de estandarización y normalización en materia de la seguridad de las instalaciones de las usuarias finales y el Sistema Eléctrico Nacional; XXVI. Participar en el Comité Consultivo Nacional de Normalización de Instalaciones Eléctricas; XXVII. Definir los mecanismos, términos, plazos, criterios, bases y metodologías bajo las cuales la suministradora de servicios básicos tiene la opción de celebrar contratos de cobertura eléctrica; XXVIII. Establecer con la opinión de la Secretaría de Economía, los porcentajes mínimos y demás condiciones de contenido nacional en los términos establecidos por la Ley del Sector Eléctrico; XXIX. Avalar la determinación y ajuste periódico de los niveles de consumo o demanda total y de consumo o demanda por centro de carga que se requieran para que una usuaria final se registre como usuario calificado y, emitir las disposiciones correspondientes; XXX. Participar en la regulación de la ocupación de los terrenos, bienes o derechos que sean necesarios para llevar a cabo las actividades del sector eléctrico; XXXI. Proponer la intervención o requisa de las instalaciones eléctricas en los casos previstos en la Ley del Sector Eléctrico y participar en el procedimiento correspondiente, en los términos del decreto que al efecto se expida; XXXII. Establecer y vigilar la política nuclear en materia de electricidad, conducción y supervisión de generación de energía eléctrica con tecnología nuclear; XXXIII. Regular el uso de los materiales radiactivos incluyendo la explotación, transportación, importación y exportación, así como controlar y vigilar su debido cumplimiento; XXXIV. Coordinar con las dependencias gubernamentales involucradas la transportación del combustible nuclear nuevo, para su utilización en las centrales nucleoeléctricas; XXXV. Vigilar que las actividades nacionales de investigación y desarrollo tecnológico en materia nuclear se orienten al óptimo aprovechamiento de las aplicaciones de materiales y combustibles nucleares y de los materiales radiactivos; XXXVI. Colaborar en el establecimiento de los mecanismos que permitan cumplir, medir y evaluar la política en materia de diversificación de fuentes de energía, la transición energética, la descarbonización, la autosuficiencia y seguridad energéticas, y la promoción de fuentes de energías limpias, en lo relacionado con las actividades de generación, transmisión, distribución y usos finales de energía eléctrica; XXXVII. Aprobar los procedimientos que correspondan a esta dependencia, relacionados con los proyectos de infraestructura productiva de largo plazo que realice la empresa pública del Estado, Comisión Federal de Electricidad; XXXVIII. Autorizar la aplicación de los ordenamientos legales que regulen la distribución de energía eléctrica, así como aquellas disposiciones en materia de instalaciones eléctricas destinadas al uso de la energía eléctrica; XXXIX. Ejercer las atribuciones que se le otorgan a la Secretaría en los ordenamientos legales y demás normas jurídicas que de éstos deriven, cuyas disposiciones regulen materias relacionadas con el análisis del sector eléctrico y la evaluación del mercado eléctrico y emitir, en su caso, sus correspondientes criterios de aplicación, en acuerdo con el superior jerárquico; XL. Dirigir en coordinación con las Direcciones Generales de Asuntos Internacionales y de Desarrollo Tecnológico y Acceso a la Energía, los proyectos de investigación, cooperación, intercambio de información y convenios con instituciones y organismos nacionales e internacionales, en materias afines al Sistema Eléctrico Nacional, política nuclear, distribución, generación, transmisión, suministro, energías limpias, transición energética, reducción de emisiones contaminantes y descarbonización del sector eléctrico, justicia energética, mercados eléctricos y tarifas y cualquier otra en el ámbito de su competencia; XLI. Autorizar el almacenamiento temporal y, en su caso, el confinamiento definitivo, de combustibles nucleares y de desechos radiactivos derivados de su utilización, así como la autorización del emplazamiento de nuevas instalaciones para almacenamiento y confinamiento de desechos radiactivos; XLII. Vigilar el cumplimiento de las atribuciones que correspondan a la Secretaría en materia de energía eléctrica para el campo, así como suscribir los documentos relativos; XLIII. Someter a consideración del Comité de Asignaciones, Contratos y Permisos los proyectos de otorgamiento, prórroga, modificación, actualización, reasignación, revocación, caducidad y terminación de autorizaciones, permisos, concesiones o asignaciones en materia del sector eléctrico, política nuclear y cualquier otro en el ámbito de su competencia; XLIV. Formalizar las autorizaciones de importación y exportación de energía eléctrica, así como el otorgamiento, modificación y revocación de concesiones y asignaciones para la exploración y extracción de minerales radiactivos, previa aprobación del Comité de Asignaciones, Contratos y Permisos; XLV. Dirigir la integración de expedientes de los procedimientos administrativos por el presunto incumplimiento de obligaciones o por violaciones a la Ley del Sector Eléctrico y demás disposiciones jurídicas aplicables; XLVI. Someter a consideración del Comité de Asignaciones, Contratos y Permisos, a través de la Unidad de Asuntos Jurídicos, el inicio y resolución del procedimiento administrativo de sanción o por posibles incumplimientos, en términos de las atribuciones que se otorgan a la Secretaría en la Ley del Sector Eléctrico y demás ordenamientos jurídicos aplicables; XLVII. Participar en el proceso de autorización al Centro Nacional de Control de Energía para llevar a cabo los mecanismos competitivos para adquirir potencia, energía y servicios conexos para asegurar la confiabilidad del Sistema Eléctrico Nacional, así como determinar la asignación de los costos que resulten de dichos mecanismos y expedir el protocolo para que el Centro Nacional de Control de Energía realice la contratación en casos de emergencia; XLVIII. Llevar a cabo la regulación técnica y económica del sector eléctrico de conformidad con la Ley del Sector Eléctrico; XLIX. Proponer esquemas financieros para proyectos de infraestructura eléctrica que lleve a cabo el Estado directamente o a través de esquemas de desarrollo mixto, y L. Imponer las medidas de seguridad en el ejercicio de sus facultades de inspección, supervisión y vigilancia de conformidad con lo establecido en las disposiciones jurídicas aplicables.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LA SUBSECRETARÍA DE PLANEACIÓN Y TRANSICIÓN ENERGÉTICA Y SUS UNIDADES ADMINISTRATIVAS","seccion_nombre":null,"orden":19},{"id":"c79f5b60-63a8-4e2f-9d7e-31e003579aba","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 19.","contenido":"- Corresponde a la Unidad del Sistema Eléctrico Nacional y Política Nuclear, el ejercicio de las atribuciones siguientes: I. Atender los asuntos relativos al Sistema Eléctrico Nacional, política nuclear, así como aquellos que le sean encomendados específicamente, previo acuerdo con el superior jerárquico; II. Vigilar el cumplimiento de las disposiciones que regulen la operación eficiente del sector eléctrico; III. Implementar los actos necesarios para mantener la integridad, la calidad, confiabilidad, continuidad, seguridad, accesibilidad, sostenibilidad y el funcionamiento eficiente del Sistema Eléctrico Nacional; IV. Coordinar, con las unidades administrativas competentes de la Subsecretaría de Electricidad, la alineación de las políticas y estrategias que tengan como fin garantizar la eficiencia, calidad, confiabilidad, continuidad y seguridad del Sistema Eléctrico Nacional, así como promover su sostenibilidad; V. Establecer y ejecutar, en coordinación con los tres niveles de gobierno y con los integrantes del sector eléctrico, los programas y estrategias para suministrar electricidad a las comunidades rurales y zonas urbanas marginadas; VI. Gestionar, por conducto de la unidad administrativa competente de la Secretaría, el reintegro a la Secretaría de Hacienda y Crédito Público de los fondos que no se ejerzan en proyectos de electrificación conforme a las reglas del mercado; VII. Atender las solicitudes de los procedimientos en materia de ocupación temporal, total o parcial, sobre inmuebles, predios, terrenos, bienes o derechos necesarios para realizar las actividades del sector eléctrico; con el apoyo de las unidades correspondientes, conforme a las disposiciones jurídicas aplicables y en el ámbito de competencia de la Subsecretaría de Electricidad; VIII. Opinar técnicamente sobre las acciones relacionadas con la negociación y acuerdo para la ocupación temporal, parcial o total, así como de la limitación de los derechos de dominio de los bienes inmuebles necesarios para llevar a cabo las actividades del sector eléctrico; IX. Proponer la intervención o requisa de empresas e instalaciones eléctricas, así como intervenir y participar en el procedimiento correspondiente; X. Coordinar la definición de los términos, condiciones y modalidades en los que los sistemas de almacenamiento de energía eléctrica participan en las actividades del sector eléctrico, así como en el establecimiento de permisos y sus requisitos necesarios; XI. Coordinar los procesos relativos al acceso a la información sobre el desempeño y las tendencias del sector eléctrico; XII. Dirigir la integración de expedientes de los procedimientos administrativos de sanciones que, en su caso, correspondan en términos de la Ley del Sector Eléctrico, su reglamento o disposiciones emanadas de esta, y demás relativas al Sistema Eléctrico Nacional y a la política nuclear; XIII. Vigilar el cumplimiento de las obligaciones consideradas de servicio público y universal de los integrantes del sector eléctrico; XIV. Supervisar el cumplimiento de la política, regulación y vigilancia del sector eléctrico en el ámbito de competencia de la Secretaría; XV. Vigilar la aplicación de los convenios bajo los cuales los integrantes del sector eléctrico deben colaborar dentro de los pequeños sistemas eléctricos, a fin de prestar el suministro eléctrico en condiciones de eficiencia, calidad, confiabilidad, accesibilidad, continuidad, seguridad y sostenibilidad; XVI. Establecer y vigilar los términos para la desincorporación de activos, derechos, partes sociales o acciones cuando se determine que la separación legal sea insuficiente para fomentar el acceso o la operación eficiente del sector eléctrico; XVII. Aplicar los ordenamientos legales y demás normas jurídicas que de éstos deriven, cuyas disposiciones sean competencia de la Secretaría en materia de energía nuclear; XVIII. Proponer los proyectos de políticas, lineamientos y programas, en acuerdo con el superior jerárquico, en materia de: a) Exploración, explotación y beneficio de minerales radiactivos, así como de su importación y exportación; b) Aprovechamiento de los combustibles nucleares, las actividades, equipos y materiales relacionadas con el ciclo de combustible nuclear, así como de los materiales nucleares, materiales radiactivos y las fuentes radiactivas; c) Energía nucleoeléctrica; d) Investigación y desarrollo tecnológico de la ciencia y aplicaciones nucleares; e) Gestión de desechos radiactivos y del combustible gastado, y f) Bienes de uso dual nuclear; XIX. Proponer las disposiciones respecto del uso energético y no energético de los materiales radiactivos; XX. Someter a consideración de la persona titular de la Subsecretaría de Electricidad o, en su caso, del Comité de Asignaciones, Contratos y Permisos los proyectos de otorgamiento, prórroga, modificación, actualización, reasignación, revocación, caducidad, terminación de las asignaciones para la exploración y extracción de minerales radiactivos; XXI. Vigilar el otorgamiento, la negación, modificación y revocación de las asignaciones para la exploración y extracción de minerales radiactivos; XXII. Coordinar la integración de expedientes de los procedimientos administrativos por el presunto incumplimiento de obligaciones o por violaciones a la Ley de Planeación y Transición Energética, la Ley de Biocombustibles, la Ley de Geotermia y demás disposiciones jurídicas aplicables; XXIII. Someter a consideración de la persona titular de la Subsecretaría de Electricidad o, en su caso, del Comité de Asignaciones, Contratos y Permisos, a través de la Unidad de Asuntos Jurídicos, el inicio y resolución del procedimiento administrativo de sanción o por posibles incumplimientos en materia de asignaciones para la exploración y extracción de minerales radiactivos; XXIV. Coordinar el transporte de combustibles nucleares y el transporte, almacenamiento y confinamiento de los desechos radiactivos; XXV. Vigilar el almacenamiento temporal y, en su caso , el confinamiento definitivo, de combustibles nucleares y de desechos radiactivos derivados de su utilización; así como el emplazamiento de nuevas instalaciones para almacenamiento y confinamiento de desechos radiactivos; XXVI. Emitir opinión respecto de los actos administrativos de carácter general que la Comisión Nacional de Seguridad Nuclear y Salvaguardias proponga en materia de seguridad nuclear, radiológica y física; XXVII. Analizar y emitir, en su caso, recomendaciones de las solicitudes de emplazamiento, diseño, construcción, operación, modificación, cese de operaciones, cierre definitivo y desmantelamiento de instalaciones nucleares; XXVIII. Emitir recomendaciones sobre la ocupación temporal de una instalación nuclear o radiactiva en los casos de peligro o riesgo inminente para el personal y para la sociedad en general, así como para el medio ambiente, en coordinación con las autoridades competentes; XXIX. Recibir los avisos sobre la existencia de yacimientos de minerales radiactivos y ejercer las atribuciones que competan a la Secretaría en esta materia; XXX. Elaborar los proyectos de lineamientos y programas relativos a la industria nuclear, al aprovechamiento y desarrollo de la energía y tecnología nucleares; XXXI. Coordinar el desarrollo y ejecución de los programas de verificación, supervisión, inspección o revisión del Sistema Eléctrico Nacional, en coordinación con las unidades administrativas de la Subsecretaría de Electricidad; XXXII. Participar, en su caso, en coordinación con la Dirección General de Asuntos Internacionales, en foros, proyectos de investigación, cooperación, intercambio de información y convenios con instituciones y organismos nacionales e internacionales en materias afines al Sistema Eléctrico Nacional y a la política nuclear; XXXIII. Vigilar el cumplimiento de la Ley del Sector Eléctrico, su reglamento y demás disposiciones jurídicas aplicables en el ámbito de las atribuciones de la Subsecretaría de Electricidad; XXXIV. Coordinar el proceso de planeación y elaboración del Plan de Desarrollo del Sector Eléctrico con las unidades administrativas que participan en la Subsecretaría de Electricidad; XXXV. Validar los programas vinculantes para la instalación y retiro de centrales eléctricas; XXXVI. Coordinar la definición de los mecanismos que permitan cumplir la política en materia de diversificación de fuentes de energía, seguridad energética y la promoción de fuentes de energías limpias, en lo relacionado con las actividades de generación y transmisión de energía eléctrica; XXXVII. Supervisar los proyectos de instrumentos, obligaciones, convenios y requisitos para la adquisición de certificados de energías limpias, relacionados con las energías renovables, para dar cumplimiento a la Ley del Sector Eléctrico; XXXVIII. Coordinar la opinión y la solicitud de los cambios a los programas de ampliación y modernización del Sistema Eléctrico Nacional, con la opinión de la Comisión Nacional de Energía, en acuerdo con su superior jerárquico; XXXIX. Evaluar las instrucciones giradas a la transportista o distribuidora sobre la ejecución de los proyectos contenidos en los programas de ampliación y modernización del Sistema Eléctrico Nacional; XL. Dirigir el desarrollo de propuestas de proyectos estratégicos de infraestructura de generación, transmisión y distribución de energía eléctrica necesarios para cumplir con la política energética nacional; XLI. Coordinar con las unidades administrativas competentes de la Secretaría, los procedimientos que correspondan a esta dependencia, relacionados con los proyectos de infraestructura productiva de largo plazo que realice la empresa pública del Estado, Comisión Federal de Electricidad; XLII. Coordinar el análisis sobre las reglas y la operación del Mercado Eléctrico Mayorista; XLIII. Colaborar en la evaluación del Centro Nacional de Control de Energía y del Mercado Eléctrico Mayorista, en coordinación con las unidades administrativas de la Subsecretaría de Electricidad; XLIV. Evaluar las autorizaciones al Centro Nacional de Control de Energía, relacionadas con la celebración de mecanismos competitivos para adquirir potencia, energía y servicios conexos para asegurar la confiabilidad del Sistema Eléctrico Nacional, así como determinar la asignación de los costos que resulten de dichos mecanismos y expedir el protocolo para realizar adquisiciones en casos de emergencia; XLV. Coordinar y validar la determinación de las tarifas reguladas de los servicios establecidos en la Ley del Sector Eléctrico, así como los mecanismos de coordinación necesarios con otras dependencias y organismos; XLVI. Coordinar el establecimiento de los mecanismos, términos, plazos, criterios, bases y metodologías bajo los cuales la suministradora de servicios básicos tiene la opción de celebrar los contratos de cobertura eléctrica; XLVII. Vigilar el cumplimiento de las atribuciones que correspondan a la Secretaría en materia de energía eléctrica para el campo, así como suscribir los documentos relativos, en acuerdo con el superior jerárquico; XLVIII. Participar en el desarrollo de las políticas necesarias para regular y supervisar en materia de redes eléctricas y generación distribuida; XLIX. Coordinar, con la Secretaría de Economía, la realización del estudio técnico, para determinar la coexistencia de las actividades mineras con las actividades estratégicas del Sistema Eléctrico Nacional, en acuerdo con el superior jerárquico; L. Requerir la información necesaria para el desarrollo de sus funciones en materia nuclear a sus órganos administrativos desconcentrados, así como de las entidades paraestatales y empresas públicas del Estado sectorizadas a esta y, en general, a toda persona física o moral que realice cualquiera de las actividades que se refieren en la Ley Reglamentaria del Artículo 27 Constitucional en Materia Nuclear; LI. Supervisar la generación de energía nuclear en el territorio nacional; LII. Vigilar el cumplimiento de normas oficiales mexicanas para la aplicación de reactores nucleares y para la investigación, el desarrollo tecnológico de los materiales nucleares, combustibles nucleares y radiactivos para fortalecer el avance económico y social de la Nación; LIII. Expedir y vigilar el cumplimiento de las disposiciones administrativas de carácter general, en materia del sector eléctrico; LIV. Proponer esquemas de financiamiento que permitan minimizar el costo financiero y el impacto en las métricas de deuda para los proyectos de inversión de generación, transmisión y distribución de energía eléctrica desarrollados tanto por el Estado mexicano, como a través de los esquemas de desarrollo mixto; LV. Supervisar los ajustes correspondientes en la aplicación de la metodología establecida por la Secretaría de Hacienda y Crédito Público para estimar los retornos objetivos alcanzados por los proyectos de expansión e incremento de vida útil de generación, transmisión y distribución de energía eléctrica en los que participe el Estado; LVI. Revisar que la participación del Estado, en los proyectos de desarrollo mixto, sea de conformidad con la Ley del Sector Eléctrico, considerando los costos y beneficios directos e indirectos en su ejecución y operación; LVII. Fungir como enlace de la Secretaría, ante las diferentes instancias de la Secretaría de Hacienda y Crédito Público relacionados con la autorización, supervisión y la gestión de los proyectos de inversión del sector eléctrico, y LVIII. Imponer las medidas de seguridad en el ejercicio de sus facultades de inspección, supervisión y vigilancia de conformidad con lo establecido en las disposiciones jurídicas aplicables.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LA SUBSECRETARÍA DE ELECTRICIDAD Y SUS UNIDADES ADMINISTRATIVAS","seccion_nombre":null,"orden":20},{"id":"569fa909-f362-4d51-af72-c3da655bf2f5","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 20.","contenido":"- Corresponde a la Dirección General de Evaluación Financiera de la Unidad del Sistema Eléctrico Nacional y Política Nuclear, el ejercicio de las atribuciones siguientes: I. Estructurar esquemas de financiamiento que permitan minimizar el costo financiero y el impacto en las métricas de deuda para los proyectos de inversión de generación, transmisión y distribución de energía eléctrica desarrollados tanto por el Estado, como a través de los esquemas de desarrollo mixto; II. Dictaminar que la participación del Estado, en los proyectos de generación desarrollados mediante desarrollo mixto, sea de conformidad con la Ley del Sector Eléctrico, considerando los costos y beneficios directos e indirectos en su ejecución y operación; III. Realizar los ajustes correspondientes, en la aplicación de la metodología establecida por la Secretaría de Hacienda y Crédito Público, para estimar los retornos objetivos alcanzados por los proyectos de expansión e incremento de vida útil de generación, transmisión y distribución de energía eléctrica en los que participe el Estado; IV. Validar y dictaminar las evaluaciones económicas o financieras de los proyectos de generación, transmisión y distribución estratégicos incluidos en la planeación vinculante; V. Dictaminar los cambios en los esquemas de financiamiento de los proyectos de inversión que sean propuestos por la Comisión Federal de Electricidad y otras instancias relacionadas con el sector eléctrico; VI. Desarrollar el análisis técnico necesario relacionado con la autorización, supervisión y gestión de los proyectos de inversión del sector eléctrico ante la Secretaría de Hacienda y Crédito Público; VII. Integrar la cartera de programas y proyectos de inversión en el sector eléctrico que serán desarrollados de forma directa e indirecta por el Estado; VIII. Dar seguimiento económico-financiero a la ejecución de los proyectos de inversión de los procesos de generación, transmisión y distribución en los que participe la empresa pública del Estado, Comisión Federal de Electricidad; IX. Establecer los criterios de evaluación financiera para la delimitación de las centrales eléctricas, las redes de transmisión, las redes de distribución, los centros de carga y el Sistema Eléctrico Nacional y para clasificar instalaciones eléctricas; X. Atender los trámites, consultas y la resolución de los asuntos de su competencia, sobre los aspectos económicos y financieros del sector eléctrico, y XI. Fomentar el otorgamiento de créditos y otros esquemas para el financiamiento de centrales eléctricas de generación distribuida con energía limpia.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LA SUBSECRETARÍA DE ELECTRICIDAD Y SUS UNIDADES ADMINISTRATIVAS","seccion_nombre":null,"orden":21},{"id":"5682e02e-d159-4a26-b74a-c200876b2661","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 21.","contenido":"- Corresponde a la Dirección General de Confiabilidad y Seguridad del Sector Eléctrico, el ejercicio de las atribuciones siguientes: I. Ejercer las atribuciones relativas a la vigilancia, seguimiento, evaluación, y diseño de política pública en materia de confiabilidad y seguridad del sector eléctrico y de cada uno de sus integrantes; II. Orientar a la Comisión Nacional de Energía, el Centro Nacional de Control de Energía, el Centro Nacional de Control del Gas Natural, las empresas públicas del Estado y las demás autoridades relevantes, en las acciones necesarias para el desarrollo confiable y seguro del sector eléctrico; III. Participar en la constitución del comité de evaluación que revisa el desempeño del Centro Nacional de Control de Energía y del Mercado Eléctrico Mayorista; IV. Supervisar que los sistemas informáticos del Centro Nacional de Control de Energía, la empresa pública del Estado, Comisión Federal de Electricidad, así como sus empresas filiales, incluyendo las contables, operacionales y de cualquier tipo, cuenten con mecanismos para preservar la integridad, confidencialidad y disponibilidad de la información; V. Opinar sobre la creación y funcionamiento de los sistemas integrados de transporte por ducto y de almacenamiento de gas natural, así como en la incorporación de nueva infraestructura a los mismos; VI. Coordinar la definición y vigilar el cumplimiento de la política en materia de eficiencia, calidad, continuidad, accesibilidad, seguridad, confiabilidad y sostenibilidad en el Sistema Eléctrico Nacional, incluyendo los criterios para establecer el equilibrio entre estos objetivos, de conformidad con la Ley del Sector Eléctrico; VII. Disponer y requerir la información que se considere necesaria a los integrantes del sector eléctrico en materia de confiabilidad y seguridad; VIII. Participar en la coordinación, ejecución, seguimiento y entrada en operación de los proyectos estratégicos de infraestructura para cumplir con la política energética nacional en materia de confiabilidad y seguridad del sector eléctrico; IX. Evaluar y autorizar los mecanismos competitivos para adquirir potencia, energía y servicios conexos del Centro Nacional de Control de Energía; X. Asistir técnicamente en la formulación de los proyectos de disposiciones administrativas de carácter general del sector eléctrico en materia de seguridad y confiabilidad; XI. Vigilar que los proyectos de los programas de planeación vinculante cumplan con los criterios y lineamientos en materia de confiabilidad y seguridad en el ámbito del sector eléctrico; XII. Monitorear el suministro y comportamiento de los recursos energéticos y, requerir información continua de la prospectiva del suministro de energéticos a los integrantes del sector eléctrico; XIII. Evaluar la eficacia y eficiencia de las inversiones realizadas en mantenimientos del sector eléctrico, respecto a la disminución del derrateo, fallas y la recurrencia de estas; XIV. Dar seguimiento a los protocolos de emergencia, sistemas de alerta temprana y de restablecimiento ante eventos meteorológicos, hidrológicos, incrementos atípicos en los precios de los combustibles, fallas en los elementos y ciberataques que comprometan la operación segura y confiable del Sistema Eléctrico Nacional; XV. Vigilar que los programas de planeación vinculante en el sector eléctrico consideren los criterios de confiabilidad y seguridad, la matriz de generación eléctrica y su evolución, y los impactos ambientales, a fin de garantizar la seguridad energética y la transición hacia la descarbonización; XVI. Determinar, en conjunto con la autoridad correspondiente, los proyectos estratégicos relacionados con centros de carga de alto consumo eléctrico, para definir los requerimientos de infraestructura por actividad económica para su viabilidad; XVII. Impulsar la proveeduría de insumos primarios para el sector eléctrico, a través del fomento de proyectos de exploración y explotación de gas natural en territorio nacional, en coordinación con las unidades administrativas correspondientes; XVIII. Coordinar la cooperación interinstitucional para que los proyectos de generación eléctrica optimicen el uso de agua y otros recursos naturales, así como la disminución de generación de residuos; XIX. Coadyuvar al cumplimiento de la normatividad ambiental de las centrales eléctricas en operación; XX. Participar, con la unidad administrativa responsable, en las mesas de diálogo plurales con comunidades potencialmente afectadas por nuevos proyectos del sector eléctrico; XXI. Desarrollar, en coordinación con el Centro Nacional de Prevención de Desastres, el atlas de riesgos asociados con las actividades de generación, transmisión, distribución y suministro de energía eléctrica; XXII. Establecer los acuerdos interinstitucionales asociados con las actividades de generación, transmisión, distribución y suministro de energía eléctrica, para reducir y mitigar los riesgos a la población; XXIII. Formalizar convenios con instituciones de educación superior y centros de investigación, para el desarrollo y profesionalización de cuadros técnicos especializados que contengan temas de confiabilidad y seguridad del sector eléctrico; XXIV. Coadyuvar en la elaboración del reporte de confiabilidad de la Comisión Nacional de Energía; XXV. Proponer las condiciones para la prestación del Servicio Público de Transmisión y Distribución de Energía Eléctrica; para la prestación del Suministro Eléctrico, en sus aspectos de confiabilidad, así como resolver sobre sus modificaciones; XXVI. Proponer estrategias de promoción de la generación de energía eléctrica a partir de energías limpias, de conformidad con la política energética; XXVII. Participar en la autorización al Centro Nacional de Control de Energía para llevar a cabo mecanismos competitivos para adquirir potencia, energía y servicios conexos, con la finalidad de asegurar la confiabilidad del Sistema Eléctrico Nacional, así como determinar la asignación de los costos que resulten de dichos mecanismos; XXVIII. Expedir el protocolo de contrataciones de energía, potencia y servicios conexos en casos de emergencia al que se debe sujetar el Centro Nacional de Control de Energía; XXIX. Participar en la determinación, conducción y regulación en lo referente a nuevas políticas, incluyendo los lineamientos para la transición energética integral, justa y sostenible; XXX. Colaborar en el diseño e implementación de proyectos piloto de procedimientos, lineamientos, servicios, entre otros que aporten a la eficiencia y confiabilidad del Sistema Eléctrico Nacional, con el propósito de someterlos a la consideración de la Secretaría, para su eventual implementación general, y XXXI. Desarrollar estrategias para la implementación de mecanismos que permitan la diversificación de fuentes de energía, la transición energética, la autosuficiencia energética, la seguridad energética y la promoción de fuentes de energías limpias.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LA SUBSECRETARÍA DE ELECTRICIDAD Y SUS UNIDADES ADMINISTRATIVAS","seccion_nombre":null,"orden":22},{"id":"2fb13ec9-ab84-4f5f-ab34-9c0c97258f29","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 22.","contenido":"- Corresponde a la Dirección General de Distribución, Usos Finales de Energía Eléctrica y Vinculación Social, el ejercicio de las atribuciones siguientes: I. Aplicar los ordenamientos legales que regulen la distribución de energía eléctrica, así como aquellas disposiciones en materia de instalaciones eléctricas destinadas al uso final de la energía eléctrica; II. Definir y vigilar las políticas necesarias en materia de redes eléctricas inteligentes y generación distribuida; III. Determinar los niveles de consumo o demanda que permitan a las personas usuarias finales, su inclusión en el registro de usuarios calificados; IV. Establecer los términos bajo los cuales las personas usuarias finales que pertenecen a un mismo grupo de interés económico pueden agregar sus centros de carga, a fin de alcanzar los niveles de consumo o demanda para incluirse en el registro de usuarios calificados; V. Coadyuvar al cumplimiento de las atribuciones que correspondan a la Secretaría en materia de electrificación de comunidades rurales, zonas urbanas marginadas y el suministro eléctrico a personas y comunidades en condiciones de vulnerabilidad o pobreza energética; VI. Fijar los términos y condiciones para la distribuidora y la suministradora de servicios básicos, en cuanto a la obligación de instalar, conservar y mantener su infraestructura, así como para prestar el servicio de distribución y el suministro básico a comunidades rurales, zonas urbanas marginadas y a personas y comunidades en condiciones de vulnerabilidad o pobreza energética; VII. Realizar visitas de verificación, así como requerir la presentación de información e informes y citar a comparecer a la distribuidora y a las suministradoras, a fin de supervisar y vigilar el cumplimiento de las disposiciones jurídicas aplicables en materia de distribución y suministro de energía eléctrica; VIII. Expedir y vigilar el cumplimiento de las disposiciones administrativas y normas oficiales mexicanas que regulen las actividades en materia de la seguridad de las instalaciones de las personas usuarias finales; IX. Coordinar la integración de expedientes de los procedimientos administrativos de su competencia por el presunto incumplimiento de obligaciones o por violaciones a la Ley del Sector Eléctrico y demás disposiciones jurídicas aplicables; X. Someter a consideración de la persona titular de la Subsecretaría de Electricidad o, en su caso, del Comité de Asignaciones, Contratos y Permisos, a través de la Unidad de Asuntos Jurídicos, el inicio y resolución del procedimiento administrativo de sanción o por posibles incumplimientos, en términos de las atribuciones que se otorgan a la Secretaría en la Ley del Sector Eléctrico y demás ordenamientos jurídicos aplicables; XI. Realizar la evaluación de la conformidad en cumplimiento de las normas oficiales mexicanas que se expidan en materia de distribución y en materia de instalaciones destinadas al uso final de la energía eléctrica; así como expedir los formatos para la aprobación de las unidades de inspección; XII. Emitir opinión y, en su caso, solicitar cambios a los programas de ampliación y modernización de las redes generales de distribución, y en su caso, proponer al superior jerárquico la autorización de dichos programas, lo anterior con la opinión de la Comisión Nacional de Energía; XIII. Instruir a la distribuidora la ejecución de los proyectos contenidos en los programas de ampliación y modernización de las redes generales de distribución; XIV. Establecer y verificar los porcentajes mínimos y demás condiciones de contenido nacional, en la proveeduría de los proyectos para la prestación del servicio público de distribución de energía eléctrica; XV. Contribuir en la definición de los términos, condiciones y modalidades en los que los sistemas de almacenamiento de energía eléctrica participan en las actividades del sector eléctrico, así como en el establecimiento de permisos y sus requisitos necesarios; XVI. Coadyuvar en la definición y vigilancia de las obligaciones de cobertura para el suministro eléctrico en las comunidades rurales, zonas urbanas marginadas y a personas y comunidades en condiciones de vulnerabilidad o pobreza energética e instrumentar los mecanismos para dirigir recursos económicos a este fin; XVII. Apoyar técnicamente la formulación y administración del Fondo de Servicio Universal Energético; XVIII. Coadyuvar en la definición y vigilancia de las estrategias para suministrar electricidad a las comunidades rurales, zonas urbanas marginadas y a personas y comunidades en condiciones de vulnerabilidad o pobreza energética al menor costo para el país, en congruencia con la política energética prevista para el desarrollo del sector eléctrico y promoviendo el uso de las energías limpias; XIX. Participar en los proyectos de investigación, intercambio de información y convenios con instituciones y organismos nacionales e internacionales en materias afines a la distribución y suministro de energía eléctrica; XX. Participar en el proceso de planeación y la elaboración del Plan de Desarrollo del Sector Eléctrico en lo relacionado con las actividades de distribución y suministro de energía eléctrica; XXI. Coadyuvar en la definición de la política en materia de eficiencia, calidad, continuidad, accesibilidad, seguridad, confiabilidad y sostenibilidad en el Sistema Eléctrico Nacional, incluyendo los criterios para establecer el equilibrio entre estos objetivos, en lo relacionado con las actividades de distribución y suministro de energía eléctrica; XXII. Proponer las disposiciones administrativas y normas oficiales mexicanas que regulen las actividades en materia de la seguridad de las instalaciones de las usuarias finales, en coordinación con la Unidad de Asuntos Jurídicos; XXIII. Proponer los procedimientos que correspondan a esta dependencia, relacionados con los proyectos de infraestructura productiva de largo plazo en materia de distribución de energía eléctrica que realice la empresa pública del Estado, Comisión Federal de Electricidad; XXIV. Proponer la ejecución de los proyectos estratégicos de infraestructura de distribución de energía eléctrica necesarios para cumplir con la política energética nacional; XXV. Coadyuvar a la planeación de la transición energética y el aprovechamiento sustentable de la energía, en materia de redes eléctricas inteligentes; XXVI. Proponer disposiciones administrativas de carácter general, orientadas a regular la infraestructura y el suministro de electricidad necesaria para la realización de actividades productivas y la electromovilidad; XXVII. Diseñar estrategias en materia de electrificación de usos finales, así como participar en su promoción; XXVIII. Someter a consideración de la persona titular de la Subsecretaría de Electricidad o, en su caso, del Comité de Asignaciones, Contratos y Permisos los proyectos de autorizaciones de importación y exportación de energía eléctrica, en términos de las atribuciones otorgadas a la Secretaría en la Ley del Sector Eléctrico; XXIX. Formalizar las autorizaciones de importación y exportación de energía eléctrica, previa aprobación del Comité de Asignaciones, Contratos y Permisos; XXX. Formalizar las autorizaciones de importación y exportación de energía eléctrica de centrales eléctricas conectadas, exclusivamente al Sistema Eléctrico Nacional, previa aprobación del Comité de Asignaciones, Contratos y Permisos; XXXI. Emitir las bases normativas para autorizar unidades de inspección especializadas en centrales eléctricas de generación distribuida; XXXII. Participar en el establecimiento de los lineamientos para el otorgamiento de permisos de generación para el autoconsumo aislado y autoconsumo interconectado; XXXIII. Participar en el análisis de las solicitudes realizadas a la Secretaría por los interesados en infraestructura a fin de que se incluyan obras específicas en los programas de ampliación y modernización de las redes generales de distribución; XXXIV. Coadyuvar en la regulación del uso de redes particulares para el autoconsumo en el ámbito de la actividad de distribución de energía eléctrica; XXXV. Comprobar, cuando se trate de conexiones de instalaciones destinadas al uso de energía eléctrica para servicios en alta tensión y de la prestación de servicios en lugares de concentración pública, que una unidad de inspección haya certificado que la instalación en cuestión cumple con las normas oficiales mexicanas aplicables a dichas instalaciones, y XXXVI. Coadyuvar en la definición de las estrategias para el fomento industrial de cadenas productivas locales y para el fomento de la inversión directa en el sector eléctrico, con especial atención a las pequeñas y medianas empresas.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LA SUBSECRETARÍA DE ELECTRICIDAD Y SUS UNIDADES ADMINISTRATIVAS","seccion_nombre":null,"orden":23},{"id":"1e68a074-8f2c-4553-88b4-3bd30fc5b3d6","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 23.","contenido":"- Corresponde a la Dirección General de Generación y Transmisión de Energía Eléctrica, el ejercicio de las atribuciones siguientes: I. Coadyuvar en el proceso de planeación y la elaboración del Plan de Desarrollo del Sector Eléctrico respecto a las actividades de generación y transmisión de energía eléctrica; II. Determinar las tecnologías que se consideran energías limpias, en coordinación con la unidad administrativa responsable; III. Coadyuvar en el proceso de elaboración de los programas vinculantes para la instalación y retiro de centrales eléctricas; IV. Proponer la ejecución de los proyectos estratégicos de infraestructura de generación y transmisión de energía eléctrica necesarios para cumplir con la política energética nacional; V. Emitir opinión y, en su caso, solicitar cambios a los programas de ampliación y modernización de la Red Nacional de Transmisión así como proponer al superior jerárquico la autorización de dichos programas de ser procedente, lo anterior con la opinión de la Comisión Nacional de Energía; VI. Verificar los porcentajes mínimos y demás condiciones de contenido nacional en la proveeduría de los contratos a que se refiere la Ley del Sector Eléctrico, de acuerdo con la naturaleza de la contratación, la regulación tarifaria y conforme a los Tratados Internacionales de los que México sea parte, en lo relacionado con las actividades de generación y transmisión de energía eléctrica; VII. Proponer la instrucción para que la empresa pública del Estado, Comisión Federal de Electricidad, realice la ejecución de los proyectos de la Red Nacional de Transmisión contenidos en los programas de ampliación y modernización de la Red Nacional de Transmisión; VIII. Coadyuvar en la definición de los términos, condiciones y modalidades en los que los sistemas de almacenamiento de energía eléctrica participan en las actividades del sector eléctrico, así como permisos y sus requisitos necesarios; IX. Proponer y participar en los proyectos de investigación, intercambio de información y convenios con instituciones y organismos nacionales e internacionales en materias afines a la generación y transmisión de energía eléctrica; X. Proponer los mecanismos para la supervisión de los elementos que permitan cumplir la política en materia de diversificación de fuentes de energía, seguridad energética y la promoción de fuentes de energías limpias, en lo relacionado con las actividades de generación y transmisión de energía eléctrica; XI. Establecer las obligaciones y requisitos para adquirir certificados de energías limpias e instrumentar los mecanismos necesarios para dar cumplimiento a la política en la materia; XII. Celebrar convenios que permitan la homologación de las obligaciones para adquirir los certificados de energías limpias, con los instrumentos correspondientes de otras jurisdicciones; XIII. Coadyuvar en la definición de la política en materia de eficiencia, calidad, continuidad, accesibilidad, seguridad, confiabilidad y sostenibilidad en el Sistema Eléctrico Nacional, incluyendo los criterios para establecer el equilibrio entre estos objetivos, en lo relacionado con las actividades de generación y transmisión de energía eléctrica, de conformidad con la Ley del Sector Eléctrico; XIV. Programar la realización de visitas de inspección y verificación, así como requerir la presentación de información e informes y citar a comparecer a los integrantes del sector eléctrico, a fin de supervisar y vigilar el cumplimiento de las disposiciones jurídicas aplicables en materia de generación y transmisión de energía eléctrica; XV. Imponer las medidas de seguridad en el ejercicio de sus facultades de inspección, supervisión y vigilancia de conformidad con lo establecido en las disposiciones jurídicas aplicables; XVI. Coordinar la integración de expedientes de los procedimientos administrativos por el presunto incumplimiento de obligaciones o por violaciones a la Ley del Sector Eléctrico y demás disposiciones jurídicas aplicables; XVII. Someter a consideración de la persona titular de la Subsecretaría de Electricidad o, en su caso, del Comité de Asignaciones, Contratos y Permisos, a través de la Unidad de Asuntos Jurídicos, el inicio y resolución del procedimiento administrativo de sanción o por posibles incumplimientos, en términos de las atribuciones que se otorgan a la Secretaría en la Ley del Sector Eléctrico y demás ordenamientos jurídicos aplicables; XVIII. Elaborar los procedimientos que correspondan a esta dependencia, relacionados con los proyectos de infraestructura productiva de largo plazo en materia de generación y transmisión de energía eléctrica que realice la empresa pública del Estado, Comisión Federal de Electricidad; XIX. Emitir opinión sobre la creación y funcionamiento de los sistemas integrados de transporte por ducto y de almacenamiento de gas natural, así como en la incorporación de nueva infraestructura a los mismos; XX. Participar en la realización del estudio técnico, para determinar la coexistencia de las actividades mineras con las actividades estratégicas del servicio público de transmisión y distribución de energía eléctrica; XXI. Participar en el establecimiento de los lineamientos para el otorgamiento de permisos de generación para el autoconsumo aislado y autoconsumo interconectado; XXII. Participar en la regulación del uso de redes particulares para el autoconsumo en el ámbito de la Red Nacional de Transmisión; XXIII. Coadyuvar en la emisión de disposiciones de carácter general en materia de cogeneración, y XXIV. Analizar las solicitudes realizadas a la Secretaría por los interesados en infraestructura a fin de que se incluyan obras específicas en los programas de ampliación y modernización de la Red Nacional de Transmisión.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LA SUBSECRETARÍA DE ELECTRICIDAD Y SUS UNIDADES ADMINISTRATIVAS","seccion_nombre":null,"orden":24},{"id":"4a1a91d1-d9c7-4778-8373-851b10f2494f","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 24.","contenido":"- Corresponde a la Dirección General de Análisis y Evaluación del Mercado Eléctrico Mayorista el ejercicio de las atribuciones siguientes: I. Ejercer las atribuciones que se le otorgan a la Secretaría en los ordenamientos legales y demás normas jurídicas que de éstos deriven, cuyas disposiciones regulen materias relacionadas con el análisis del sector eléctrico y la evaluación del Mercado Eléctrico Mayorista y emitir, en su caso, sus correspondientes criterios de aplicación; II. Participar en la constitución de un comité de evaluación para revisar el desempeño del Centro Nacional de Control de Energía y del Mercado Eléctrico Mayorista. III. Analizar y emitir opinión sobre las reglas del mercado y sobre la operación del Mercado Eléctrico Mayorista; IV. Modificar las reglas de mercado cuando sea necesario para preservar la eficiencia, calidad, confiabilidad, continuidad y sostenibilidad del Sistema Eléctrico Nacional; V. Evaluar el desempeño y las tendencias del sector eléctrico, a partir de la información requerida para ello a los integrantes del sector eléctrico y las empresas públicas del Estado; VI. Informar al órgano en materia de competencia económica, la existencia de cualquier convenio, arreglo o coordinación entre participantes del mercado con la intención o efecto de restringir el funcionamiento eficiente del Mercado Eléctrico Mayorista; VII. Emitir formatos y requisitos para recopilar, en forma física y electrónica, datos de los integrantes del sector eléctrico; VIII. Coordinar y participar en los estudios, investigaciones e intercambio de información y convenios con instituciones y organismos nacionales e internacionales, en materias afines sobre ahorro de energía, estructuras, costos, proyectos, mercados, precios y tarifas, activos, procedimientos, reglas, normas y demás aspectos relacionados con las actividades anteriores; IX. Coadyuvar en el establecimiento de los sistemas para automatizar la recepción y procesamiento de datos para habilitar a las personas servidoras públicas de la Secretaría a llevar a cabo sus atribuciones en relación con la transparencia y evaluación del Mercado Eléctrico Mayorista; X. Determinar criterios y procedimientos de control de personas usuarias para el acceso a la información relativa al Mercado Eléctrico Mayorista y verificar el cumplimiento por parte del Centro Nacional de Control de Energía; XI. Elaborar y proponer la publicación anual del informe pormenorizado que permita conocer el desempeño y las tendencias del Sector Eléctrico Nacional; XII. Analizar y emitir opinión sobre la operación del Mercado Eléctrico Mayorista, a fin de asegurar su funcionamiento eficiente y el cumplimiento de las reglas del mercado; XIII. Evaluar y dar seguimiento al cumplimiento de los objetivos y metas de la empresa pública del Estado, Comisión Federal de Electricidad, así como del Centro Nacional de Control de Energía y de la Comisión Nacional de Energía; XIV. Coadyuvar en el proceso de planeación y elaboración del Plan de Desarrollo del Sector Eléctrico; XV. Coordinar con la Comisión Nacional de Energía la regulación tarifaria a que se deben sujetar la transmisión, la distribución, la operación de la suministradora de servicios básicos, la operación del Centro Nacional de Control de Energía y los servicios conexos no incluidos en el Mercado Eléctrico Mayorista, así como las tarifas finales del suministro básico, en términos de lo dispuesto en la Ley del Sector Eléctrico; XVI. Autorizar al Centro Nacional de Control de Energía la celebración de convenios con los organismos o autoridades que sean responsables de operar los mercados y sistemas eléctricos en el extranjero; XVII. Establecer los términos para la separación legal de integrantes del sector eléctrico y la desincorporación de activos, derechos, partes sociales o acciones ante el incumplimiento de las obligaciones de ofrecer al Mercado Eléctrico Mayorista la totalidad de las capacidades disponibles en las centrales eléctricas a precios basados en costos y la totalidad de las capacidades disponibles en la demanda controlable garantizada, conforme a las reglas del mercado; XVIII. Establecer los mecanismos, términos, plazos, criterios, bases y metodologías bajo los cuales la suministradora de servicios básicos tiene la opción de celebrar los contratos de cobertura eléctrica, y XIX. Coadyuvar, en la determinación de las condiciones para la prestación del servicio público de transmisión y distribución de energía eléctrica, para la prestación del suministro eléctrico, en sus aspectos de Mercado Eléctrico Mayorista, así como resolver sobre sus modificaciones. CAPÍTULO VIII DE LA SUBSECRETARÍA DE HIDROCA R BUROS Y SUS UNIDADES ADMINISTRATIVAS","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LA SUBSECRETARÍA DE ELECTRICIDAD Y SUS UNIDADES ADMINISTRATIVAS","seccion_nombre":null,"orden":25},{"id":"908cbf24-91cc-4d49-a3a9-a98975d70e40","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 25.","contenido":"- Corresponde a la persona titular de la Subsecretaría de Hidrocarburos el trámite y la resolución de los asuntos de su competencia y de las unidades administrativas que le estén adscritas, además tiene las facultades siguientes: I. Someter a consideración de la persona titular de la Secretaría la política energética del país en el ámbito de su competencia; II. Aprobar el Programa Anual de Visitas de Verificación e Inspección, con base en las propuestas de las Unidades Técnicas y de conformidad con la normativa aplicable; III. Someter al Comité de Asignaciones, Contratos y Permisos, la propuesta de desincorporación de activos solicitada por el asignatario o contratista; IV. Proponer a la persona titular de la Secretaría, la plataforma anual de producción de petróleo y de gas, con base en las disposiciones aplicables; V. Autorizar los términos técnicos y operativos de la asignación y el modelo del título de asignación, así como los términos y condiciones técnicos de los contratos de exploración y extracción y el modelo de contratación; VI. Determinar las áreas en posesión del Estado a otorgar en una asignación y en un contrato para la exploración y extracción, previa aprobación del Comité de Asignaciones, Contratos y Permisos; VII. Aprobar los porcentajes mínimos de contenido nacional que deberán incluirse en cada asignación y contrato; VIII. Emitir los lineamentos técnicos que deben observarse en los procesos excepcionales de licitación, los términos y condiciones técnicas de los contratos de exploración y extracción y los modelos de contratación, previa aprobación del Comité de Asignaciones, Contratos y Permisos; IX. Determinar la procedencia sobre las solicitudes de la empresa pública del Estado respecto de la migración de asignaciones a contratos para la exploración y extracción, previa aprobación del Comité de Asignaciones, Contratos y Permisos; X. Emitir los lineamientos técnicos para la creación de alianzas y asociaciones entre empresas públicas del Estado y personas morales para los casos de asignaciones que migren a contratos para la exploración y extracción de hidrocarburos, previa aprobación del Comité de Asignaciones, Contratos y Permisos; XI. Autorizar las adecuaciones a los términos de asociación o alianza entre una empresa pública del Estado y una o varias personas morales y al acuerdo de operación conjunta, previa opinión de la Secretaría de Hacienda y Crédito Público, conforme a lo aprobado por el Comité de Asignaciones, Contratos y Permisos; XII. Proponer a la persona titular de la Secretaría, el establecimiento de zonas de salvaguarda en las que se prohíban las actividades de exploración y extracción de hidrocarburos, así como para incorporar o desincorporar áreas específicas a estas; XIII. Instruir la unificación de campos o yacimientos de extracción de hidrocarburos, en los términos aprobados por el Comité de Asignaciones, Contratos y Permisos; XIV. Determinar la participación del Estado Mexicano, a través de la empresa pública del Estado mexicano, cuando un área contractual coexista a distinta profundidad con una asignación o bien, cuando existan oportunidades de impulsar la transferencia de conocimiento y tecnología, en los contratos para la exploración y extracción de hidrocarburos, previa aprobación del Comité de Asignaciones, Contratos y Permisos; XV. Aprobar la participación obligatoria de la empresa pública del Estado en los contratos para la exploración y extracción en aquellas áreas contractuales en las que exista la posibilidad de encontrar yacimientos transfronterizos, en los términos aprobados por el Comité de Asignaciones, Contratos y Permisos; XVI. Resolver las solicitudes de adjudicación directa de contratos para la exploración y extracción de gas natural contenido en la veta de carbón mineral y producida por esta, en los términos aprobados por el Comité de Asignaciones, Contratos y Permisos; XVII. Someter a consideración del Comité de Asignaciones, Contratos y Permisos, los programas de transición, planes de exploración y de desarrollo para la extracción, los programas asociados y sus modificaciones, así como las solicitudes de periodos adicionales de exploración, suspensión de actividades de exploración y extracción y prórrogas a la vigencia de las asignaciones y contratos para la exploración y extracción; XVIII. Someter a consideración del Comité de Asignaciones, Contratos y Permisos, el programa de aprovechamiento de gas natural como parte del plan de desarrollo para la extracción de hidrocarburos; XIX. Proponer a la persona titular de la Secretaría las políticas que deban emitirse con relación a los asuntos de su competencia; XX. Proponer a la persona titular de la Secretaría la estrategia para asegurar, fomentar y vigilar el adecuado suministro de hidrocarburos y petrolíferos en el territorio nacional; XXI. Proponer a la persona titular de la Secretaría la intención de convocar a un proceso excepcional de licitación para adjudicar áreas contractuales; XXII. Autorizar la cesión del control corporativo o de las operaciones de los contratos para la exploración y extracción de hidrocarburos, previa aprobación del Comité de Asignaciones, Contratos y Permisos; XXIII. Solicitar a entidades paraestatales de la Administración Pública Federal, y empresas públicas del Estado, que realicen acciones preventivas para garantizar el suministro de hidrocarburos, petrolíferos y petroquímicos en el territorio nacional ante casos en los que se prevea un inminente riesgo de desabasto, o acciones temporales ante casos fortuitos o de fuerza mayor; XXIV. Participar con las unidades administrativas de la Subsecretaría de Planeación y Transición Energética y Subsecretaría de Electricidad, en la elaboración de políticas públicas en materia de cogeneración; XXV. Proponer a la persona titular de la Secretaría el proyecto de política de restitución de reservas de hidrocarburos; XXVI. Proponer a la persona titular de la Secretaría los proyectos de infraestructura estratégicos necesarios para cumplir con la política energética en actividades de exploración y extracción de hidrocarburos; XXVII. Determinar como inviable técnica o económicamente para la extracción a un pozo destinado para las actividades de exploración y extracción de las asignaciones y contratos para la exploración y extracción de hidrocarburos; XXVIII. Aprobar y emitir el plan quinquenal de expansión del Sistema de Transporte y Almacenamiento Nacional Integrado de Gas Natural, así como su revisión anual e instruir su publicación; XXIX. Establecer el mecanismo de administración para la gestión de los niveles mínimos de almacenamiento de gas natural; XXX. Aprobar y emitir el plan quinquenal de expansión y optimización de la infraestructura de transporte por ducto y almacenamiento de petróleo y petrolíferos, así como su revisión anual e instruir su publicación; XXXI. Instruir a las empresas públicas del Estado, y sus empresas filiales que realicen las acciones necesarias para que sus actividades y operaciones sean garantes de la seguridad y la autosuficiencia energética de la Nación y que no obstaculicen el desarrollo eficiente de los mercados, así como la política pública en materia energética; XXXII. Desarrollar las políticas públicas de comercialización, transporte, distribución, tratamiento, refinación, expendio al público y almacenamiento de petróleo, gas natural, petrolíferos y petroquímicos, así como los mecanismos de administración para la gestión de los niveles mínimos de almacenamiento de gas natural y petrolíferos, en cumplim i ento con la planeación vinculante del sector hidrocarburos; XXXIII. Presentar a la persona titular de la Secretaría la estrategia para asegurar, fomentar y vigilar el adecuado suministro de petróleo, gas natural, petrolíferos y petroquímicos en el territorio nacional; XXXIV. Aprobar la creación de sistemas integrados en materia de gas natural, petrolíferos y petroquímicos, en los términos aprobados por el Comité de Asignaciones, Contratos y Permisos; XXXV. Solicitar a dependencias y entidades de la Administración Pública Federal la información con la que cuenten relacionada con la supervisión y el cumplimiento de obligaciones de los permisos a que se refiere el Título Tercero de la Ley del Sector Hidrocarburos, a fin de que sea integrada a la plataforma de información electrónica que la Secretaría establezca; XXXVI. Establecer mecanismos de coordinación y celebrar convenios de colaboración con Petróleos Mexicanos o cualquier otra autoridad de los tres órdenes de gobierno para que, en el ámbito de su competencia supervisen, vigilen y verifiquen que las actividades reguladas en la Ley se realicen sin perjuicio del interés público y social; XXXVII. Remitir a la persona titular de la Unidad de Asuntos Jurídicos la opinión técnica respecto de la ocupación temporal, intervención, servidumbre o expropiación de bienes, derechos e instalaciones, que se lleven a cabo respecto de las actividades que son materia del sector hidrocarburos, a fin de garantizar los intereses de la Nación, para el inicio del procedimiento administrativo correspondiente; XXXVIII. Expedir la regulación, lineamientos, disposiciones técnicas y administrativas, normas oficiales mexicanas, manuales, instructivos, políticas y demás normativa respecto a las materias competencia de la Subsecretaría de Hidrocarburos, y sus modificaciones o cancelación, según corresponda, previa opinión de la Unidad de Asuntos Juríd i cos, así como los procedimientos de evaluación de la conformidad, en cumplimiento con la planeación vinculante del sector hidrocarburos; XXXIX. Aprobar la estrategia regulatoria y normativa de la Subsecretaría de Hidrocarburos con base en la legislación aplicable y los conceptos de eficiencia regulatoria; XL. Aprobar las estrategias, mecanismos, actos jurídicos y acciones para la ejecución de políticas, programas, decretos, acuerdos y demás disposiciones administrativas de carácter general, relacionadas con el sector hidrocarburos, en coordinación con las áreas competentes de la Administración Pública Federal; XLI. Aprobar en coordinación con las autoridades administrativas competentes los proyectos que sean materia del sector hidrocarburos, que lleven a cabo las empresas públicas del Estado, organismos descentralizados, entidades paraestatales y otras empresas del sector hidrocarburos, en términos aprobados por el Comité de Asignaciones, Contratos y Permisos; XLII. Proponer a la persona titular de la Secretaría los actos y acciones correspondientes para llevar a cabo la ocupación temporal, intervención, servidumbres o expropiación de bienes, derechos e instalaciones, relacionados con las actividades que son materia del sector hidrocarburos; XLIII. Emitir las autorizaciones de perforación de pozos exploratorios, pozos tipo y pozos en aguas profundas y ultra profundas, así como sus prórrogas o renovaciones, en los términos aprobados por el Comité de Asignaciones, Contratos y Permisos; XLIV. Emitir las autorizaciones para el no ejercicio de derechos conferidos en las autorizaciones otorgadas, en los términos aprobados por el Comité de Asignaciones, Contratos y Permisos; XLV. Emitir las autorizaciones para las actividades de reconocimiento y exploración superficial, así como sus prórrogas o renovaciones, en los términos aprobados por el Comité de Asignaciones, Contratos y Permisos; XLVI. Coadyuvar con la Unidad de Asuntos Jurídicos en la elaboración y publicación de los criterios de interpretación y aplicación para efectos administrativos, así como de todas las disposiciones normativas de carácter general o de carácter interno que expida el Subsecretario de Hidrocarburos; XLVII. Aprobar las bases de licitación que realice el Centro Nacional de Control del Gas Natural, así como los mecanismos de asignación de capacidad por parte de las personas permisionarias para sistemas integrados o nuevos proyectos de transporte y almacenamiento de gas natural, en los términos aprobados por el Comité de Asignaciones, Contratos y Permisos; XLVIII. Proponer a la persona titular de la Secretaría la Política Nacional en materia de petrolíferos, petroquímicos, refinación y gas natural; XLIX. Proponer los criterios de planeación vinculante para el otorgamiento de los permisos del Sector Hidrocarburos en términos de lo establecido en la Ley de Planeación y Transición Energética y el Plan de Desarrollo del Sector Hidrocarburos; L. Emitir las convocatorias y bases para los procesos excepcionales de licitación previstos en la Ley del Sector Hidrocarburos, así como sus modificaciones en los términos aprobados por el Comité de Asignaciones, Contratos y Permisos; LI. Instruir la revisión de la efectiva recuperación de los costos incurridos y demás contabilidad involucrada en el cumplimiento de las actividades objeto de las asignaciones para desarrollo mixto, en los términos aprobados por el Comité de Asignaciones, Contratos y Permisos; LII. Aprobar una recuperación de costos mayor del treinta por ciento para los contratos mixtos de las asignaciones para desarrollo mixto, en los términos aprobados por el Comité de Asignaciones, Contratos y Permisos; LIII. Someter a consideración del Comité de Asignaciones, Contratos y Permisos el otorgamiento, prórroga, modificación, revocación, cancelación, renuncia, terminación y demás asuntos que así se determinen, de las autorizaciones, permisos, asignaciones y contratos en materia de hidrocarburos de conformidad con lo establecido en la Ley del Sector Hidrocarburos y demás disposiciones jurídicas aplicables; LIV. Someter a consideración del Comité de Asignaciones, Contratos y Permisos la sustitución de una asignación para desarrollo propio por una asignación para desarrollo mixto; LV. Formalizar el otorgamiento, prórroga, modificación, revocación, cancelación, terminación y demás asuntos que así se determinen, de las autorizaciones, permisos, asignaciones y contratos a que se refiere la Ley del Sector Hidrocarburos, previa aprobación del Comité de Asignaciones, Contratos y Permisos; LVI. Formalizar el otorgamiento, modificación y cesión de los permisos de tratamiento, refinación, comercialización, transporte y almacenamiento de petróleo, previa aprobación del Comité de Asignaciones, Contratos y Permisos; LVII. Formalizar el otorgamiento, modificación y cesión de los permisos de importación y exportación de petróleo, gas natural, petrolíferos y petroquímicos por una cantidad mayor a un millón de unidades de medida a las que se refiere el artículo 1 de la Ley de los Impuestos Generales de Importación y de Exportación, previa aprobación del Comité de Asignaciones, Contratos y Permisos; LVIII. Formalizar el otorgamiento, modificación y cesión de los permisos de importación y exportación de petróleo, gas natural, petrolíferos y petroquímicos por una cantidad de hasta un millón de unidades de medida a las que se refiere el artículo 1 de la Ley de los Impuestos Generales de Importación y de Exportación, previa aprobación del Comité de Asignaciones, Contratos y Permisos; LIX. Imponer las medidas precautorias o cautelares en el ejercicio de sus facultades de inspección, supervisión y vigilancia de conformidad con lo establecido en la Ley del Sector Hidrocarburos y demás ordenamientos jurídicos aplicables; LX. Dirigir la integración de expedientes de los procedimientos administrativos por el presunto incumplimiento de obligaciones o por violaciones a la Ley del Sector Hidrocarburos y demás disposiciones jurídicas aplicables, y LXI. Someter a consideración del Comité de Asignaciones, Contratos y Permisos, a través de la Unidad de Asuntos Jurídicos, el inicio y resolución del procedimiento administrativo de sanción o por posibles incumplimientos, en términos de las atribuciones que se otorgan a la Secretaría en la Ley del Sector Hidrocarburos y demás ordenamientos jurídicos aplicables.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LA SUBSECRETARÍA DE PLANEACIÓN Y TRANSICIÓN ENERGÉTICA Y SUS UNIDADES ADMINISTRATIVAS","seccion_nombre":null,"orden":26},{"id":"3f16638f-aef3-4993-bf4b-7e09eccec406","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 26.","contenido":"- Corresponde a la Unidad de Desarrollo de Modelos Contractuales y de Asignaciones, Proyectos Regulatorios y Argumentación Técnica el ejercicio de las atribuciones siguientes: I. Coordinar la aplicación de los ordenamientos legales y demás normas jurídicas que de estos deriven, tales como leyes, reglamentos, decretos, acuerdos y políticas cuyas disposiciones regulen materias relativas al sector hidrocarburos, en el ámbito de su competencia; II. Orientar legalmente a la Subsecretaría de Hidrocarburos y sus unidades administrativas, en los asuntos que sean materia del sector hidrocarburos; III. Dirigir los procesos de regulación y consulta de las Direcciones Generales adscritas a su cargo; IV. Dirigir los procesos de argumentación técnica que se brinda a la Unidad de Asuntos Jurídicos para la defensa jurídica de los asuntos contenciosos, relacionados con el sector hidrocarburos; V. Fungir como enlace de la Subsecretaría de Hidrocarburos ante la Unidad de Transparencia de la dependencia, coordinar y vigilar la atención de las solicitudes de información, el cumplimiento de las obligaciones en materia de transparencia y la emisión de los alegatos en los recursos de revisión respectivos; VI. Coadyuvar con la Unidad de Asuntos Jurídicos en la elaboración de los criterios de interpretación y aplicación administrativa, que sean competencia de la Subsecretaría de Hidrocarburos, respecto de la Ley del Sector Hidrocarburos, su Reglamento, y demás normatividad aplicable; VII. Coordinar y asegurar la atención de las solicitudes ciudadanas que sean competencia de la Subsecretaría de Hidrocarburos; VIII. Proporcionar a la Unidad de Asuntos Jurídicos los elementos técnicos necesarios para que determine la procedencia de los procedimientos administrativos de revocación, caducidad o sanción, previstos en la Ley del Sector Hidrocarburos; IX. Validar los argumentos técnicos en las materias especializadas que son competencia de la Subsecretaría de Hidrocarburos, para la defensa jurídica de los asuntos contenciosos que lleva la Unidad de Asuntos Jurídicos ante las autoridades jurisdiccionales, en representación legal de la Secretaría de Energía; X. Coordinar y vigilar el cumplimiento de las sentencias emitidas por las autoridades jurisdiccionales, que sean competencia de la Subsecretaría de Hidrocarburos, a solicitud de la Unidad de Asuntos Jurídicos; XI. Validar la información y documentación técnica, relacionada con las materias especializadas que son competencia de la Subsecretaría de Hidrocarburos, necesaria para atender los requerimientos de la Unidad de Asuntos Jurídicos; XII. Coadyuvar con la Unidad de Asuntos Jurídicos en el desarrollo de los procesos de mediación y arbitraje, así como de cualquier otro procedimiento de solución de controversias, respecto de los contratos de exploración y extracción previstos en la Ley del Sector Hidrocarburos; XIII. Opinar los anteproyectos de política pública, iniciativas de leyes, decretos legislativos, y demás disposiciones administrativas de carácter general, relacionados con el sector hidrocarburos, remitidos por los diversos órganos legislativos y administrativos competentes; XIV. Vigilar el cumplimiento y atención a las proposiciones con punto de acuerdo relativas al sector hidrocarburos, emitidas por los diversos órganos legislativos, así como validar las opiniones que sean emitidas al respecto por parte de sus subalternos; XV. Definir, coordinar e implementar las estrategias, mecanismos, actos jurídicos y acciones para la ejecución de políticas, programas, decretos, acuerdos y demás disposiciones administrativas de carácter general, relacionadas con el sector hidrocarburos, en coordinación con las áreas competentes de la Administración Pública Federal o cualquier otro ente participante del mercado; XVI. Definir, coordinar e implementar los actos y acciones correspondientes a la ocupación temporal, intervención, servidumbres o expropiación de bienes, derechos e instalaciones, relacionados con las actividades del sector hidrocarburos, que le sean instruidos por su superior jerárquico, en coordinación con las unidades administrativas competentes; XVII. Coordinar, validar y supervisar las acciones necesarias para el análisis y tramitación de las solicitudes relacionadas con las actividades que requieren permiso por parte de la Secretaría de Energía, previstas en la Ley del Sector Hidrocarburos; XVIII. Supervisar la elaboración de respuesta a las consultas formuladas por las unidades administrativas y los particulares, respecto del sector hidrocarburos, en coordinación con las unidades administrativas competentes; XIX. Supervisar la atención de los requerimientos realizados por los órganos fiscalizadores del Estado, que sean competencia de la Subsecretaría de Hidrocarburos; XX. Coordinar y dirigir los proyectos para la elaboración, modificación, actualización o cancelación de la regulación, lineamientos, disposiciones técnicas y administrativas, normas oficiales mexicanas, estándares, programas, instructivos, criterios, metodologías, parámetros, directivas, reglas, manuales, y demás normativa técnica competencia de la Subsecretaría de Hidrocarburos, y previa opinión de la Unidad de Asuntos Jurídicos, proponer su emisión; XXI. Proponer la estrategia regulatoria y normativa de la Subsecretaría de Hidrocarburos, con base en la legislación aplicable y los conceptos de eficiencia regulatoria; XXII. Designar a las personas servidoras públicas adscritas a su Unidad, cuando sea el caso, para participar con las dependencias competentes en la formulación de los proyectos de iniciativas de leyes, decretos, disposiciones reglamentarias y normas oficiales mexicanas relativas o relacionadas con las actividades reguladas; XXIII. Participar en los trabajos y reuniones de los comités de normalización y, en su caso, coordinar el funcionamiento de los subcomités y grupos de trabajo específicos, que tengan relación con el sector hidrocarburos, en términos de lo dispuesto en la Ley de Infraestructura de la Calidad; XXIV. Emitir opinión respecto de los anteproyectos de normas oficiales mexicanas en materia del sector hidrocarburos; XXV. Requerir a las unidades administrativas competentes de la Subsecretaría de Hidrocarburos, opinión respecto de la emisión y modificación de la normatividad relacionada con el Sector Hidrocarburos; XXVI. Coordinar y supervisar las actividades relacionadas con la mejora regulatoria de la Subsecretaría de Hidrocarburos; XXVII. Coordinar y dirigir la integración de la solicitud de registro de los trámites de la Subsecretaría de Hidrocarburos que deban ser inscritos en el Registro Federal de Trámites y Servicios; XXVIII. Coordinar la integración del programa de mejora regulatoria a cargo de la Subsecretaría de Hidrocarburos, de conformidad con las disposiciones jurídicas aplicables; XXIX. Coordinar la evaluación de la eficacia de la regulación y normatividad emitida por la Subsecretaría de Hidrocarburos; XXX. Coordinar la elaboración de los análisis de impacto regulatorio que se formulen en la Subsecretaría de Hidrocarburos y presentarlos ante la Unidad de Asuntos Jurídicos para su tramitación; XXXI. Vigilar el cumplimiento del programa de mejora regulatoria a cargo de la Subsecretaría de Hidrocarburos, de conformidad con las disposiciones jurídicas aplicables; XXXII. Supervisar la evaluación de la eficacia de la regulación y normatividad emitida por la Subsecretaría de Hidrocarburos; XXXIII. Proponer para aprobación superior, la conveniencia de instruir a la empresa pública del Estado, y sus empresas filiales que realicen las acciones necesarias para que sus actividades y operaciones sean garantes de la seguridad y la autosuficiencia energética de la Nación y que no obstaculicen el desarrollo eficiente de los mercados, así como la política pública en materia energética; XXXIV. Realizar las gestiones necesarias para la inscripción y actualización de la información de las personas servidoras públicas autorizadas para realizar inspecciones y verificaciones en el padrón respectivo, de conformidad con la Ley General de Mejora Regulatoria; XXXV. Definir los procedimientos para la emisión de autorizaciones, aprobaciones, dictámenes, resoluciones, opiniones, análisis y demás actos administrativos que deba emitir la Subsecretaría de Hidrocarburos, así como aquellos que correspondan a sus Unidades Administrativas, derivados de la Ley del Sector Hidrocarburos y su Reglamento; XXXVI. Emitir opinión sobre las autorizaciones para las actividades de Reconocimiento y Exploración Superficial, así como para autorizar la perforación de pozos, en términos de la normatividad aplicable; XXXVII. Presentar a la persona titular de la Subsecretaría de Hidrocarburos, las propuestas de disposiciones, lineamientos, normas oficiales mexicanas o regulación técnica en materia de Hidrocarburos, Petróleo, Gas Natural, Petrolíferos y Petroquímicos, en el ámbito de su competencia; XXXVIII. Aprobar y presentar a la Unidad de Asuntos Jurídicos el dictamen de incumplimiento a las obligaciones, así como la detección de posibles ilícitos cometidos por los permisionarios, en el ejercicio de las actividades objeto de los permisos otorgados; XXXIX. Planear, coordinar y supervisar las funciones de las Direcciones Generales adscritas a su cargo; XL. Coordinar la emisión de la opinión técnica respecto de las manifestaciones, pruebas y alegatos presentados durante los procedimientos de revocación de las autorizaciones de reconocimiento y exploración superficial y perforación de pozos; XLI. Dirigir la elaboración de proyectos de contratos , convenios y demás instrumentos jurídicos necesarios, en materia de comercialización de hidrocarburos del Estado en contratos de exploración y extracción; XLII. Coordinar la atención de los avisos, notificaciones, informes, trámites y procedimientos en general que deriven de los contratos de comercialización de hidrocarburos; XLIII. Proponer el modelo de los títulos de asignación, y el modelo de contratación; XLIV. Revisar y proponer, para aprobación superior, los lineamientos técnicos que deberán observarse en el proceso excepcional de licitación, los términos y condiciones técnicas de los contratos de exploración y extracción de hidrocarburos, así como los modelos de contratación para cada área contractual; XLV. Revisar y proponer para aprobación superior, los anteproyectos de lineamientos técnicos para la creación de alianzas o asociaciones entre empresas públicas del Estado y personas morales, para los casos de asignaciones que migren a contratos para la exploración y extracción de hidrocarburos; XLVI. Proponer para aprobación superior el proyecto de resolución de las solicitudes de contratos para la exploración y extracción de gas natural contenido en la veta de carbón mineral y producido por esta y elaborar el proyecto de contrato respectivo; XLVII. Admitir la solicitud de migración de asignaciones a contratos, y proponer al superior jerárquico la procedencia de las solicitudes de la empresa pública del Estado respecto de la migración de asignaciones a contratos para la exploración y extracción; XLVIII. Proponer el dictamen respecto de la participación del Estado Mexicano en los contratos para la exploración y extracción, en coordinación con las Unidades Administrativas competentes; XLIX. Coordinar la elaboración del proyecto respecto del otorgamiento, modificación, sustitución, renuncia y revocación de asignaciones y remitir al superior para propuesta al Comité de Asignaciones, Contratos y Permisos; L. Emitir el proyecto de resolución de acreditación de las capacidades para empresas respecto de la cesión de control corporativo y de gestión o cesión de interés de participación, de la cesión de control corporativo y de gestión o cesión del interés de participación, o de la autorización para la celebración de alianzas o asociaciones en las que se lleve a cabo una cesión, según corresponda, en términos de las disposiciones legales aplicables; LI. Proponer el otorgamiento de asignaciones para desarrollo mixto; LII. Resolver las solicitudes para imponer Gravámenes sobre el Interés de Participación en los contratos para la exploración y extracción; LIII. Proponer al superior jerárquico el dictamen para la selección y determinar las áreas de asignación y áreas contractuales a otorgar o licitar; LIV. Supervisar la elaboración de las propuestas de convocatorias y bases para los procesos excepcionales de licitación previstos en la Ley del Sector Hidrocarburos, así como las de sus modificaciones para consideración del superior jerárquico; LV. Validar los títulos de asignación y los modelos de contratación y presentarlos al superior jerárquico para su presentación y aprobación por el Comité de Asignaciones, Contratos y Permisos; LVI. Coordinar y dirigir las actividades asociadas con la administración de las garantías presentadas en los procesos de contratación previstos en la Ley del Sector Hidrocarburos; LVII. Supervisar la elaboración del dictamen y, en su caso, la resolución de la unificación de campos o yacimientos de extracción para los efectos referidos en la Ley del Sector Hidrocarburos, y remitir al superior para su presentación y aprobación por el Comité de Asignaciones, Contratos y Permisos; LVIII. Emitir opinión respecto del dictamen con las condiciones para la coexistencia de actividades extractivas; LIX. Coordinar la integración de expedientes de los procedimientos administrativos por el presunto incumplimiento de obligaciones o por violaciones a la Ley del Sector Hidrocarburos y demás disposiciones jurídicas aplicables; LX. Someter a consideración la persona titular de la Subsecretaría de Hidrocarburos o, en su caso, del Comité de Asignaciones, Contratos y Permisos, a través de la Unidad de Asuntos Jurídicos, el inicio y resolución del procedimiento administrativo de sanción o por posibles incumplimientos, en términos de las atribuciones que se otorgan a la Secretaría en la Ley del Sector Hidrocarburos y demás disposiciones jurídicas aplicables; LXI. Emitir resolución para la acreditación de capacidades legales, financieras, técnicas, de experiencia y de ejecución para los procedimientos de cesión de cambio de control corporativo y de gestión, y LXII. Revisar y opinar técnicamente la documentación que se someta a consideración de los órganos colegiados en los que la Subsecretaría de Hidrocarburos tenga representación.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LA SUBSECRETARÍA DE HIDROCA R BUROS Y SUS UNIDADES ADMINISTRATIVAS","seccion_nombre":null,"orden":27},{"id":"fa98c8d5-0bc9-4082-8dd3-c45f054fd6c7","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 27.","contenido":"- Corresponde a la Dirección General de Diseño, Desarrollo e Implementación de Asignaciones y Contratos de Exploración y Extracción el ejercicio de las atribuciones siguientes: I. Proponer, para aprobación superior, el dictamen respecto de la participación del Estado Mexicano en los contratos para la exploración y extracción; II. Requerir la información necesaria para el desarrollo de sus funciones, a órganos administrativos desconcentrados, entidades paraestatales, empresas públicas del Estado y empresas del sector y, en general, a toda persona física o moral que realice cualquiera de las actividades a que se refieren la Ley del Sector Hidrocarburos; III. Recibir, y evaluar las solicitudes de la empresa pública del Estado respecto de la migración de asignaciones a contratos para la exploración y extracción de hidrocarburos y elaborar el proyecto de admisión; IV. Elaborar el proyecto de procedencia de la solicitud de migración de asignaciones a contratos para la exploración y extracción; V. Elaborar y proponer para aprobación superior, los anteproyectos de lineamientos técnicos para la creación de alianzas o asociaciones entre la empresa pública del Estado y personas morales, para los casos de Asignaciones que migren a contratos para la exploración y extracción de hidrocarburos; VI. Recibir y evaluar las solicitudes de contratos para la exploración y extracción de gas natural contenido en la veta de carbón mineral y producido por esta; VII. Supervisar y vigilar el cumplimiento de los lineamientos técnicos que emita la Subsecretaría de Hidrocarburos, respecto a las licitaciones que excepcionalmente se lleven a cabo para la adjudicación de contratos para la exploración y extracción de hidrocarburos; VIII. Analizar y evaluar los riesgos y las garantías contractuales desde el punto de vista financiero y legal, en los procesos excepcionales de licitación de las áreas para realizar actividades de exploración y extracción de hidrocarburos; IX. Elaborar el dictamen para seleccionar el modelo de los títulos de asignación en áreas en posesión del Estado; X. Elaborar y presentar a su superior jerárquico, los proyectos de títulos de asignación; XI. Elaborar la convocatoria y las bases de los procesos de licitación de los contratos para la exploración y extracción de hidrocarburos; XII. Elaborar los términos y condiciones para la suscripción de los contratos para la exploración y extracción de hidrocarburos para los procesos excepcionales de las licitaciones; XIII. Elaborar el proyecto de resolución y los términos y condiciones para la suscripción de los contratos para la exploración y extracción de gas natural asociado a la veta de carbón mineral y producido por esta; XIV. Recibir, evaluar e instrumentar el procedimiento para la atención de las solicitudes de la sustitución de asignaciones para desarrollo propio por asignaciones para desarrollo mixto que solicite Petróleos Mexicanos; XV. Elaborar el proyecto de sustitución de asignaciones para desarrollo propio por asignaciones para desarrollo mixto que solicite Petróleos Mexicanos; XVI. Recibir, evaluar e instrumentar el procedimiento para la atención de las solicitudes de cesión de control corporativo y de gestión o de cesión del interés de participación, en términos de las disposiciones legales aplicables; XVII. Elaborar propuesta para aprobación superior de procedencia o improcedencia de las solicitudes de cesión de control corporativo y de gestión o de cesión del interés de participación, en términos de las disposiciones legales aplicables; XVIII. Valorar y emitir los proyectos de propuesta de los procedimientos asociados a las asignaciones para desarrollo mixto, de conformidad con la Ley del Sector Hidrocarburos y las disposiciones jurídicas aplicables; XIX. Recibir y evaluar las solicitudes para la acreditación de capacidades para empresas, en términos de las disposiciones legales aplicables; XX. Elaborar propuesta de resolución de la acreditación de capacidades para empresas, en términos de las disposiciones legales aplicables; XXI. Recibir y evaluar las solicitudes de autorización para la celebración de alianzas o asociaciones en las que se lleve a cabo una cesión; XXII. Elaborar la propuesta de resolución de la autorización para la celebración de alianzas o asociaciones en las que se lleve a cabo una cesión; XXIII. Recibir y evaluar las solicitudes para imponer Gravámenes sobre el Interés de Participación; XXIV. Elaborar propuesta de autorización para las solicitudes para imponer gravámenes sobre el interés de participación; XXV. Recibir y registrar los avisos de modificación de capital social o de Interés de Participación de los contratos para la exploración y extracción de hidrocarburos; XXVI. Emitir opinión técnica para la determinación de las áreas en posesión del Estado para la exploración y extracción de hidrocarburos, para asignaciones o contratos; XXVII. Evaluar las consultas relacionadas con los términos y condiciones de las asignaciones y las cláusulas de los contratos y elaborar el proyecto de atención; XXVIII. Elaborar proyecto de opinión del dictamen para la coexistencia de actividades extractivas con actividades de exploración y extracción de hidrocarburos; XXIX. Administrar el registro y control del contrato mixto; XXX. Elaborar los proyectos de dictamen y, en su caso, los proyectos de resolución de la unificación de campos o yacimientos de extracción para los efectos referidos en la Ley del Sector Hidrocarburos; XXXI. Evaluar las capacidades legales, financieras, técnicas, de experiencia y de ejecución para los procedimientos de cesión de cambio de control corporativo y de gestión y emitir dictamen; XXXII. Elaborar los términos y condiciones de contratos, convenios y demás instrumentos jurídicos necesarios en materia de comercialización de hidrocarburos; XXXIII. Instrumentar los procesos y procedimientos necesarios para atender los avisos, notificaciones, informes, y trámites que deriven de los contratos de comercialización de hidrocarburos; XXXIV. Coordinar la integración de expedientes de los procedimientos administrativos por el presunto incumplimiento de obligaciones o por violaciones a la Ley del Sector Hidrocarburos y demás disposiciones jurídicas aplicables, y XXXV. Revisar y opinar técnicamente la documentación que se someta a consideración de los órganos colegiados en los que la Subsecretaría de Hidrocarburos tenga representación.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LA SUBSECRETARÍA DE HIDROCA R BUROS Y SUS UNIDADES ADMINISTRATIVAS","seccion_nombre":null,"orden":28},{"id":"d8507603-9150-4276-b2bb-ab58fb5fa27c","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 28.","contenido":"- Corresponde a la Dirección General de Proyectos de Regulación, Normas Oficiales Mexicanas y Estándares el ejercicio de las atribuciones siguientes: I. Analizar la política pública y programas en materia del sector hidrocarburos, y elaborar, en coordinación con las unidades administrativas competentes, los proyectos de emisión y modificación a las políticas públicas y programas relativas al sector hidrocarburos; II. Elaborar, analizar y opinar los proyectos de iniciativas de leyes, reglamentos, decretos, acuerdos, tratados y convenios internacionales, lineamientos, instructivos, criterios, metodologías, parámetros, directivas, reglas, manuales, políticas y demás disposiciones técnicas y administrativas de carácter general, relativas al sector hidrocarburos, en coordinación con las unidades administrativas competentes; III. Elaborar, analizar y opinar los proyectos de creación, modificación y cancelación de normas oficiales mexicanas, ordenamientos técnicos, lineamientos, procedimientos de evaluación de la conformidad, procedimientos de homologación, así como otras disposiciones técnicas, relacionadas con el sector hidrocarburos, en coordinación con las unidades administrativas competentes; IV. Identificar y evaluar estándares técnicos nacionales e internacionales, así como las mejores prácticas de la industria; V. Proponer la estrategia regulatoria y normativa de la Subsecretaría de Hidrocarburos, con base en la legislación aplicable y los conceptos de eficiencia regulatoria; VI. Participar en los procesos de modernización y adecuación del marco normativo, coordinación con las unidades administrativas competentes; VII. Desarrollar y ejecutar las acciones relacionadas con la mejora regulatoria de la Subsecretaría de Hidrocarburos, en coordinación con las unidades administrativas competentes; VIII. Elaborar los análisis de impacto regulatorio relativos a los proyectos de leyes, reglamentos, decretos, acuerdos, manuales, instructivos, lineamientos, normas oficiales mexicanas, y demás disposiciones técnicas y administrativas de carácter general, que proponga la Subsecretaría de Hidrocarburos y sus unidades administrativas, y presentarlos a la Unidad de Asuntos Jurídicos para su gestión; IX. Desarrollar las acciones necesarias para la integración de la solicitud para el registro de los trámites que deban ser inscritos en el Registro Federal de Trámites y Servicios, en coordinación con las unidades administrativas competentes, y presentarla a la Unidad de Asuntos Jurídicos para la obtención del registro; X. Ejecutar el programa de mejora regulatoria a cargo de la Subsecretaría de Hidrocarburos, de conformidad con las disposiciones jurídicas aplicables; XI. Inscribir y actualizar la información de las personas servidoras públicas autorizadas para realizar inspecciones y verificaciones en el padrón respectivo, de conformidad con la Ley General de Mejora Regulatoria; XII. Evaluar e informar a su superior jerárquico, cuando se observe que las actividades y operaciones de las empresas públicas del Estado obstaculizan la competencia y el desarrollo eficiente de los mercados, así como la política pública en materia de exploración y extracción de hidrocarburos, y XIII. Revisar y opinar técnicamente la documentación que se someta a consideración de los órganos colegiados en los que la Subsecretaría de Hidrocarburos tenga representación.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LA SUBSECRETARÍA DE HIDROCA R BUROS Y SUS UNIDADES ADMINISTRATIVAS","seccion_nombre":null,"orden":29},{"id":"944ffbc4-fbdd-46b3-8a2b-025c1a1740f9","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 29.","contenido":"- Corresponde a la Dirección General de Desarrollo de Argumentación Técnica para la Implementación de la Política Regulatoria del Sector Hidrocarburos el ejercicio de las atribuciones siguientes: I. Analizar, elaborar y emitir documentos de análisis técnico y normativo, respecto de los actos administrativos que emita la Subsecretaría de Hidrocarburos y sus unidades administrativas; II. Revisar y analizar que los actos administrativos emitidos por la Subsecretaría de Hidrocarburos y sus unidades administrativas, en el ejercicio de sus funciones, cumplan con los elementos y requisitos de validez del acto administrativo y se emitan conforme al marco jurídico aplicable; III. Atender las solicitudes de transparencia que sean competencia de la Subsecretaría de Hidrocarburos, en coordinación con las unidades administrativas competentes, así como proponer los alegatos que deben formularse dentro de los respectivos recursos administrativos de revisión; IV. Realizar las gestiones necesarias para cumplir con las determinaciones de la autoridad competente en materia de transparencia emitidas en los recursos administrativos de revisión, en coordinación con las unidades administrativas competentes; V. Realizar las gestiones necesarias para cumplir con la normatividad aplicable en materia de clasificación de la información y elaboración de versiones públicas, en coordinación con las unidades administrativas competentes; VI. Realizar las gestiones necesarias para que la Subsecretaría de Hidrocarburos y sus unidades administrativas cumplan con sus obligaciones en materia de transparencia, de conformidad con la normatividad aplicable; VII. Interpretar el marco jurídico aplicable y proponer los criterios de aplicación, así como la adecuada aplicación de las normas relacionadas con el sector hidrocarburos, en los actos administrativos que sean emitidos por la Subsecretaría de Hidrocarburos o sus unidades administrativas; VIII. Proponer los criterios de interpretación administrativa de las normas relacionadas con el sector hidrocarburos, en coordinación con las unidades administrativas competentes; IX. Formular proyectos de opinión, en coordinación con las unidades administrativas competentes, respecto de criterios de interpretación administrativa, solicitados por la Unidad de Asuntos Jurídicos; X. Proporcionar los elementos y realizar las gestiones necesarias para que la Unidad de Asuntos Jurídicos publique los criterios de interpretación y aplicación para efectos administrativos, que expida el Subsecretario de Hidrocarburos o sus unidades administrativas; XI. Proponer estrategias jurídicas y elaborar los argumentos técnico-jurídicos en las materias especializadas que son competencia de la Subsecretaría de Hidrocarburos, para la defensa jurídica de los asuntos contenciosos que lleva la Unidad de Asuntos Jurídicos ante las autoridades jurisdiccionales, en representación legal de la Secretaría de Energía; XII. Coordinar la integración de expedientes de los procedimientos administrativos por el presunto incumplimiento de obligaciones o por violaciones a la Ley del Sector Hidrocarburos y demás disposiciones jurídicas aplicables; XIII. Realizar las gestiones necesarias, en coordinación con las unidades administrativas competentes, para dar cumplimiento a las sentencias emitidas por las autoridades jurisdiccionales, que sean competencia de la Subsecretaría de Hidrocarburos, a solicitud de la Unidad de Asuntos Jurídicos; XIV. Analizar, consolidar y elaborar la información y documentación técnica jurídica, relacionada con las materias especializadas que son competencia de la Subsecretaría de Hidrocarburos, necesaria para atender los requerimientos de la Unidad de Asuntos Jurídicos; XV. Analizar y proponer, en coordinación con las unidades administrativas competentes, la opinión de los anteproyectos de política pública, iniciativas de leyes y decretos, así como de disposiciones administrativas de carácter general, que sean competencia de la Subsecretaría de Hidrocarburos, y sean solicitadas por los órganos legislativos; XVI. Atender, analizar, opinar y dar seguimiento a las proposiciones con punto de acuerdo, que sean competencia de la Subsecretaría de Hidrocarburos, y sean solicitadas por los órganos legislativos; XVII. Proponer las estrategias, mecanismos, actos jurídicos y acciones para la ejecución e implementación de las políticas, programas, decretos, acuerdos y demás disposiciones administrativas de carácter general, relacionadas con el sector hidrocarburos, en coordinación con las áreas competentes de la Administración Pública Federal o cualquier otro ente participante del mercado; XVIII. Atender y elaborar las respuestas a las solicitudes o consultas técnico-jurídicas que le sean formuladas por la Subsecretaría de Hidrocarburos o sus unidades administrativas, en coordinación con las unidades administrativas competentes; XIX. Atender y elaborar las respuestas a las solicitudes o consultas ciudadanas que sean competencia de la Subsecretaría de Hidrocarburos, en coordinación con las unidades administrativas competentes; XX. Atender, en coordinación con las unidades administrativas competentes, los requerimientos realizados por los órganos fiscalizadores del Estado, y XXI. Revisar y opinar técnicamente la documentación que se someta a consideración de los órganos colegiados en los que la Subsecretaría de Hidrocarburos tenga representación.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LA SUBSECRETARÍA DE PLANEACIÓN Y TRANSICIÓN ENERGÉTICA Y SUS UNIDADES ADMINISTRATIVAS","seccion_nombre":null,"orden":30},{"id":"e20fbb6c-81cd-4f81-b718-d5df3bcf8153","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 30.","contenido":"- Corresponde a la Unidad Técnica de Exploración el ejercicio de las atribuciones siguientes: I. Coordinar la aplicación de los ordenamientos legales y demás normas jurídicas que de estos deriven, tales como decretos, acuerdos y políticas cuyas disposiciones regulen o estén vinculadas a las actividades de exploración de hidrocarburos; II. Participar con las unidades administrativas de la Secretaría, en la elaboración de los anteproyectos de planeación energética relacionados con la exploración de hidrocarburos, cuantificación de recursos prospectivos y contingentes, la investigación y desarrollo tecnológico nacionales relacionados con la exploración de hidrocarburos; III. Evaluar las referencias tecnológicas utilizadas conforme a las mejores prácticas de la industria en materia de su competencia; IV. Coordinar investigaciones y estudios para la identificación y propuesta de la tecnología más adecuada para la exploración de hidrocarburos en función de los beneficios esperados; V. Evaluar las nominaciones de áreas en posesión del Estado que realicen la empresa pública del Estado o cualquier persona moral sobre las cuales exista interés para llevar a cabo la exploración de hidrocarburos; VI. Proponer, para aprobación superior, la selección y la determinación de las áreas en posesión del Estado para la exploración de hidrocarburos; VII. Implementar los mecanismos para el resguardo de las áreas en posesión del Estado, en materia de su competencia; VIII. Emitir el dictamen técnico respecto del otorgamiento, modificación, sustitución, renuncia o revocación de asignaciones para la realización de actividades de exploración; IX. Proporcionar a la Unidad de Desarrollo de Modelos Contractuales y de Asignaciones, Proyectos Regulatorios y Argumentación Técnica, la propuesta de los términos técnicos y operativos para el otorgamiento y modificación de las asignaciones para la realización de actividades de exploración; X. Coordinar y supervisar, el dictamen técnico sobre la procedencia de la sustitución de asignaciones de desarrollo propio a asignaciones de desarrollo mixto, en materia de su competencia; XI. Coordinar y supervisar el dictamen técnico sobre la procedencia de la solicitud de migración de asignaciones para desarrollo propio a contratos para la exploración y extracción, en materia de su competencia; XII. Emitir el dictamen técnico de la evaluación económica y técnica de las áreas contractuales de exploración de hidrocarburos que excepcionalmente se sujeten a licitación; XIII. Proporcionar a la Unidad de Desarrollo de Modelos Contractuales y de Asignaciones, Proyectos Regulatorios y Argumentación Técnica, opinión técnica respecto de los modelos de contratación para cada área contractual, en materia de su competencia; XIV. Emitir dictamen técnico respecto de las solicitudes de contratos para la exploración y extracción del gas natural contenido en las vetas de carbón mineral y producido por esta, en materia de su competencia; XV. Proporcionar a la Unidad de Desarrollo de Modelos Contractuales y de Asignaciones, Proyectos Regulatorios y Argumentación Técnica, el dictamen con las condiciones para la coexistencia de actividades extractivas, de su competencia; XVI. Analizar y proponer al superior jerárquico, el dictamen técnico para la aprobación o rechazo de los programas de transición, de los planes de exploración, los programas asociados y sus modificaciones, así como las solicitudes de periodos adicionales de exploración, suspensión de actividades de exploración y prórrogas a la vigencia de las asignaciones y los contratos; XVII. Analizar y proponer al superior jerárquico, la resolución del informe de evaluación e informe de evaluación inicial que presenten los asignatarios y contratistas; XVIII. Analizar y proponer al superior, el dictamen técnico para la aprobación de los programas anuales de inversión y operación de los contratos para la exploración y extracción, en el ámbito de su competencia; XIX. Proporcionar a la Unidad de Seguimiento y Supervisión de Asignaciones, Contratos y Permisos, la opinión técnica para la acreditación de compromisos de trabajo, programas mínimos de trabajo y actividades de exploración que presenten los asignatarios y contratistas, según corresponda; XX. Validar los informes sobre cualquier siniestro, hecho o contingencia derivada de las operaciones que pongan en peligro la vida, la salud y seguridad públicas, el medio ambiente, la seguridad de las instalaciones o la producción de Hidrocarburos, así como los informes de las causas que los originaron, las medidas tomadas para su control y, en su caso, remediación, en materia de su competencia; XXI. Analizar y proponer para aprobación superior, el anteproyecto y dictamen técnico para establecer zonas de salvaguarda en las que se prohíban las actividades de exploración de hidrocarburos, así como para incorporar o desincorporar áreas específicas a estas; XXII. Proponer al superior jerárquico, en materia de su competencia , la participación obligatoria de una empresa pública del Estado en los contratos para la exploración y extracción en aquellas áreas contractuales en las que exista la posibilidad de encontrar yacimientos transfronterizos; XXIII. Participar en foros internacionales representando a la Secretaría, en el ámbito de su competencia, con la intervención que corresponda a la Secretaría de Relaciones Exteriores y proponer la celebración de convenios, acuerdos y tratados internacionales en materia de hidrocarburos, así como participar en la concertación y seguimiento de la ejecución de los acuerdos internacionales en materia de exploración y extracción de hidrocarburos en yacimientos transfronterizos de los que el Estado mexicano sea parte; XXIV. Proponer al superior jerárquico, las autorizaciones de perforación de pozos exploratorios; XXV. Proponer al superior jerárquico, las autorizaciones para el no ejercicio de derechos conferidos en las autorizaciones otorgadas; XXVI. Proponer al superior jerárquico, las autorizaciones de perforación de pozos, así como pronunciarse respecto de las solicitudes de prórroga o renovación de las autorizaciones de perforación de pozos exploratorios; XXVII. Proponer al superior jerárquico, las autorizaciones para las actividades de reconocimiento y exploración superficial; XXVIII. Proponer al superior jerárquico, las autorizaciones para las actividades de reconocimiento y exploración superficial, así como pronunciarse respecto de las solicitudes de prórroga o renovación de las autorizaciones para las actividades de reconocimiento y exploración superficial; XXIX. Supervisar la administración del padrón en materia de reconocimiento y exploración superficial, así como la inscripción de los autorizados en el padrón; XXX. Elaborar los términos y condiciones de los contratos para realizar actividades de reconocimiento y exploración superficial y proponerlos a su aprobación, y en su caso, llevar a cabo el procedimiento para contratar a cualquier empresa pública del Estado, entidades públicas, instituciones académicas o particulares para llevar a cabo dichas actividades conforme a la normativa aplicable; XXXI. Supervisar y coordinar el análisis de la información técnica que entreguen los asignatarios, contratistas y autorizados , derivada de las actividades de reconocimiento y exploración superficial, así como de la exploración de hidrocarburos, para la evaluación del potencial petrolero del país y generar la información que permita el desarrollo de la política pública en materia de recursos petroleros; XXXII. Remitir los elementos técnicos a la Unidad de Seguimiento y Supervisión de Asignaciones, Contratos y Permisos respecto del cumplimiento de las obligaciones de los autorizados, asignatarios y contratistas en materia de perforación de pozos exploratorios, reconocimiento y exploración superficial y demás actividades en materia de exploración; XXXIII. Proporcionar los elementos técnicos a la unidad administrativa que corresponda sobre la probable existencia de alguna de las causales de revocación de la asignación y rescisión de contratos para la exploración y extracción; XXXIV. Coordinar y supervisar la administración de las Litotecas Nacionales de la Industria de Hidrocarburos; XXXV. Coordinar y supervisar el acopio, resguardo, uso, administración, actualización y publicación de la información referida en los artículos 60, 61, 63 y 124 de la Ley del Sector Hidrocarburos, en materia de exploración y extracción; XXXVI. Coordinar la atención de las solicitudes de acceso a la información, publicación, entrega u obtención de información a que se refiere el artículo 60 de la Ley del Sector Hidrocarburos; XXXVII. Coordinar la administración de los datos para los procedimientos excepcionales de licitación de contratos para la exploración y extracción, en el ámbito de su competencia; XXXVIII. Supervisar los estudios económicos y de análisis relacionados con las actividades de exploración de hidrocarburos; XXXIX. Coordinar lo relativo a la evaluación económica y los programas de inversiones en materia de exploración de hidrocarburos; XL. Coordinar el desarrollo de análisis estadísticos sobre las actividades de su competencia; XLI. Aprobar la consolidación de la cuantificación del potencial de hidrocarburos del país considerando la estimación de los recursos prospectivos y contingentes; XLII. Proponer, para aprobación superior, el informe de cuantificación del potencial de hidrocarburos del país considerando la estimación de los recursos prospectivos y contingentes; XLIII. Publicar los análisis estadísticos sobre la producción de hidrocarburos y reservas, incluyendo la información de reportes de estimación y estudios de evaluación o cuantificación y certificación, la relación entre producción y reservas, los recursos contingentes y prospectivos, la información geológica, geofísica, petrofísica, petroquímica y demás que se obtenga de las actividades de reconocimiento y exploración superficial, así como de la exploración y extracción de hidrocarburos, en coordinación con la Unidad Técnica de Extracción, de conformidad con la normatividad de aplicable; XLIV. Poner a disposición del público la información a que se refiere el artículo 124 de la Ley del Sector Hidrocarburos, en el ámbito de su competencia; XLV. Evaluar el desempeño y la eficiencia de proyectos de exploración; XLVI. Administrar la información geoespacial del sector energético, a través de herramientas tecnológicas que permitan fortalecer la toma de decisiones destinadas al cumplimiento de las atribuciones de la Secretaría; XLVII. Avalar la planificación, administración y coordinación de la integración de datos geoespaciales mediante la creación, desarrollo e implementación de un Sistema de Información Geográfica para almacenar y visualizar información cartográfica y bases de datos del sector energético; XLVIII. Asegurar la planificación, regulación, difusión y actualización de la información cartográfica y estadística relacionada al sector energético con factores socio-organizativos, físico-ambientales, económicos y financieros para fortalecer la toma de decisiones destinadas al cumplimiento de las atribuciones de la Secretaría; XLIX. Establecer las mejoras en la organización de la información geográfica, así como los procesos de revisión y actualización de la información geoespacial; L. Resolver y proponer a su superior, las respuestas a solicitudes externas e internas de información geográfica de acuerdo con las disposiciones oficiales vigentes; LI. Administrar la información geoespacial del sector energético, estableciendo acuerdos y convenios con instituciones públicas y privadas que producen información geográfica y estadística para mantener actualizada y homologada la información; LII. Asegurar el desarrollo de la infraestructura de datos espaciales de la Secretaría, estableciendo normas internas, soluciones basadas en mejores prácticas nacionales e internacionales, y organizativas sustentables, a fin de mejorar el acceso a la información geoespacial del sector energético; LIII. Asegurar el diseño y estrategias para la actualización de la base de datos de la Secretaría para garantizar su calidad e integridad de la información geoespacial; LIV. Evaluar y proponer para aprobación del superior, los mecanismos eficientes de acceso a la información geográfica y estadística para mejorar el servicio de atención a usuarios del sector energético; LV. Conocer de las posibles violaciones que se detecten al marco normativo, ordenar las medidas que correspondan y emitir recomendaciones al respecto en el ámbito de su competencia; LVI. Emitir opinión técnica que soliciten las Unidades Administrativas, en materia de su competencia, y LVII. Revisar y opinar técnicamente la documentación que se someta a consideración de los órganos colegiados en los que la Subsecretaría de Hidrocarburos tenga representación.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LA SUBSECRETARÍA DE HIDROCA R BUROS Y SUS UNIDADES ADMINISTRATIVAS","seccion_nombre":null,"orden":31},{"id":"13994036-15c9-4202-9e2d-0504b3d82f48","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 31.","contenido":"- Corresponde a la Dirección General de Registro de Recursos Energéticos y Prospectivos de la Nación el ejercicio de las atribuciones siguientes: I. Aplicar los ordenamientos legales y demás normas jurídicas que de estos deriven, cuyas disposiciones regulen o estén vinculadas con las actividades de exploración de Hidrocarburos; II. Administrar y mantener actualizadas las Litotecas Nacionales de la Industria de hidrocarburos; III. Atender, gestionar y resolver las solicitudes de acceso a la información, publicación, entrega u obtención de información a que se refiere el artículo 60 de la Ley del Sector Hidrocarburos; IV. Recabar, acopiar, resguardar, usar, administrar y actualizar, así como publicar la información geológica, geofísica, petrofísica, petroquímica, materiales de campo, así como la información procesada, interpretada e integrada y, en general, la que se obtenga o se haya obtenido de las actividades de reconocimiento y exploración superficial y de exploración de hidrocarburos; V. Resguardar, preservar y administrar en materia de su competencia, los núcleos de roca, recortes de perforación y muestras de hidrocarburos en términos de la normativa aplicable; VI. Proponer, desarrollar y coordinar la publicación de estudios económicos y de análisis relacionados con el sector de hidrocarburos, en coordinación con las unidades administrativas competentes; VII. Definir, coordinar, asegurar y resguardar la información geoespacial del sector energético, a través de herramientas tecnológicas que permitan fortalecer la toma de decisiones destinadas al cumplimiento de las atribuciones de la Secretaría; VIII. Planificar, administrar y coordinar la integración de datos geoespaciales mediante la creación, desarrollo e implementación de un Sistema de Información Geográfica para almacenar y visualizar información cartográfica y bases de datos del sector energético; IX. Planificar, regular, difundir y actualizar información cartográfica y estadística relacionada al sector energético con factores socio-organizativos, físico-ambientales, económicos y financieros para fortalecer la toma de decisiones destinadas al cumplimiento de las atribuciones de la Secretaría de Energía; X. Promover y coordinar mejoras en la organización de la información geográfica, así como los procesos de revisión y actualización de la información geoespacial; XI. Administrar y verificar respuestas a solicitudes externas e internas de información geográfica de acuerdo con las disposiciones oficiales vigentes; XII. Promover y coordinar la obtención y generación de información geoespacial del sector energético, estableciendo acuerdos y convenios con instituciones públicas y privadas que producen información geográfica y estadística para mantener actualizada y homologada la información; XIII. Coordinar el desarrollo de la infraestructura de datos geoespaciales de la Secretaría, estableciendo normas internas para generar soluciones basadas en mejores prácticas nacionales e internacionales y organizativas sustentables, a fin de dar certeza y precisión a la información geográfica y estadística del sector energético; XIV. Dirigir el diseño y las estrategias para la actualización de la base de datos de la Secretaría para garantizar su calidad e integridad de la información geoespacial; XV. Regular y coordinar mecanismos eficientes de acceso a la información geográfica y estadística para mejorar el servicio de atención a usuarios del sector energético; XVI. Elaborar análisis estadísticos sobre las actividades en materia de su competencia; XVII. Administrar los cuartos de datos para los procedimientos excepcionales de licitación de contratos, en el ámbito de su competencia; XVIII. Emitir opinión técnica que soliciten las unidades administrativas, en materia de su competencia; XIX. Conocer de las posibles violaciones que se detecten al marco normativo, ordenar las medidas que correspondan y emitir recomendaciones al respecto en el ámbito de su competencia; XX. Coordinar la integración de los expedientes y proponer a la Unidad de Asuntos Jurídicos la tramitación del procedimiento administrativo de sanción o por posibles incumplimientos que sean de su competencia, y XXI. Revisar y opinar técnicamente la documentación que se someta a consideración de los órganos colegiados en los que la Subsecretaría de Hidrocarburos tenga representación.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LA SUBSECRETARÍA DE HIDROCA R BUROS Y SUS UNIDADES ADMINISTRATIVAS","seccion_nombre":null,"orden":32},{"id":"ec3b728c-c8ed-46c4-9f1d-6f61153e2899","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 32.","contenido":"- Corresponde a la Dirección General de Evaluación del Potencial de Hidrocarburos el ejercicio de las atribuciones siguientes: I. Aplicar ordenamientos legales y demás normas jurídicas que de estos deriven, cuyas disposiciones regulen o estén vinculadas con las actividades de Exploración de Hidrocarburos; II. Elaborar los anteproyectos de planeación energética relacionados con la exploración de hidrocarburos, cuantificación de recursos prospectivos y contingentes, la investigación y desarrollo tecnológico nacionales relacionados con la exploración de hidrocarburos; III. Participar en las investigaciones y estudios para la identificación y propuesta de utilización de la tecnología más adecuada para la exploración de hidrocarburos en función de resultados productivos y económicos; IV. Emitir opinión técnica respecto de las nominaciones de Áreas en posesión del Estado que realicen la empresa pública del Estado o cualquier persona moral sobre las cuales exista interés para llevar a cabo la exploración de hidrocarburos; V. Elaborar la opinión técnica para la selección y para la determinación de las áreas en posesión del Estado para desarrollar actividades de exploración; VI. Controlar y administrar las áreas en posesión del Estado, en materia de su competencia; VII. Elaborar y proponer al superior, la propuesta de términos técnicos y operativos para el otorgamiento y modificación de las Asignaciones para la realización de actividades de exploración; VIII. Elaborar opinión técnica de las Áreas Contractuales de exploración que excepcionalmente se sujetarán a licitación; IX. Analizar y opinar técnicamente en materia de su competencia, respecto de las solicitudes de Contratos para la Exploración y Extracción del gas natural contenido en las vetas de carbón mineral y producido por esta; X. Elaborar y proponer para aprobación, el anteproyecto y dictamen técnico para establecer las Zonas de Salvaguarda en las que se prohíban las actividades de exploración de hidrocarburos; así como para incorporar o desincorporar áreas específicas a estas; XI. Elaborar opinión técnica en la participación obligatoria de una empresa pública del Estado en los contratos para la exploración y extracción en aquellas áreas contractuales en las que exista la posibilidad de encontrar yacimientos transfronterizos, en materia de su competencia; XII. Coadyuvar en la implementación, en materia de su competencia en la ejecución y seguimiento de los acuerdos internacionales en materia de exploración de hidrocarburos en yacimientos transfronterizos de los que el Estado mexicano sea parte; XIII. Desarrollar y aplicar metodologías para la evaluación económica del potencial exploratorio; XIV. Elaborar análisis estadísticos sobre las actividades en materia de su competencia; XV. Realizar los estudios para la cuantificación del potencial de Hidrocarburos del país considerando la estimación de los Recursos Prospectivos y contingentes; XVI. Realizar y proponer al superior el análisis estadísticos de la estimación y estudios de evaluación o cuantificación y certificación, los recursos Contingentes y Prospectivos, la información geológica, geofísica, petrofísica, petroquímica y demás que se obtenga de las actividades de Reconocimiento y Exploración Superficial y la Exploración de Hidrocarburos; XVII. Elaborar, publicar y actualizar las fichas técnicas de las Asignaciones, Contratos y Autorizaciones en coordinación con las Unidades Administrativas competentes; XVIII. Emitir opinión técnica que soliciten las Unidades Administrativas, en materia de su competencia; XIX. Conocer de las posibles violaciones que se detecten al marco normativo, ordenar las medidas que correspondan y emitir recomendaciones al respecto en el ámbito de su competencia, y XX. Revisar y opinar técnicamente la documentación que se someta a consideración de los órganos colegiados en los que la Subsecretaría de Hidrocarburos tenga representación.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LA SUBSECRETARÍA DE ELECTRICIDAD Y SUS UNIDADES ADMINISTRATIVAS","seccion_nombre":null,"orden":33},{"id":"07243591-72f5-4404-8027-110c88da20ae","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 33.","contenido":"- Corresponde a la Dirección General de Autorizaciones de Estudios y Pozos Exploratorios el ejercicio de las atribuciones siguientes: I. Revisar la aplicación de los ordenamientos legales y demás normas jurídicas que de éstos deriven, cuyas disposiciones regulen o estén vinculadas con las actividades de exploración de hidrocarburos; II. Analizar las referencias tecnológicas utilizadas conforme a las mejores prácticas de la industria en materia de su competencia; III. Elaborar para aprobación superior, el proyecto para la emisión de las autorizaciones de perforación de pozos exploratorios; IV. Elaborar para aprobación superior, el proyecto para la emisión de las autorizaciones de pozos exploratorios, así como para el pronunciamiento de las solicitudes de prórroga o renovación de las autorizaciones de perforación de pozos exploratorios; V. Proporcionar a su superior, los elementos técnicos y proyecto para la emisión de las autorizaciones para el no ejercicio de derechos conferidos en las autorizaciones otorgadas; VI. Elaborar para aprobación superior, el proyecto para la emisión de las autorizaciones correspondientes a las actividades de reconocimiento y exploración superficial; VII. Administrar el padrón en materia de reconocimiento y exploración superficial, así como inscribir a los autorizados en el padrón; VIII. Elaborar y proponer al superior, el proyecto de términos y condiciones de los contratos para llevar a cabo actividades de reconocimiento y exploración superficial y proponer se lleve a cabo el procedimiento para contratar a cualquier empresa pública del Estado, entidades públicas, instituciones académicas o particulares para llevar a cabo dichas actividades conforme a la normativa aplicable; IX. Analizar la información técnica que entreguen los asignatarios, contratistas y autorizados , derivada de las actividades de reconocimiento y exploración superficial, así como de la exploración de hidrocarburos, para la evaluación del potencial petrolero del país y, en su caso, elaborar la información técnica que permita el desarrollo de la política pública en materia de recursos petroleros; X. Elaborar, para aprobación superior, la opinión técnica para la declaratoria de utilidad pública en predios de propiedad pública , social y privada en las actividades a que refiere el artículo 61 de la Ley; XI. Analizar técnicamente el cumplimiento de las obligaciones de los autorizados, asignatarios y contratistas en materia de perforación de pozos exploratorios, reconocimiento y exploración superficial y demás actividades en materia de exploración; XII. Elaborar análisis estadísticos sobre las actividades en materia de su competencia; XIII. Emitir opinión técnica que soliciten las unidades administrativas, en materia de su competencia; XIV. Conocer de las posibles violaciones que se detecten al marco normativo, ordenar las medidas que correspondan y emitir recomendaciones al respecto en el ámbito de su competencia, y XV. Revisar y opinar técnicamente la documentación que se someta a consideración de los órganos colegiados en los que la Subsecretaría de Hidrocarburos tenga representación.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LA SUBSECRETARÍA DE HIDROCA R BUROS Y SUS UNIDADES ADMINISTRATIVAS","seccion_nombre":null,"orden":34},{"id":"81744849-be17-47ab-a84a-6af7882a9d18","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 34.","contenido":"- Corresponde a la Dirección General de Planes de Exploración y Programas de Evaluación el ejercicio de las atribuciones siguientes: I. Aplicar los ordenamientos legales y demás normas jurídicas que de éstos deriven, cuyas disposiciones regulen o estén vinculadas con las actividades de Exploración de Hidrocarburos; II. Proponer a su superior, el dictamen técnico respecto del otorgamiento, modi ficación, sustitución, renuncia o revocación de Asignaciones para la realización de actividades de Exploración; III. Revisar y proponer al superior, la opinión técnica de los Programas de Transición, de los planes de Exploración, programas asociados, y sus modificaciones, así como las solicitudes de periodos adicionales de Exploración, suspensión de actividades de exploración y prórrogas a la vigencia de las Asignaciones y los Contratos; IV. Elaborar la propuesta de resolución respecto del informe de evaluación e informes de evaluación inicial que presenten los Asignatarios y Contratistas; V. Elaborar la opinión técnica para la acreditación de compromisos de trabajo, programas mínimos de trabajo y actividades de Exploración que presenten los Asignatarios y Contratistas, según corresponda; VI. Informar al superior, en e l ámbito de sus competencias, la probable existencia de alguna de las causales de revocación de Asignaciones y rescisión de Contratos; VII. Elaborar el dictamen técnico sobre la procedencia de la sustitución de Asignaciones de desarrollo propio a Asignaciones de desarrollo mixto, en materia de su competencia; VIII. Elaborar el dictamen técnico sobre la procedencia de la migración de Asignaciones de desarrollo propio de Exploración a Contratos para la Exploración y Extracción de Hidrocarburos, en materia de su competencia; I X. Elaborar para aprobación superior, la opinión respecto de los modelos de contratación para cada Área Contractual; X. Elaborar la opinión técnica y económica de los programas anuales de inversión y operación de los Contratos para la Exploración y Extracción, en el ámbito de su competencia; X I . Elaborar y proponer las opiniones respecto a los presupuestos de los Contratos con recuperación de costos, así como la revisión de los presupuestos indicativos, previo a su registro ante el Fondo Mexicano del Petróleo; X I I. Elaborar y proponer al superior, propuesta sobre la coexistencia de actividades extractivas; XI I I. Recibir y evaluar, en términos de su competencia, los informes de los Asignatarios, Contratistas y Autorizados respecto a cualquier siniestro, hecho o contingencia, que como resultado de sus operaciones pongan en peligro la vida, la salud y seguridad públicas, el medio ambiente, la seguridad de las instalaciones o la producción de Hidrocarburos, así como los informes de las causas que los originaron, las medidas tomadas para su control y, en su caso, remediación; XI V . Elaborar y proponer las opiniones respecto de la evaluación económica y los programas del costo total asociado a los planes y programas, para la integración de los dictámenes técnicos respectivos o la resolución, según corresponda; XV. Definir los indicadores de referencia para evaluar la eficiencia de proyectos de Exploración; XV I . Proponer metodologías y realizar la evaluación económica de las Áreas Contractuales sujetas a procesos excepcionales de licitación; XV I I. Desarrollar y aplicar metodologías para las proyecciones de producción, inversiones y costos del sector de Exploración de Hidrocarburos, en coordinación con las Unidades Administrativas competentes; XVI I I. Elaborar análisis estadísticos sobre las actividades en materia de su competencia; XI X . Emitir opinión técnica que soliciten las Unidades Administrativas, en materia de su competencia; XX. Conocer de las posibles violaciones que se detecten al marco normativo, ordenar las medidas que correspondan y emitir recomendaciones al respecto en el ámbito de su competencia, y XX I . Revisar y opinar técnicamente la documentación que se someta a consideración de los órganos colegiados en los que la Subsecretaría de Hidrocarburos tenga representación.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LA SUBSECRETARÍA DE HIDROCA R BUROS Y SUS UNIDADES ADMINISTRATIVAS","seccion_nombre":null,"orden":35},{"id":"996e9bca-5d8d-42a3-b3db-21097f7f1ea1","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 35.","contenido":"- Corresponde a la Unidad Técnica de Extracción de Hidrocarburos el ejercicio de las atribuciones siguientes: I. Coordinar la aplicación de los ordenamientos legales y demás normas jurídicas que de éstos deriven, tales como decretos, acuerdos y políticas cuyas disposiciones regulen o estén vinculadas a las actividades de extracción de hidrocarburos; II. Participar con las unidades administrativas de la Secretaría, en la elaboración de los anteproyectos de planeación energética relativo a la extracción de hidrocarburos, cuantificación de reservas de hidrocarburos, la investigación y desarrollo tecnológico nacionales relacionados con la extracción de hidrocarburos; III. Evaluar las referencias tecnológicas utilizadas conforme a las mejores prácticas de la industria en materia de su competencia; IV. Coordinar investigaciones y estudios para la identificación y propuesta de utilización de la tecnología más adecuada para la extracción de hidrocarburos en función de resultados productivos y económicos; V. Evaluar las nominaciones de áreas en posesión del estado que realicen la empresa pública del estado o cualquier persona moral sobre las cuales exista interés para llevar a cabo la extracción de hidrocarburos; VI. Proponer, para aprobación superior, la selección y la determinación de las áreas en posesión del estado para la extracción de hidrocarburos; VII. Implementar los mecanismos para resguardar las áreas en posesión del estado, en materia de su competencia; VIII. Emitir el dictamen técnico respecto del otorgamiento, modificación, sustitución, renuncia o revocación de asignaciones para la realización de actividades de extracción; IX. Proporcionar a la Unidad de Desarrollo de Modelos Contractuales y de Asignaciones, Proyectos Regulatorios y Argumentación Técnica, la propuesta de los términos técnicos y operativos para el otorgamiento y modificación de las asignaciones para la realización de actividades de extracción; X. Coordinar y supervisar el dictamen técnico sobre la procedencia de la sustitución de asignaciones de desarrollo propio a asignaciones de desarrollo mixto, en materia de su competencia; XI. Coordinar y supervisar el dictamen técnico sobre la procedencia de la solicitud de migración de asignaciones de desarrollo propio a contratos para la exploración y extracción, en materia de su competencia; XII. Emitir el dictamen técnico de la evaluación económica y técnica de las áreas contractuales de extracción de hidrocarburos que excepcionalmente se sujeten a licitación; XIII. Proporcionar a la Unidad de Desarrollo de Modelos Contractuales y de Asignaciones, Proyectos Regulatorios y Argumentación Técnica, opinión técnica respecto de los modelos de contratación para cada área contractual, en materia de su competencia; XIV. Emitir el dictamen técnico respecto de las solicitudes de contratos para la exploración y extracción del gas natural contenido en las vetas de carbón mineral y producido por esta, en materia de su competencia; XV. Proporcionar a la Unidad de Desarrollo de Modelos Contractuales y de Asignaciones, Proyectos Regulatorios y Argumentación Técnica, el dictamen con las condiciones para la coexistencia de actividades extractivas de su competencia; XVI. Analizar y proponer al superior, el dictamen técnico para la aprobación o rechazo de los programas de transición, de los planes de desarrollo para la extracción, los programas asociados y sus modificaciones, suspensión de actividades de extracción y prórrogas a la vigencia de las asignaciones y los contratos; XVII. Resolver respecto a la incorporación de reservas que no cuenten con un informe de evaluación y la declaración de descubrimiento comercial, conforme a lo dispuesto en la normativa en materia de cuantificación y certificación de reservas; XVIII. Analizar y proponer al superior, el dictamen técnico para la aprobación o rechazo de los programas anuales de inversión y operación de los contratos para la exploración y extracción, en el ámbito de su competencia; XIX. Proporcionar a la Unidad de Seguimiento y Supervisión de Asignaciones, Contratos y Permisos, la opinión técnica para la acreditación de compromisos de trabajo, programas mínimos de trabajo y actividades de extracción que presenten los asignatarios y contratistas, según corresponda; XX. Validar los informes sobre cualquier siniestro, hecho o contingencia derivada de las operaciones que pongan en peligro la vida, la salud y seguridad públicas, el medio ambiente, la seguridad de las instalaciones o la producción de hidrocarburos, así como los informes de las causas que los originaron, las medidas tomadas para su control y, en su caso, remediación, en materia de su competencia; XXI. Proponer al superior jerárquico, el dictamen para determinar cómo inviable técnica o económicamente para la extracción a un pozo destinado para las actividades de exploración y extracción de hidrocarburos en asignaciones y contratos; XXII. Validar y proponer a la Unidad de Desarrollo de Modelos Contractuales y de Asignaciones, Proyectos Regulatorios y Argumentación Técnica , el dictamen para la instrucción de la unificación de campos o yacimientos; XXIII. Analizar y proponer para aprobación superior, el anteproyecto y dictamen técnico para establecer zonas de salvaguarda en las que se prohíban las actividades de extracción de hidrocarburos, así como para incorporar o desincorporar áreas específicas a éstas; XXIV. Proponer al superior jerárquico la participación obligatoria de una empresa pública del Estado en los contratos para la exploración y extracción en aquellas áreas contractuales en las que exista la posibilidad de encontrar yacimientos transfronterizos en materia de su competencia; XXV. Participar en foros internacionales en representación de la Secretaría, en el ámbito de su competencia, con la intervención que corresponda a la Secretaría de Relaciones Exteriores y proponer la celebración de convenios, acuerdos y tratados internacionales en materia de hidrocarburos, así como participar en la concertación y seguimiento de la ejecución de los acuerdos internacionales en materia de exploración y extracción de hidrocarburos en yacimientos transfronterizos de los que el Estado mexicano sea parte; XXVI. Proponer al superior jerárquico las autorizaciones de perforación de pozos tipo que utilicen como modelos de diseño y de pozos de desarrollo para la extracción en aguas profundas y ultra profundas; XXVII. Proponer al superior jerárquico las autorizaciones de la perforación de pozos, así como pronunciarse respecto de las solicitudes de prórroga o renovación de las autorizaciones de perforación de pozos tipo que utilicen como modelos de diseño y de pozos de desarrollo para la extracción en aguas profundas y ultra profundas; XXVIII. Supervisar la administración del registro de las autorizaciones de perforación de pozos tipo que utilicen como modelos de diseño, y de pozos de desarrollo para la extracción en aguas profundas y ultra profundas; XXIX. Supervisar la administración del registro de los avisos para perforación, terminación y abandono de pozos de desarrollo presentados por los asignatarios y contratistas; XXX. Ordenar la instalación de sistemas e instrumentos de medición; XXXI. Evaluar el potencial de recuperación avanzada y mejorada y validar los análisis sobre la definición y seguimiento de estrategias y proyectos relacionados; XXXII. Vigilar el cumplimiento de las obligaciones de los asignatarios y contratistas en materia de medición de hidrocarburos; XXXIII. Avalar la medición de la producción de hidrocarburos de los asignatarios y contratistas; XXXIV. Verificar e instruir que los asignatarios y contratistas cuenten con sistemas de medición para cada uno de los volúmenes de hidrocarburos extraídos, ubicados en campo y punto de transferencia de custodia; XXXV. Evaluar la eficiencia de los sistemas de medición, equipos y personal de asignatarios y contratistas; XXXVI. Vigilar el funcionamiento de los sistemas de medición instalados por los asignatarios y contratistas; XXXVII. Corroborar los reportes de producción por parte de los asignatarios y los contratistas que se consideran para el cálculo de las contraprestaciones, así como de los derechos e impuestos correspondientes; XXXVIII. Dictaminar la resolución de los actos relacionados con los procedimientos de ajuste que deriven de los reportes de producción y que se requieran para la comercialización, así como para el cálculo de las contraprestaciones, derechos e impuestos correspondientes; XXXIX. Difundir y remitir a las unidades administrativas y a las autoridades competentes la información de producción de hidrocarburos; XL. Proporcionar a la Unidad de Desarrollo de Modelos Contractuales y de Asignaciones, Proyectos Regulatorios y Argumentación Técnica de los términos y condiciones de los contratos de comercialización de Hidrocarburos para su validación; XLI. Elaborar los términos y condiciones de los contratos de servicio de comercialización de hidrocarburos y proponerlos a su aprobación, y en su caso, ordenar se lleve a cabo el procedimiento para contratar al comercializador de los hidrocarburos, conforme a la normativa aplicable; XLII. Colaborar con la Unidad de Desarrollo de Modelos Contractuales y de Asignaciones, Proyectos Regulatorios y Argumentación Técnica con la información técnica necesaria para suscribir los contratos, convenios y demás instrumentos jurídicos necesarios que en materia de comercialización de hidrocarburos; XLIII. Colaborar con la Unidad de Seguimiento y Supervisión de Asignaciones, Contratos y Permisos, con la información técnica relacionada con la comercialización de hidrocarburos; XLIV. Colaborar con la Unidad de Desarrollo de Modelos Contractuales y de Asignaciones, Proyectos Regulatorios y Argumentación Técnica para atender los avisos, notificaciones, informes, trámites y procedimientos en general que deriven de los contratos de comercialización de hidrocarburos; XLV. Validar los reportes requeridos en materia de los sistemas de medición y de supervisión; XLVI. Difundir y remitir a las Unidades Administrativas y a las autoridades competentes la información de volúmenes de hidrocarburos comercializados y tarifas de comercialización; XLVII. Aprobar los terceros independientes para la verificación de los sistemas de medición; XLVIII. Analizar y proponer al superior, el dictamen técnico para la aprobación de programa de aprovechamiento de gas natural como parte del plan de desarrollo para la extracción de hidrocarburos; XLIX. Validar la ejecución de los programas asociados a los sistemas de recolección aprobados a asignatarios y contratistas en los planes de desarrollo para la extracción de hidrocarburos; L. Validar la ejecución de los programas de recuperación secundaria o mejorada , aprobados a asignatarios o contratistas en los planes de desarrollo para la extracción; LI. Validar la estimación de las cifras de los recursos contingentes de la Nación; LII. Instruir las actividades necesarias para procurar la reposición de las reservas de hidrocarburos, como garantes de la seguridad energética de la Nación; LIII. Supervisar el cumplimiento de la regulación relativa al proceso de selección de los terceros independientes para la certificación de las reservas de hidrocarburos de la Nación; LIV. Vigilar que la información y documentación que se obtenga de los reportes de cuantificación de las reservas de hidrocarburos correspondientes a los asignatarios y contratistas; así como los reportes de los terceros; LV. Poner a disposición de las Unidades Administrativas competentes, la información y documentación que se obtenga de los reportes de cuantificación de las reservas de hidrocarburos correspondientes a los asignatarios y contratistas; así como los reportes de los terceros independientes relativos a la certificación de las reservas; LVI. Analizar y emitir opinión técnica respecto de la evolución histórica del volumen original de hidrocarburos, así como de las reservas asociadas a asignaciones y contratos, en concordancia con los planes de desarrollo para la extracción; LVII. Analizar y emitir opinión técnica respecto de l a s actividades físicas asociadas y perfiles de producción asociados a la cuantificación de reservas de hidrocarburos del país, derivado de información de los asignatarios y contratistas y en concordancia con los planes de desarrollo para la extracción; LVIII. Avalar el análisis de cuantificación de volúmenes de hidrocarburos asociado a información histórica de áreas de extracción susceptibles o no de ser recuperables; LIX. Aprobar la consolidación anual de la información nacional de las reservas de hidrocarburos; LX. Analizar y proponer al superior, la propuesta de política de restitución de reservas de hidrocarburos; LXI. Validar y proponer para aprobación superior, escenarios de plataforma anual de producción de petróleo y de gas, con base en las reservas probadas y los recursos disponibles, con el objeto de dar prioridad a la seguridad energética del país; LXII. Proporcionar los elementos técnicos a la Unidad Administrativa que corresponda sobre la probable existencia de alguna de las causales de revocación de la asignación y rescisión de contratos; LXIII. Proporcionar a la Unidad Técnica de Exploración la información referida en los artículos 60, 63 y 124 de la Ley del Sector Hidrocarburos, en materia de su competencia; LXIV. Proporcionar a la Unidad Técnica de Exploración la información a que se refiere el artículo 60 de la Ley del Sector Hidrocarburos, a fin de dar atención a las solicitudes de acceso a la información, publicación, entrega u obtención, en materia de su competencia; LXV. Coordinar la administración de los datos para los procedimientos excepcionales de licitación de contratos, en el ámbito de su competencia; LXVI. Supervisar los estudios económicos y de análisis relacionados con el sector de extracción de hidrocarburos; LXVII. Coordinar lo relativo a la evaluación económica y los programas de inversiones en materia de extracción de hidrocarburos; LXVIII. Proporcionar a la Unidad Técnica de Exploración, para su publicación los análisis estadísticos sobre la producción de hidrocarburos y reservas, incluidas la relación entre producción y reservas, los recursos contingentes y prospectivos, la información geológica, geofísica, petrofísica, petroquímica y demás que se obtenga de las actividades de extracción de hidrocarburos; LXIX. Coordinar el desarrollo de análisis estadísticos sobre las actividades en materia de su competencia; LXX. Proporcionar a la Unidad Técnica de Exploración, para su publicación las estadísticas de la medición y la comercialización de la producción de Hidrocarburos; LXXI. Proporcionar a la Unidad Técnica de Exploración para poner a disposición del público, la información en el ámbito de su competencia, que se refiere el artículo 124 de la Ley del Sector Hidrocarburos; LXXII. Evaluar el desempeño y la eficiencia de proyectos de extracción; LXXIII. Conocer de las posibles violaciones que se detecten al marco normativo, ordenar las medidas que correspondan y emitir recomendaciones al respecto en el ámbito de su competencia; LXXIV. Emitir opinión técnica que soliciten las unidades administrativas, en materia de su competencia; LXXV. Revisar y opinar técnicamente la documentación que se someta a consideración de los órganos colegiados en los que la Subsecretaría de Hidrocarburos tenga representación, y LXXVI. Revisar el proyecto de resolución de análisis de participación cruzada, en materia de hidrocarburos, que remita la Comisión Nacional de Energía, y solicitar la opinión de la autoridad en materia de competencia económica; en su caso remitir a su superior para su aprobación.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LA SUBSECRETARÍA DE HIDROCA R BUROS Y SUS UNIDADES ADMINISTRATIVAS","seccion_nombre":null,"orden":36},{"id":"7ec008be-a77b-450b-8b88-dac0e362a4b1","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 36.","contenido":"- Corresponde a la Dirección General de Medición y Balances de la Producción el ejercicio de las atribuciones siguientes: I. Aplicar los ordenamientos legales y demás normas jurídicas que de estos deriven, cuyas disposiciones regulen o estén vinculadas con las actividades de extracción de hidrocarburos; II. Dar seguimiento y verificar el cumplimiento de las obligaciones de los asignatarios y contratistas en materia de medición de hidrocarburos; III. Dar seguimiento y verificar la medición de la producción de hidrocarburos de los asignatarios y contratistas; IV. Verificar que los asignatarios y contratistas cuenten con sistemas de medición para cada uno de los volúmenes de hidrocarburos extraídos, ubicados en campo y punto de transferencia de custodia; V. Proponer los indicadores de referencia para evaluar la eficiencia de los sistemas de medición, equipos y personal de asignatarios y contratistas; VI. Verificar el funcionamiento de los sistemas de medición instalados por los asignatarios y contratistas; VII. Dar seguimiento a los reportes de producción por parte de los asignatarios y los contratistas que se consideran para el cálculo de las contraprestaciones, así como de los derechos e impuestos correspondientes; VIII. Iniciar, tramitar y resolver los actos relacionados con los procedimientos de ajuste que deriven de los reportes de producción y que se requieran para la comercialización, así como para el cálculo de las contraprestaciones, derechos e impuestos correspondientes; IX. Elaborar la información de producción de hidrocarburos; X. Proponer al superior jerárquico los elementos técnicos para la instalación de sistemas e instrumentos de medición; XI. Elaborar y proponer al superior, los términos y condiciones de los contratos de comercialización de hidrocarburos; XII. Proporcionar al superior, la información técnica para suscribir los contratos, convenios y demás instrumentos jurídicos necesarios que en materia de comercialización de hidrocarburos; XIII. Coordinar las actividades relacionadas con la comercialización de hidrocarburos; XIV. Proporcionar al superior, la información técnica para atender los avisos, notificaciones, informes, trámites y procedimientos en general que deriven de los contratos de comercialización de hidrocarburos; XV. Elaborar los reportes requeridos en materia de los sistemas de medición y de supervisión; XVI. Elaborar la información de volúmenes de hidrocarburos comercializados y tarifas de comercialización; XVII. Emitir opinión técnica al programa de aprovechamiento de gas natural; XVIII. Elaborar y someter para aprobación de la persona superior jerárquica la opinión sobre la verificación de los sistemas de medición por personas terceras independientes ; XIX. Elaborar la opinión técnica de la medición y comercialización de la producción de las áreas de asignación y las áreas contractuales en actividades de exploración y extracción; XX. Proponer para publicación al superior, las estadísticas de la medición y la comercialización de la producción de Hidrocarburos; XXI. Elaborar análisis estadísticos sobre las actividades en materia de su competencia; XXII. Conocer de las posibles violaciones que se detecten al marco normativo, ordenar las medidas que correspondan y emitir recomendaciones al respecto en el ámbito de su competencia, y XXIII. Revisar y opinar técnicamente la documentación que se someta a consideración de los órganos colegiados en los que la Subsecretaría de Hidrocarburos tenga representación.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LA SUBSECRETARÍA DE HIDROCA R BUROS Y SUS UNIDADES ADMINISTRATIVAS","seccion_nombre":null,"orden":37},{"id":"5de858bf-791a-49dc-81b3-ff0489bed6b1","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 37.","contenido":"- Corresponde a la Dirección General de Reservas de Hidrocarburos el ejercicio de las atribuciones siguientes: I. Aplicar los ordenamientos legales y demás normas jurídicas que de éstos deriven, cuyas disposiciones regulen o estén vinculadas con las actividades de extracción de hidrocarburos; II. Elaborar los anteproyectos de planeación energética relacionados con la extracción de hidrocarburos e incorporación de reservas de hidrocarburos; III. Elaborar y proponer al superior la propuesta para la selección y la determinación de las áreas en posesión del Estado para desarrollar actividades de extracción; IV. Elaborar y proponer al superior, opinión técnica para la determinación de las áreas en posesión del Estado para la extracción de hidrocarburos; V. Controlar y administrar las áreas en posesión del Estado, en materia de su competencia; VI. Analizar y opinar técnicamente en materia de su competencia, respecto de las solicitudes de contratos para la exploración y extracción del gas natural contenido en las vetas de carbón mineral y producida por esta; VII. Elaborar y proponer al superior el dictamen de unificación de campos o yacimientos; VIII. Elaborar y proponer para aprobación, el anteproyecto y dictamen técnico para establecer zonas de salvaguarda en las que se prohíban las actividades de extracción de hidrocarburos; así como para incorporar o desincorporar áreas específicas a estas; IX. Elaborar opinión técnica en la participación obligatoria de una empresa pública del Estado en los contratos para la exploración y extracción en aquellas áreas contractuales en las que exista la posibilidad de encontrar yacimientos transfronterizos en materia de su competencia; X. Coadyuvar en la implementación, ejecución y seguimiento de los acuerdos internacionales en materia de exploración y extracción de hidrocarburos en yacimientos transfronterizos de los que el Estado mexicano sea parte; XI. Realizar la cuantificación de reservas de hidrocarburos del país, derivado de información de los asignatarios y contratistas; XII. Asegurar el cumplimiento de la regulación relativa al proceso de selección de los terceros independientes para la certificación de las reservas de hidrocarburos de la Nación; XIII. Dar seguimiento y validar el procedimiento anual de cuantificación de las reservas de hidrocarburos para llevar a cabo su consolidación, así como su certificación; XIV. Elaborar y proponer al superior la propuesta de política de restitución de reservas de hidrocarburos; XV. Elaborar y proponer al superior, la opinión técnica respecto de la evolución histórica del volumen original de hidrocarburos, así como de las reservas asociadas a asignaciones y contratos, en concordancia con los planes de desarrollo para la extracción; XVI. Elaborar y proponer al superior, la opinión técnica respecto de las actividades físicas y de los perfiles de producción asociados a la cuantificación de reservas de hidrocarburos del país, derivado de información de los asignatarios y contratistas y en concordancia con los planes de desarrollo para la extracción; XVII. Realizar análisis de cuantificación de volúmenes de hidrocarburos asociado a información histórica de áreas de extracción susceptibles o no de ser recuperables; XVIII. Emitir opinión técnica respecto de las nominaciones de áreas en posesión del Estado que realicen la empresa pública del Estado o cualquier persona moral sobre las cuales exista interés para llevar a cabo la extracción de hidrocarburos; XIX. Realizar la estimación de las cifras de los recursos contingentes de la Nación; XX. Proponer al superior, la resolución respecto de la incorporación de reservas que no cuenten con un informe de evaluación y la declaración de descubrimiento comercial; XXI. Proponer las actividades necesarias para procurar la reposición de las reservas de hidrocarburos, como garantes de la seguridad energética de la Nación; XXII. Elaborar los reportes de cuantificación de las reservas de hidrocarburos correspondientes a los asignatarios y contratistas; así como los reportes de los terceros independientes relativos a la certificación de las reservas; XXIII. Elaborar los términos técnicos y operativos de las asignaciones, en materia de su competencia; XXIV. Elaborar y proponer al superior, los escenarios de plataforma anual de producción de petróleo y de gas, con base en las reservas probadas y los recursos disponibles, con la seguridad energética del país como prioridad; XXV. Realizar y proponer al superior los análisis estadísticos sobre la producción de hidrocarburos y reservas, incluidas la relación entre producción y reservas, los recursos contingentes y prospectivos, la información geológica, geofísica, petrofísica, petroquímica y demás que se obtenga de las actividades de extracción de hidrocarburos; XXVI. Elaborar opinión técnica que soliciten las Unidades Administrativas, en materia de su competencia; XXVII. Conocer de las posibles violaciones que se detecten al marco normativo, ordenar las medidas que correspondan y emitir recomendaciones al respecto en el ámbito de su competencia, y XXVIII. Revisar y opinar técnicamente la documentación que se someta a consideración de los órganos colegiados en los que la Subsecretaría de Hidrocarburos tenga representación.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LA SUBSECRETARÍA DE HIDROCA R BUROS Y SUS UNIDADES ADMINISTRATIVAS","seccion_nombre":null,"orden":38},{"id":"f3049d38-4ac6-4498-a2c5-86b7ce8848a5","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 38.","contenido":"- Corresponde a la Dirección General de Planes y Programas de Extracción, el ejercicio de las atribuciones siguientes: I. Aplicar los ordenamientos legales y demás normas jurídicas que de estos deriven, cuyas disposiciones regulen o estén vinculadas con las actividades de extracción de hidrocarburos; II. Proponer al superior, el dictamen técnico respecto del otorgamiento, modificación, sustitución, renuncia o revocación de asignaciones para la realización de actividades de extracción; III. Elaborar el dictamen técnico sobre la procedencia de la sustitución de asignaciones de desarrollo propio a asignaciones de desarrollo mixto; IV. Elaborar el dictamen técnico sobre la procedencia de la migración de asignaciones de desarrollo propio de exploración a contratos para la exploración y extracción de hidrocarburos, en materia de su competencia; V. Elaborar la opinión técnica para la acreditación de compromisos de trabajo, programas mínimos de trabajo y actividades de extracción que presenten los asignatarios y contratistas, según corresponda; VI. Informar al superior jerárquico en el ámbito de sus competencias, la probable existencia de alguna de las causales de revocación de la asignación y rescisión de contratos; VII. Revisar y proponer al superior, la opinión técnica para la aprobación de los programas de transición, de los planes de desarrollo para la extracción, los programas asociados y sus modificaciones, suspensión de actividades de extracción y prórrogas a la vigencia de las asignaciones y los contratos; VIII. Elaborar la opinión técnica y económica de los programas anuales de inversión y operación de los contratos para la exploración y extracción, en el ámbito de su competencia; IX. Desarrollar los estudios económicos y de análisis relacionados con el sector de extracción de hidrocarburos, en coordinación con las Unidades Administrativas competentes; X. Elaborar y proponer a las Unidades Administrativas competentes, las opiniones respecto de la evaluación económica y los programas del costo total asociado a los planes y programas, para la integración de los dictámenes técnicos respectivos o la resolución, según corresponda; XI. Elaborar y proponer las opiniones respecto a los presupuestos de los contratos con recuperación de costos, así como la revisión de los presupuestos indicativos, previo a su registro ante el Fondo Mexicano del Petróleo; XII. Desarrollar y aplicar metodologías y realizar la evaluación económica de las áreas contractuales sujetas a procesos excepcionales de licitación; XIII. Elaborar para aprobación superior, la opinión respecto de los modelos de contratación para cada área contractual; XIV. Desarrollar y aplicar metodologías para las proyecciones de producción, inversiones y costos del sector de extracción de hidrocarburos, en coordinación con las Unidades Administrativas competentes; XV. Elaborar y proponer al superior, el dictamen con las condiciones sobre la coexistencia de actividades extractivas; XVI. Emitir opinión técnica para determinar co mo inviable técnica o económicamente para la extracción a un pozo destinado para las actividades de exploración y extracción de hidrocarburos; XVII. Conocer de las posibles violaciones que se detecten al marco normativo, ordenar las medidas que correspondan y emitir recomendaciones al respecto en el ámbito de su competencia, y XVIII. Revisar y opinar técnicamente la documentación que se someta a consideración de los órganos colegiados en los que la Subsecretaría de Hidrocarburos tenga representación.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LA SUBSECRETARÍA DE HIDROCA R BUROS Y SUS UNIDADES ADMINISTRATIVAS","seccion_nombre":null,"orden":39},{"id":"82d242ab-2a85-4b60-a8af-a9bd168e793c","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 39.","contenido":"- Corresponde a la Dirección General de Administración de Campos de Extracción, el ejercicio de las atribuciones siguientes: I. Aplicar los ordenamientos legales y demás normas jurídicas que de éstos deriven, cuyas disposiciones regulen o estén vinculadas con las actividades de extracción de hidrocarburos; II. Elaborar los anteproyectos de planeación energética relacionados con investigación y desarrollo tecnológico nacionales relacionados con la extracción de hidrocarburos; III. Analizar las referencias tecnológicas utilizadas conforme a las mejores prácticas de la industria en materia de su competencia; IV. Participar en investigaciones y estudios para la identificación y propuesta de utilización de la tecnología más adecuada para la extracción de hidrocarburos en función de resultados productivos y económicos; V. Administrar el registro de las autorizaciones de perforación de pozos tipo que utilicen como modelos de diseño, y de pozos de desarrollo para la extracción en aguas profundas y ultra profundas e inscribir las autorizaciones de los pozos correspondientes; VI. Recibir y evaluar, en términos de su competencia, los informes de los asignatarios, contratistas y autorizados respecto a cualquier siniestro, hecho o contingencia que, como resultado de sus operaciones ponga en peligro la vida, la salud y seguridad públicas, el medio ambiente, la seguridad de las instalaciones o la producción de hidrocarburos, así como los informes de las causas que los originaron, las medidas tomadas para su control y, en su caso, remediación; VII. Elaborar para aprobación superior, el proyecto para la emisión de las autorizaciones para la perforación de pozos tipo que utilicen como modelos de diseño y de pozos de desarrollo para la extracción en aguas profundas y ultra profundas; VIII. Elaborar para aprobación superior, el proyecto para la emisión de las autorizaciones respecto de la perforación de pozos, así como para el pronunciamiento de las solicitudes de prórroga o renovación de las autorizaciones de perforación de pozos; IX. Administrar y registrar los avisos para perforación, terminación y abandono de pozos de desarrollo presentados por los asignatarios y contratistas; X. Administrar los cuartos de datos para los procedimientos excepcionales de licitación de contratos, en el ámbito de su competencia; XI. Evaluar técnicamente la ejecución de los programas asociados a los sistemas de recolección aprobados a asignatarios y contratistas en los planes de desarrollo para la extracción y sus programas; XII. Evaluar la ejecución de los programas de recuperación secundaria o mejorada , aprobados a asignatarios y contratistas en los planes de desarrollo para la extracción y sus programas; XIII. Definir los indicadores de referencia para evaluar la eficiencia de proyectos de extracción; XIV. Proponer los índices o métricas para la evaluación de la eficiencia operativa de los métodos utilizados en ésta y elaborar los análisis sobre la definición y seguimiento de estrategias y proyectos relacionados; XV. Elaborar para aprobación superior, los proyectos de infraestructura estratégicos necesarios para cumplir con la política energética en actividades de extracción hidrocarburos; XVI. Elaborar y proponer al superior la información referida en los artículos 60, 63 y 124 de la Ley del Sector Hidrocarburos, en materia de su competencia; XVII. Elaborar y proponer al superior la información a que se refiere el artículo 60 de la Ley del Sector Hidrocarburos, en materia de su competencia; XVIII. Elaborar, publicar y actualizar las fichas técnicas de las asignaciones, contratos y autorizaciones en coordinación con las unidades administrativas competentes; XIX. Elaborar opinión técnica que soliciten las unidades administrativas, en materia de su competencia; XX. Conocer de las posibles violaciones que se detecten al marco normativo, ordenar las medidas que correspondan y emitir recomendaciones al respecto en el ámbito de su competencia; XXI. Coordinar la integración de expedientes de los procedimientos administrativos por el presunto incumplimiento de obligaciones o por violaciones a la Ley del Sector Hidrocarburos y demás disposiciones jurídicas aplicables; XXII. Someter a consideración la persona titular de la Subsecretaría de Hidrocarburos o, en su caso, del Comité de Asignaciones, Contratos y Permisos, a través de la Unidad de Asuntos Jurídicos, el inicio y resolución del procedimiento administrativo de sanción o por posibles incumplimientos, en términos de las atribuciones que se otorgan a la Secretaría en la Ley del Sector Hidrocarburos y demás disposiciones jurídicas aplicables, y XXIII. Revisar y opinar técnicamente la documentación que se someta a consideración de los órganos colegiados en los que la Subsecretaría de Hidrocarburos tenga representación.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LA SUBSECRETARÍA DE HIDROCA R BUROS Y SUS UNIDADES ADMINISTRATIVAS","seccion_nombre":null,"orden":40},{"id":"6450fbbf-f655-451f-a52d-b439a96101b8","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 40.","contenido":"- Corresponde a la Unidad de Políticas de Transformación Industrial el ejercicio de las atribuciones siguientes: I. Aplicar los ordenamientos legales y demás normas jurídicas que de estos deriven, cuyas disposiciones regulen o estén vinculadas con el tratamiento, refinación, importación, exportación, comercialización, transporte y almacenamiento de petróleo, así como la importación y exportación de gas natural, petrolíferos y petroquímicos; II. Revisar y remitir a la Unidad de Desarrollo de Modelos Contractuales y de Asignaciones, Proyectos Regulatorios y Argumentación Técnica, de la Subsecretaría de Hidrocarburos, los proyectos de disposiciones, lineamientos, normas oficiales mexicanas o regulación técnica en materia de petróleo, gas natural, petrolíferos y petroquímicos; III. Supervisar y coordinar el trámite y análisis de las solicitudes de permisos de tratamiento, refinación, comercialización, transporte y almacenamiento de petróleo, importación y exportación de petróleo, gas natural, petrolíferos y petroquímicos; IV. Emitir, con la aprobación de la persona titular de la Subsecretaría de Hidrocarburos, y en su caso del comité, el otorgamiento, desechamiento, modificación y en su caso, prórroga, de los permisos de tratamiento, refinación, comercialización, transporte y almacenamiento de petróleo, importación y exportación de petróleo, gas natural, petrolíferos y petroquímicos; V. Someter a consideración de la persona titular de la Subsecretaría de Hidrocarburos la propuesta de cesión de los permisos que hayan otorgado las Direcciones Generales de Petrolíferos y Permisos, en sus ámbitos correspondientes; VI. Remitir a la persona titular de la Unidad de Desarrollo de Modelos Contractuales y de Asignaciones, Proyectos Regulatorios y Argumentación Técnica, el informe de los incumplimientos a las obligaciones de los permisionarios, así como la detección de posibles ilícitos en la realización de actividades reguladas; VII. Coordinar el seguimiento que las Direcciones Generales a su cargo le dan a los planes y programas en materia de petróleo, gas natural, petroquímicos y petrolíferos, en términos de la Ley de Planeación y Transición Energética; VIII. Coordinar y proponer para aprobación superior los proyectos de políticas públicas en materia de tratamiento, comercialización, transporte, distribución, expendio, almacenamiento y garantía de suministro de gas natural, petrolíferos y petroquímicos; IX. Revisar y proponer para aprobación superior los proyectos de plan quinquenal de expansión y optimización de la infraestructura de transporte por ducto y almacenamiento de gas natural, petrolíferos y petroquímicos, así como su revisión anual, considerando las opiniones que emitan la Comisión Nacional de Energía y los gestores de dichos sistemas; X. Seleccionar y proponer para aprobación superior el mecanismo de administración para la gestión de los niveles mínimos de almacenamiento de gas natural, petrolíferos y petroquímicos; XI. Evaluar y poner a consideración superior las bases de licitación que realice el Centro Nacional de Control del Gas Natural, así como los mecanismos de asignación de capacidad por parte de las personas permisionarias para sistemas integrados o nuevos proyectos de transporte y almacenamiento de gas natural; XII. Coordinar, supervisar y proponer al superior jerárquico la creación de sistemas integrados en materia de gas natural, petrolíferos y petroquímicos; XIII. Revisar y proponer para consideración superior la conveniencia de instruir a las empresas públicas del Estado, y sus empresas filiales que realicen las acciones necesarias para que sus actividades y operaciones sean garantes de la seguridad y la autosuficiencia energética de la Nación y que no obstaculicen el desarrollo eficiente de los mercados, así como la política pública en materia energética; XIV. Coordinar la participación y la entrega de la información de las áreas a su cargo, para contribuir en la elaboración de los instrumentos de planeación e información energética a que hace referencia la Ley de Planeación y Transición Energética; XV. Remitir a la persona titular de la Unidad de Asuntos Jurídicos, el informe de los incumplimientos a las obligaciones de los permisionarios, así como la detección de posibles ilícitos en la realización de actividades reguladas; XVI. Coordinar la integración de expedientes de los procedimientos administrativos por el presunto incumplimiento de obligaciones o por violaciones a la Ley del Sector Hidrocarburos y demás disposiciones jurídicas aplicables; XVII. Someter a consideración la persona titular de la Subsecretaría de Hidrocarburos o, en su caso, del Comité de Asignaciones, Contratos y Permisos, a través de la Unidad de Asuntos Jurídicos, el inicio y resolución del procedimiento administrativo de sanción o por posibles incumplimientos, en términos de las atribuciones que se otorgan a la Secretaría en la Ley del Sector Hidrocarburos y demás ordenamientos jurídicos aplicables; XVIII. Proponer al superior el proyecto de la política nacional en materia de petrolíferos, petroquímicos, refinación y gas natural; XIX. Proponer al superior el proyecto de los criterios de planeación vinculante para el otorgamiento de los permisos del sector hidrocarburos en términos de lo establecido en la Ley de Planeación y Transición Energética y el Plan de Desarrollo del Sector Hidrocarburos; XX. Revisar y opinar técnicamente la documentación que se someta a consideración de los órganos colegiados en los que la Subsecretaría de Hidrocarburos tenga representación, y XXI. Revisar el proyecto de resolución de análisis de participación cruzada, en materia de petrolíferos o petroquímicos, que remita la Comisión Nacional de Energía, y solicitar la opinión de la autoridad en materia de competencia económica , en su caso remitir a su superior para su aprobación.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LA SUBSECRETARÍA DE HIDROCA R BUROS Y SUS UNIDADES ADMINISTRATIVAS","seccion_nombre":null,"orden":41},{"id":"f4da6fae-dffd-427f-9435-5ab47341b833","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 41.","contenido":"- Corresponde a la Dirección General de Gas Natural y Petroquímicos el ejercicio de las atribuciones siguientes: I. Aplicar los ordenamientos legales y demás normas jurídicas que de éstos deriven, cuyas disposiciones regulen o estén vinculadas con las actividades en materia de gas natural y petroquímicos; II. Elaborar y proponer los anteproyectos de disposiciones, lineamientos, normas oficiales mexicanas o regulación técnica en materia de gas natural y petroquímicos; III. Elaborar y presentar a consideración superior los anteproyectos de políticas públicas en materia de comercialización, transporte, distribución, expendio al público, almacenamiento y garantía de suministro de gas natural y petroquímicos, así como el mecanismo de administración para la gestión de los niveles mínimos de almacenamiento de gas natural; IV. Analizar y presentar a consideración superior la conveniencia de instruir a las empresas públicas del Estado, y sus empresas filiales que realicen las acciones necesarias para que sus actividades y operaciones sean garantes de la seguridad y la autosuficiencia energética de la Nación y que no obstaculicen el desarrollo eficiente de los mercados, así como la política pública en materia energética; V. Elaborar y presentar a consideración superior el proyecto de plan quinquenal de expansión y optimización de la infraestructura de transporte por ducto y almacenamiento de gas natural y petroquímicos, así como realizar su revisión anual, considerando las opiniones que emitan la Comisión Nacional de Energía y los gestores de dichos sistemas; VI. Analizar, formular y presentar a consideración superior los proyectos de cobertura social y aquellos que se consideren estratégicos, para ser incluidos en el plan quinquenal de expansión y optimización de la infraestructura de transporte por ducto y almacenamiento de gas natural que proponga el Centro Nacional de Control del Gas Natural; VII. Analizar, formular y presentar a consideración superior la conveniencia de instruir a las empresas públicas del Estado y al Centro Nacional de Control del Gas Natural, la realización de proyectos para la generación de beneficios sociales y promoción de desarrollo económico, en materia de gas natural y petroquímicos; VIII. Elaborar y someter para aprobación superior, en coordinación con las partes involucradas, los planes de emergencia para la continuidad de las actividades en los sistemas integrados de transporte por ducto y almacenamiento de gas natural, considerando las opiniones que emitan la Comisión Nacional de Energía y los gestores de dichos sistemas; IX. Analizar, formular y proponer al superior jerárquico la creación de sistemas integrados en materia de gas natural; X. Recopilar y organizar la información que, en materia de transformación industrial de gas natural y petroquímicos reciba en ejercicio de sus atribuciones, para contribuir en la elaboración de los instrumentos de planeación e información energética a que hace referencia la Ley de Planeación y Transición Energética; XI. Evaluar y someter a aprobación superior las bases de licitación que realice el Centro Nacional de Control del Gas Natural, respecto de proyectos estratégicos para garantizar el desarrollo eficiente del Sistema de Transporte y Almacenamiento Nacional Integrado de Gas Natural; XII. Evaluar y someter a aprobación superior los mecanismos de asignación de capacidad que realicen las personas permisionarias en los sistemas, o infraestructura de transporte y almacenamiento; XIII. Dar seguimiento a los planes y programas en materia de gas natural y petroquímicos, en términos de la Ley de Planeación y Transición Energética; XIV. Elaborar el proyecto de la política nacional en materia de petroquímicos y gas natural; XV. Elaborar el proyecto de los criterios de planeación vinculante para el otorgamiento de los permisos del sector hidrocarburos en términos de lo establecido en la Ley de Planeación y Transición Energética y el Plan de Desarrollo del Sector Hidrocarburos en el ámbito de su competencia, y XVI. Revisar y opinar técnicamente la documentación que se someta a consideración de los órganos colegiados en los que la Subsecretaría de Hidrocarburos tenga representación.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LA SUBSECRETARÍA DE HIDROCA R BUROS Y SUS UNIDADES ADMINISTRATIVAS","seccion_nombre":null,"orden":42},{"id":"81a004f6-f94b-49cc-be0a-02b0a8a8ccb3","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 42.","contenido":"- Corresponde a la Dirección General de Petrolíferos el ejercicio de las atribuciones siguientes: I. Aplicar los ordenamientos legales y demás normas jurídicas que de éstos deriven, cuyas disposiciones regulen o estén vinculadas con las actividades de tratamiento, refinación, transporte, almacenamiento y comercialización de petróleo, así como las demás relativas a la industria de los petrolíferos; II. Elaborar y proponer los anteproyectos de disposiciones, lineamientos, normas oficiales mexicanas o regulación técnica en materia de Petrolíferos; III. Tramitar las solicitudes de permisos de tratamiento, refinación, transporte, almacenamiento y comercialización de petróleo; IV. Someter a consideración de la persona titular de la Subsecretaría de Hidrocarburos los proyectos de otorgamiento, prórroga, modificación, actualización, reasignación, revocación, caducidad, terminación de permisos de tratamiento, refinación, transporte, almacenamiento y comercialización de petróleo, en términos de las atribuciones otorgadas a la Secretaría en la Ley del Sector Hidrocarburos y demás ordenamientos jurídicos aplicables; V. Formular requerimientos de información necesaria para el ejercicio de sus facultades a los sujetos que realicen actividades de tratamiento, refinación, transporte, almacenamiento y comercialización de petróleo; VI. Elaborar y proponer a consideración superior la propuesta de otorgamiento, desechamiento, modificación y en su caso, prórroga de los permisos de tratamiento, refinación, comercialización, transporte y almacenamiento de petróleo; VII. Elaborar y proponer al superior jerárquico la propuesta de cesión de los permisos que hubiera otorgado; VIII. Coordinar la integración de expedientes de los procedimientos administrativos a las personas permisionarias por el presunto incumplimiento de obligaciones o por violaciones a la Ley del Sector Hidrocarburos y demás disposiciones jurídicas aplicables; IX. Someter a consideración la persona titular de la Subsecretaría de Hidrocarburos o, en su caso, del Comité de Asignaciones, Contratos y Permisos, a través de la Unidad de Asuntos Jurídicos, el inicio y resolución del procedimiento administrativo de sanción o por posibles incumplimientos de las personas permisionarias, en términos de las atribuciones que se otorgan a la Secretaría en la Ley del Sector Hidrocarburos y demás disposiciones jurídicas aplicables; X. Proponer a la Unidad de Seguimiento y Supervisión de Asignaciones, Contratos y Permisos, las acciones y medios para la supervisión de los permisionarios; XI. Elaborar y proponer para aprobación superior los anteproyectos de políticas públicas en materia de tratamiento y refinación de petróleo, comercialización, transporte, distribución, expendio, almacenamiento y garantía de suministro de petróleo y petrolíferos, así como el mecanismo de administración para la gestión de los niveles mínimos de almacenamiento de petrolíferos; XII. Analizar y presentar a consideración superior la conveniencia de instruir a las empresas públicas del Estado, y sus empresas filiales que realicen las acciones necesarias para que sus actividades y operaciones sean garantes de la seguridad y la autosuficiencia energética de la Nación y que no obstaculicen el desarrollo eficiente de los mercados, así como la política pública en materia energética; XIII. Elaborar y presentar a consideración superior el proyecto de plan quinquenal de expansión y optimización de la infraestructura de transporte por ducto y almacenamiento de petróleo y petrolíferos, así como realizar su revisión anual; XIV. Analizar y presentar a consideración superior la conveniencia de instruir a las empresas públicas del Estado, la realización de proyectos para la generación de beneficios sociales y promoción de desarrollo económico, en materia de petróleo y petrolíferos; así como coordinar la ejecución de los proyectos que se autoricen; XV. Analizar y presentar a consideración superior la instrumentación de programas de apoyos focalizados, que coadyuven al suministro adecuado y oportuno, a precios asequibles, de petrolíferos; así como coordinar la ejecución de los proyectos que se autoricen; XVI. Recopilar y organizar la información que, en materia de transformación industrial de petróleo y petrolíferos reciba en ejercicio de sus atribuciones, para contribuir en la elaboración de los instrumentos de planeación e información energética a que hace referencia la Ley de Planeación y Transición Energética; XVII. Elaborar y someter para aprobación superior los planes de emergencia para la continuidad de las actividades en los sistemas integrados de transporte por ducto y almacenamiento de petróleo y petrolíferos, considerando las opiniones que emitan la Comisión Nacional de Energía y los gestores de dichos sistemas; XVIII. Analizar, formular y proponer al superior jerárquico la creación de sistemas integrados en materia de petróleo y petrolíferos; Tramitar y resolver las solicitudes de pronunciamiento favorable de adquisición de combustibles aéreos establecida en la Ley del Sector Hidrocarburos; XIX. Revisar y validar el certificado de calidad de origen, informe de resultados o el documento de naturaleza jurídica y técnica análoga que presenten los laboratorios de prueba y/o ensayo del país de procedencia del petrolífero de que se trate para dar cumplimiento a la normatividad aplicable, en el ámbito de su competencia; XX. Dar seguimiento a los planes y programas en materia de petróleo y petrolíferos, en términos de la Ley de Planeación y Transición Energética; XXI. Elaborar el proyecto de la Política Nacional en materia de petrolíferos y refinación; XXII. Elaborar el proyecto de los criterios de planeación vinculante para el otorgamiento de los permisos del Sector Hidrocarburos en términos de lo establecido en la Ley de Planeación y Transición Energética y el Plan de Desarrollo del Sector Hidrocarburos en el ámbito de su competencia, y XXIII. Revisar y opinar técnicamente la documentación que se someta a consideración de los órganos colegiados en los que la Subsecretaría de Hidrocarburos tenga representación.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LA SUBSECRETARÍA DE HIDROCA R BUROS Y SUS UNIDADES ADMINISTRATIVAS","seccion_nombre":null,"orden":43},{"id":"63aa5b8b-b533-454f-bade-7243efd979ac","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 43.","contenido":"- Corresponde a la Dirección General de Permisos de Importación y Exportación de Hidrocarburos, Petroquímicos y Petrolíferos el ejercicio de las atribuciones siguientes: I. Aplicar los ordenamientos legales y demás normas jurídicas que de estos deriven, cuyas disposiciones regulen o estén vinculadas con los permisos de importación y exportación de petróleo, gas natural, petrolíferos y petroquímicos; II. Elaborar y proponer los anteproyectos de disposiciones, lineamientos, normas oficiales mexicanas o regulación técnica en materia de permisos de importación y exportación de petróleo, gas natural, petrolíferos y petroquímicos; III. Atender y analizar las solicitudes de permisos de importación y exportación de petróleo, gas natural, petrolíferos y petroquímicos; IV. Someter a consideración de la persona titular de la Subsecretaría de Hidrocarburos los proyectos de otorgamiento, desechamiento, prórroga, modificación, cesión, revocación, caducidad, terminación de permisos de importación y exportación de petróleo, gas natural, petrolíferos y petroquímicos, en términos de las atribuciones otorgadas a la Secretaría en la Ley del Sector Hidrocarburos y demás ordenamientos jurídicos aplicables; V. Coordinar la integración de expedientes de los procedimientos administrativos a las personas permisionarias por el presunto incumplimiento de obligaciones o por violaciones a la Ley del Sector Hidrocarburos y demás disposiciones jurídicas aplicables; VI. Someter a consideración la persona titular de la Subsecretaría de Hidrocarburos o, en su caso, del Comité de Asignaciones, Contratos y Permisos, a través de la Unidad de Asuntos Jurídicos, el inicio y resolución del procedimiento administrativo de sanción o por posibles incumplimientos de las personas permisionarias, en términos de las atribuciones que se otorgan a la Secretaría en la Ley del Sector Hidrocarburos y demás disposiciones jurídicas aplicables; VII. Formular requerimientos de información necesaria para el ejercicio de sus facultades a los sujetos que realicen actividades de importación y exportación de petróleo, gas natural, petrolíferos y petroquímicos; VIII. Proponer a la Unidad de Supervisión de Asignaciones, Contratos y Permisos, las acciones y medios para la supervisión de los permisionarios; IX. Supervisar la actualización de la información que, en materia de comercio exterior de petróleo, gas natural, petrolíferos y petroquímicos, reciba en ejercicio de sus atribuciones, y X. Revisar y opinar técnicamente la documentación que se someta a consideración de los órganos colegiados en los que la Subsecretaría de Hidrocarburos tenga representación.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LA SUBSECRETARÍA DE HIDROCA R BUROS Y SUS UNIDADES ADMINISTRATIVAS","seccion_nombre":null,"orden":44},{"id":"9bd05257-b6cc-45b0-a426-a5db44852c22","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 44.","contenido":"- Corresponde a la Unidad de Seguimiento y Supervisión de Asignaciones, Contratos y Permisos el ejercicio de las atribuciones siguientes: I. Habilitar a las personas servidoras públicas de la Secretaría y terceros para que realicen las visitas de verificación e inspección respecto del cumplimiento de las obligaciones de asignatarios, contratistas, permisionarios y autorizados e informar al superior jerárquico del personal habilitado; II. Aprobar a los organismos para la evaluación de la conformidad de las normas oficiales mexicanas competencia de la Subsecretaría de Hidrocarburos; III. Solicitar a la persona titular de la Unidad de Desarrollo de Modelos Contractuales y de Asignaciones, Proyectos Regulatorios y Argumentación Técnica que se realicen las gestiones necesarias para la inscripción y actualización de la información de las personas servidoras públicas autorizadas para realizar inspecciones y verificaciones en el padrón respectivo, de conformidad con la Ley General de Mejora Regulatoria; IV. Expedir y autorizar las órdenes de verificación o inspección de acuerdo con la normatividad aplicable; V. Coordinar el seguimiento y verificación del cumplimiento de las obligaciones de los operadores petroleros, derivadas de los contratos, asignaciones y normatividad aplicable, en el ámbito de su competencia; VI. Coordinar el seguimiento de la ejecución de las actividades consideradas en los planes de exploración y planes de desarrollo para la extracción y programas asociados de los asignatarios y contratistas en el ámbito de su competencia, en apego a la normatividad aplicable; VII. Coordinar el seguimiento del cumplimiento de las obligaciones de los autorizados, asignatarios y contratistas en materia de perforación de pozos y demás actividades de exploración y extracción de hidrocarburos, y verificar el cumplimiento de estas, con base en los elementos técnicos que proporcionen las unidades técnicas de exploración y extracción de hidrocarburos, según corresponda; VIII. Aprobar los programas de capacitación y transferencia de tecnología de los asignatarios y contratistas; IX. Asegurar la documentación en la que consten los acuerdos alcanzados mediante negociación o las medidas decretadas por el Ejecutivo Federal o los tribunales competentes en materia de uso y ocupación superficial en relación con las asignaciones y contratos; X. Notificar a la Unidad de Desarrollo de Modelos Contractuales y Asignaciones, Proyectos Regulatorios y Argumentación Técnica posibles incumplimientos en las obligaciones de los contratos para la exploración y extracción de hidrocarburos y en los títulos de asignación; XI. Evaluar y presentar para aprobación superior, los porcentajes mínimos de contenido nacional que deben incluirse en cada asignación y contrato; XII. Validar la propuesta del Programa Anual de Visitas de Verificación e Inspección, así como las visitas no programadas en términos de la normativa aplicable y proponer su aprobación al superior; XIII. Coordinar las funciones de supervisión del abandono de las áreas de asignación y áreas contractuales, en el ámbito de competencia de la Secretaría, incluyendo la constitución de los fideicomisos de abandono; XIV. Atender las solicitudes de acreditación de compromisos de trabajo, programas mínimos de trabajo y actividades que presenten los asignatarios y contratistas, según corresponda, previa opinión técnica de las unidades técnicas de exploración y extracción; XV. En caso de que durante el ejercicio de sus atribuciones se detecte que un concesionario minero lleve a cabo actividades de exploración o extracción de hidrocarburos, dar aviso al superior jerárquico y a la Secretaría de Economía; XVI. Supervisar la emisión del dictamen del modelo de contratación para cada área contractual y remitirlo a la Unidad de Desarrollo de Modelos Contractuales y Asignaciones, Proyectos Regulatorios y Argumentación Técnica; XVII. Presentar al superior los resultados y, en su caso, los posibles incumplimientos detectados en las prácticas de vistas de verificación e inspección; XVIII. Supervisar el cumplimiento de las obligaciones contenidas en los permisos de importación y exportación de petróleo, gas natural, petrolíferos y petroquímicos y en la normatividad aplicable; XIX. Supervisar el cumplimiento de las obligaciones de entrega de información y reportes de las personas permisionarias de importación y exportación de hidrocarburos, petrolíferos y petroquímicos; XX. Coordinar el seguimiento del cumplimiento de las obligaciones de las personas permisionarias de importación y exportación de hidrocarburos, petrolíferos y petroquímicos, tratamiento, refinación, transporte, almacenamiento, comercialización de petróleo, y verificarlas con base en los elementos técnicos por la Unidad de Políticas y Transformación Industrial; XXI. Emitir opinión sobre la posible existencia de alguna causal de caso fortuito o fuerza mayor de asignaciones y contratos y remitir a la Unidad de Desarrollo de Modelos Contractuales y Asignaciones, Proyectos Regulatorios y Argumentación Técnica la determinación que corresponda; XXII. Emitir orden de visitas de verificación a las instalaciones de los permisionarios y de todas aquellas personas involucradas en la logística de la importación y exportación de petróleo, petrolíferos, petroquímicos y gas natural; XXIII. Emitir opinión de las estrategias para el fomento industrial de cadenas productivas locales y para el fomento de la inversión directa en la industria de hidrocarburos, con especial atención a las pequeñas y medianas empresas, definidas por la Secretaría de Economía, aplicables a las asignaciones y contratos de exploración y extracción de hidrocarburos; XXIV. Supervisar, la elaboración e implementación de programas de capacitación y profesionalización del personal verificador, a efecto de fomentar su actualización y mejora continua, aplicables a las asignaciones y contratos de exploración y extracción de hidrocarburos; XXV. Resguardar las garantías que se constituyan en relación con los contratos de exploración y extracción de hidrocarburos; XXVI. Supervisar de manera continua las actividades que se llevan a cabo en las áreas de asignaciones o contractuales con el soporte de herramientas tecnológicas o de convenios con autoridades encargadas de actividades de verificación e inspección; XXVII. Solicitar a los operadores petroleros, las dependencias y entidades de la Administración Pública Federal, así como otros organismos o instituciones, públicos o privados, información para dar seguimiento al avance en la ejecución de las actividades contenidas en los programas de capacitación y transferencia de tecnología; XXVIII. Conocer de las posibles violaciones que se detecten al marco normativo, adoptar las medidas correspondientes conforme a su ámbito de competencia y hacerlo del conocimiento de las autoridades competentes en los casos que así proceda; XXIX. Coordinar la determinación de las penalizaciones relativas al pago de contraprestaciones a cargo de los contratistas; XXX. Emitir el proyecto de propuesta de desincorporación de activos solicitada por el asignatario o contratistas; XXXI. Resguardar las pólizas de seguros presentadas por el asignatario o contratistas, para el cumplimiento de sus obligaciones; XXXII. Coordinar la integración de expedientes de los procedimientos administrativos por el presunto incumplimiento de obligaciones o por violaciones a la Ley del Sector Hidrocarburos y demás disposiciones jurídicas aplicables; XXXIII. Someter a consideración la persona titular de la Subsecretaría de Hidrocarburos o, en su caso, del Comité de Asignaciones, Contratos y Permisos, a través de la Unidad de Asuntos Jurídicos, el inicio y resolución del procedimiento administrativo de sanción o por posibles incumplimientos, en términos de las atribuciones que se otorgan a la Secretaría en la Ley del Sector Hidrocarburos y demás disposiciones jurídicas aplicables; XXXIV. Determinar y proponer al superior jerárquico las medidas precautorias o cautelares en el ejercicio de sus facultades de inspección, supervisión y vigilancia de conformidad con lo establecido en la Ley del Sector Hidrocarburos y demás ordenamientos jurídicos aplicables, y XXXV. Revisar y opinar técnicamente la documentación que se someta a consideración de los órganos colegiados en los que la Subsecretaría de Hidrocarburos tenga representación.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LA SUBSECRETARÍA DE HIDROCA R BUROS Y SUS UNIDADES ADMINISTRATIVAS","seccion_nombre":null,"orden":45},{"id":"b36f7519-1e96-4582-b691-9181d0b822b9","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 45.","contenido":"- Corresponde a la Dirección General de Evaluación del Cumplimiento de Obligaciones de Asignaciones y Contratos el ejercicio de las atribuciones siguientes: I. Recibir, dar seguimiento y evaluar los informes de asignatarios o contratistas sobre cualquier siniestro, hecho o contingencia derivada de las operaciones que pongan en peligro la vida, la salud y seguridad públicas, el medio ambiente, la seguridad de las instalaciones o la producción de hidrocarburos, así como los informes de las causas que los originaron, las medidas tomadas para su control y, en su caso, remediación; II. Requerir informes sobre cualquier siniestro, hecho o contingencia derivados de las operaciones de los autorizados; III. Resguardar la documentación en la que consten los acuerdos alcanzados mediante negociación o las medidas decretadas por el Ejecutivo federal o los tribunales competentes en materia de uso y ocupación superficial con relación a las asignaciones y contratos; IV. Emitir dictamen técnico respecto del modelo de contratación para cada área contractual y proponerlo al superior jerárquico; V. Monitorear las actividades que se llevan a cabo en las áreas de asignaciones o contractuales pudiéndose apoyar de herramientas tecnológicas o de convenios con autoridades encargadas de actividades de verificación e inspección; VI. Desarrollar informes respecto de la ejecución de los planes de exploración o planes de desarrollo para la extracción y sus programas asociados de los asignatarios o contratistas en términos de la normativa aplicable; VII. Supervisar el abandono y desmantelamiento de áreas de asignación y contractuales, en el ámbito de competencia de la Secretaría; VIII. Verificar y emitir el informe sobre la posible existencia de alguna causal de caso fortuito o fuerza mayor, rescisión administrativa o contractual, terminación anticipada y en general cualquier incumplimiento de obligaciones contractuales derivadas de contratos, y someterlo a la consideración de su superior jerárquico; IX. Emitir el informe sobre las solicitudes de reconocimiento de caso fortuito o fuerza mayor presentadas por los operadores, así como sobre las causales de revocación y en general sobre cualquier incumplimiento de los términos y condiciones derivadas del título de asignación o del contrato; X. Emitir opinión sobre la posible existencia de alguna causal de caso fortuito o fuerza mayor de asignaciones y contratos y proponer al superior jerárquico; XI. Verificar que las disposiciones y lineamientos emitidos por la Secretaría sean atendidas por los asignatarios y contratistas para mejorar el desempeño de los campos en exploración y extracción de hidrocarburos del país; XII. Verificar y dar seguimiento a las obligaciones de constitución y aportaciones a los fideicomisos de abandono que se constituyan; XIII. Revisar y validar las garantías que se constituyan con relación a los contratos; XIV. Verificar y emitir el informe de la ejecución de los gastos e inversiones ejercidas por los asignatarios y contratistas, conforme a los planes aprobados y para los efectos que establece la normativa aplicable; XV. Conocer de las posibles violaciones que se detecten al marco normativo, ordenar las medidas que correspondan y emitir recomendaciones al respecto en el ámbito de su competencia; XVI. Coordinar la integración de expedientes de los procedimientos administrativos por el presunto incumplimiento de obligaciones o por violaciones a la Ley del Sector Hidrocarburos y demás disposiciones jurídicas aplicables; XVII. Someter a consideración la persona titular de la Subsecretaría de Hidrocarburos o, en su caso, del Comité de Asignaciones, Contratos y Permisos, a través de la Unidad de Asuntos Jurídicos, el inicio y resolución del procedimiento administrativo de sanción o por posibles incumplimientos, en términos de las atribuciones que se otorgan a la Secretaría en la Ley del Sector Hidrocarburos y demás disposiciones jurídicas aplicables, y XVIII. Revisar y opinar técnicamente la documentación que se someta a consideración de los órganos colegiados en los que la Subsecretaría de Hidrocarburos tenga representación.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LA SUBSECRETARÍA DE ELECTRICIDAD Y SUS UNIDADES ADMINISTRATIVAS","seccion_nombre":null,"orden":46},{"id":"e9b55677-7b36-4d44-9209-1be0b9b59f41","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 46.","contenido":"- Corresponde a la Dirección General de Seguimiento de Asignaciones el ejercicio de las atribuciones siguientes: I. Dar seguimiento y verificar el cumplimiento de las obligaciones de los asignatarios, derivadas de las asignaciones de desarrollo propio y de desarrollo mixto; II. Conocer de las notificaciones o avisos que deriven de las asignaciones previstas en la fracción anterior; III. Dar seguimiento a la ejecución de las actividades consideradas en los planes de exploración y planes de desarrollo para la extracción de asignatarios, así como los programas asociados a estos, de conformidad con la normativa aplicable; IV. Evaluar el cumplimiento de acreditación del compromiso mínimo de trabajo y actividades que presenten los asignatarios, conforme al título, y con el apoyo que se requiera de las unidades técnicas competentes de la Subsecretaría; V. Evaluar la existencia de posibles causales de revocación de asignaciones y proponerlo a la Unidad de Desarrollo de Modelos Contractuales y Asignaciones, Proyectos Regulatorios y Argumentación Técnica; VI. Elaborar el informe en caso de que detecte que un concesionario minero está llevando a cabo actividades de exploración o extracción de hidrocarburos, y dar aviso al superior jerárquico; VII. Administrar la documentación e información correspondiente de los acuerdos alcanzados mediante negociación o las medidas decretadas por el Ejecutivo Federal o los tribunales competentes en materia de uso y ocupación superficial con relación a las asignaciones; VIII. Conocer y analizar las solicitudes de periodos adicionales de exploración, así como de solicitudes de periodos, suspensión de actividades de exploración y extracción, prórrogas a la vigencia presentadas por los asignatarios y proponer al superior jerárquico el proyecto de resolución correspondiente, previa opinión técnica de las unidades técnicas de exploración o extracción, según corresponda; IX. Evaluar, documentar y proponer al superior la opinión sobre la procedencia de alguna causal de caso fortuito o fuerza mayor, revocación, procedimientos de sanción y en general cualquier incumplimiento de los términos y condiciones derivadas del título de asignación; X. Conocer de las posibles violaciones que se detecten al marco normativo, adoptar las medidas correspondientes conforme a su ámbito de competencia y hacerlo del conocimiento de las autoridades competentes en los casos que así proceda; XI. Coordinar la integración de expedientes de los procedimientos administrativos por el presunto incumplimiento de obligaciones o por violaciones a la Ley del Sector Hidrocarburos y demás disposiciones jurídicas aplicables; XII. Someter a consideración la persona titular de la Subsecretaría de Hidrocarburos o, en su caso, del Comité de Asignaciones, Contratos y Permisos, a través de la Unidad de Asuntos Jurídicos, el inicio y resolución del procedimiento administrativo de sanción o por posibles incumplimientos, en términos de las atribuciones que se otorgan a la Secretaría en la Ley del Sector Hidrocarburos y demás disposiciones jurídicas aplicables; XIII. Revisar y opinar técnicamente la documentación que se someta a consideración de los órganos colegiados en los que la Subsecretaría de Hidrocarburos tenga representación; XIV. Emitir el proyecto de dictamen de desincorporación de activos solicitada por el asignatario, y en su caso, una vez aprobada por el Comité instrumentar su ejecución, y XV. Recibir y calificar las pólizas de seguros presentadas por el asignatario, para el cumplimiento de sus obligaciones.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LA SUBSECRETARÍA DE HIDROCA R BUROS Y SUS UNIDADES ADMINISTRATIVAS","seccion_nombre":null,"orden":47},{"id":"a1571feb-d118-431d-9ca3-422cff3b36bd","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 47.","contenido":"- Corresponde a la Dirección General de Seguimiento de Contratos el ejercicio de las atribuciones siguientes: I. Dar seguimiento y verificar el cumplimiento de las obligaciones de los contratistas, derivadas de los contratos; II. Conocer de las notificaciones o avisos que deriven de los contratos previstos en la fracción anterior; III. Supervisar el abandono de equipos en áreas contractuales, en el ámbito de competencia de la Secretaría; IV. Dar seguimiento a la ejecución de las actividades consideradas en los planes de exploración y planes de desarrollo para la extracción de contratistas, así como los programas asociados, de conformidad con la normativa aplicable; V. Evaluar el cumplimiento de acreditación de programa mínimo de trabajo que presenten los contratistas, conforme al contrato, al plan o programa vigente, y con el apoyo que se requiera de las unidades técnicas competentes de la Subsecretaría; VI. Evaluar, documentar y proponer al superior la opinión sobre la posible procedencia de reconocimiento de caso fortuito o fuerza mayor, rescisión administrativa o contractual, terminación anticipada, procedimientos de sanción, imposición de penas convencionales, y cualquier incumplimiento de las obligaciones previstas en los contratos; VII. Elaborar el informe en caso de que detecte que un concesionario minero lleva a cabo actividades de exploración o extracción de hidrocarburos, y dar aviso al superior jerárquico; VIII. Administrar la documentación e información correspondiente de los acuerdos alcanzados mediante negociación o las medidas decretadas por el Ejecutivo federal o los tribunales competentes en materia de uso y ocupación superficial con relación a los contratistas; IX. Conocer y analizar las solicitudes de periodos adicionales de exploración, así como de solicitudes de periodos, solicitudes de suspensión de actividades de exploración y extracción, o prórrogas a la vigencia presentadas por los contratistas y proponer al superior jerárquico el proyecto de resolución correspondiente, previa opinión técnica de las unidades técnicas de exploración o extracción, según corresponda; X. Conocer de las posibles violaciones que se detecten al marco normativo, adoptar las medidas correspondientes conforme a su ámbito de competencia y hacerlo del conocimiento de las autoridades competentes en los casos que así proceda; XI. Coordinar la integración de expedientes de los procedimientos administrativos por el presunto incumplimiento de obligaciones o por violaciones a la Ley del Sector Hidrocarburos y demás disposiciones jurídicas aplicables; XII. Someter a consideración la persona titular de la Subsecretaría de Hidrocarburos o, en su caso, del Comité de Asignaciones, Contratos y Permisos, a través de la Unidad de Asuntos Jurídicos, el inicio y resolución del procedimiento administrativo de sanción o por posibles incumplimientos, en términos de las atribuciones que se otorgan a la Secretaría en la Ley del Sector Hidrocarburos y demás disposiciones jurídicas aplicables; XIII. Revisar y opinar técnicamente la documentación que se someta a consideración de los órganos colegiados en los que la Subsecretaría de Hidrocarburos tenga representación; XIV. Calcular las penalizaciones relativas al pago de contraprestaciones a cargo del o contratista; XV. Emitir el proyecto de dictamen de desincorporación de activos solicitada por los contratistas, y en su caso, una vez aprobada por el comité instrumentar su ejecución; XVI. Recibir y calificar las pólizas de seguros presentadas por los contratistas, para el cumplimiento de sus obligaciones.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LA SUBSECRETARÍA DE HIDROCA R BUROS Y SUS UNIDADES ADMINISTRATIVAS","seccion_nombre":null,"orden":48},{"id":"1f07823b-223a-4a30-9d7b-35ea057aa345","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 48.","contenido":"- Corresponde a la Dirección General de Supervisión Técnica el ejercicio de las atribuciones siguientes: I. Realizar las órdenes de verificación e inspección con base en la resolución del superior jerárquico y de acuerdo con las disposiciones legales, reglamentarias y normativas aplicables; II. Dar inicio y conclusión a las visitas de verificación e inspección, tanto ordinarias como extraordinarias, que se deban llevar a cabo en términos de la normativa aplicable; III. Mantener actualizada la lista de las personas servidoras públicas y terceros independientes, autorizados para re alizar certificaciones, auditorí as y visitas de verificación e inspecciones; IV. Dar seguimiento y verificar el cumplimiento de las obligaciones de los autorizados, asignatarios y contratistas en materia de perforación de pozos y demás actividades en materia de exploración y extracción de hidrocarburos; V. Coordinar y proponer al superior jerárquico el Programa Anual de Visitas de Verificación e Inspección, así como las visitas no programadas, en términos de la normativa aplicable, conforme a las propuestas presentadas por las unidades técnicas de la Subsecretaría, dependiendo de su ámbito de competencia; VI. Verificar las funciones logísticas, administrativas y estadísticas en la práctica de las visitas de verificación e inspección ordinarias y extraordinarias; VII. Emitir opinión técnica respecto de los resultados y, en su caso, los posibles incumplimientos detectados en las prácticas de vistas de verificación e inspección; VIII. Elaborar el informe del cumplimiento de las obligaciones contenidas en los permisos de importación y exportación de petróleo, gas natural, petrolíferos y petroquímicos y en la normatividad aplicable a los mismos; IX. Verificar la actualización de la información que, en materia de comercio exterior de petróleo, gas natural, petrolíferos y petroquímicos, que reciba en ejercicio de sus atribuciones; X. Elaborar el informe sobre cualquier incumplimiento detectado, que pueda ser una causal de revocación o caducidad de permisos de importación y exportación de hidrocarburos, petroquímicos y petrolíferos; XI. Realizar visitas de verificación a las instalaciones de los permisionarios y de todas aquellas personas involucradas en la logística de la importación y exportación de petróleo, petrolíferos, petroquímicos y gas natural; XII. Emitir el informe con respecto a las estrategias para el fomento industrial de cadenas productivas locales y para el fomento de la inversión directa en la industria de hidrocarburos, con especial atención a las pequeñas y medianas empresas, definidas por la Secretaría de Economía; XIII. Requerir información a los operadores petroleros, las dependencias y entidades de la Administración Pública Federal u otros organismos o instituciones, públicos o privados para dar seguimiento al avance en la ejecución de las actividades contenidas en los programas de capacitación y transferencia de tecnología; XIV. Supervisar el cumplimiento de los programas de capacitación y transferencia de tecnología, de conformidad con las facultades y atribuciones que le correspondan; XV. Elaborar el dictamen de procedencia y proponer al superior jerárquico el inicio de un procedimiento administrativo de sanción, derivado de los resultados de las visitas ejecutadas; XVI. Supervisar la elaboración e implementación de programas de capacitación y profesionalización del personal verificador, a efecto de fomentar su actualización y mejora continua; XVII. Elaborar y proponer al superior, los porcentajes mínimos de contenido nacional que deben incluirse en cada asignación y contrato, previa opinión de la Secretaría de Economía ; XVIII. Solicitar la opinión de la Secretaría de Economía, respecto de los porcentajes mínimos de contenido nacional que deben incluirse en cada asignación y contrato; XIX. Conocer de las posibles violaciones que se detecten al marco normativo, adoptar las medidas correspondientes conforme a su ámbito de competencia y hacerlo del conocimiento de las autoridades competentes en los casos que así proceda; XX. Calcular las penalizaciones relativas al pago de contraprestaciones a cargo del asignatario o contratista; XXI. Emitir el dictamen de desincorporación de activos solicitada por el asignatario o contratistas, y en su caso, una vez aprobada por el Comité instrumentar su ejecución; XXII. Recibir y calificar las pólizas de seguros presentadas por el asignatario o contratistas, para el cumplimiento de sus obligaciones; XXIII. Proponer al superior jerárquico, el dictamen para aprobación de los programas de capacitación y transferencia de tecnología de los asignatarios y contratistas; XXIV. Proponer al superior jerárquico, las personas servidoras públicas de la Secretaría y terceros que realizarán las visitas de verificación e inspección y, en su caso, aprobar los organismos para la evaluación de la conformidad de las normas oficiales mexicanas competencia de la Subsecretaría de Hidrocarburos; XXV. Coordinar la integración de expedientes de los procedimientos administrativos por el presunto incumplimiento de obligaciones o por violaciones a la Ley del Sector Hidrocarburos y demás disposiciones jurídicas aplicables; XXVI. Someter a consideración la persona titular de la Subsecretaría de Hidrocarburos o, en su caso, del Comité de Asignaciones, Contratos y Permisos, a través de la Unidad de Asuntos Jurídicos, el inicio y resolución del procedimiento administrativo de sanción o por posibles incumplimientos, en términos de las atribuciones que se otorgan a la Secretaría en la Ley del Sector Hidrocarburos y demás disposiciones jurídicas aplicables, y XXVII. Revisar y opinar técnicamente la documentación que se someta a consideración de los órganos colegiados en los que la Subsecretaría de Hidrocarburos tenga representación. CAPÍTULO IX DE LAS UNIDADES ADMINISTRATIVAS ADSCRITAS A LA UNIDAD DE ADMINISTRACIÓN Y FINANZAS","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LA SUBSECRETARÍA DE HIDROCA R BUROS Y SUS UNIDADES ADMINISTRATIVAS","seccion_nombre":null,"orden":49},{"id":"382bc51e-7d02-4926-a6cd-62a75f2ef18f","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 49.","contenido":"- Corresponde a la Dirección General de Programación y Presupuesto, el ejercicio de las atribuciones siguientes: I. Proponer y aplicar criterios e instrumentos normativos de carácter administrativo, para la gestión de los recursos financieros de la Secretaría, sus órganos administrativos desconcentrados, así como de las entidades paraestatales sectorizadas a esta, verificando el cumplimiento de las políticas presupuestarias y administrativas que se establezcan; II. Aplicar, en el ámbito de competencia de la Secretaría y del sector coordinado, los ordenamientos legales y demás normas jurídicas que de éstos deriven, cuyas disposiciones regulen materias de programación, presupuesto, finanzas, ejercicio del gasto, seguimiento, evaluación y rendición de cuentas, así como emitir, en su caso, criterios de aplicación, siempre que dichas facultades no correspondan a otra unidad administrativa o bien a una entidad coordinada; III. Participar, en el ámbito de su competencia, como enlace ante la Secretaría de Hacienda y Crédito Público y la Secretaría Anticorrupción y Buen Gobierno, en la atención de requerimientos de esas dependencias y en la formulación, instrumentación, seguimiento y evaluación de los programas sectoriales, regionales, especiales e institucionales que se deriven del Plan Nacional de Desarrollo y de las líneas programáticas a cargo de la Secretaría; IV. Coordinar con las áreas responsables, los procesos de planeación, programación, finanzas y presupuestación, ejercicio del gasto, seguimiento, evaluación y rendición de cuentas de la Secretaría, sus órganos administrativos desconcentrados y las entidades paraestatales sectorizadas a esta, así como el control y contabilidad de los mismos, con apego a las políticas y lineamientos aplicables; V. Solicitar, obtener y analizar la información presupuestal y financiera de sus órganos administrativos desconcentrados, así como de las entidades paraestatales sectorizadas a esta, en apego a las disposiciones aplicables y a los mecanismos y bases de colaboración que se establezcan, para consolidar la visión operativa del sector, sin que ello afecte su autonomía jurídica, técnica y presupuestal; VI. Proponer las medidas de implementación de control presupuestario que fueren necesarias para la programación, presupuestación y administración de los recursos financieros de la Secretaría, sus órganos administrativos desconcentrados, así como de las entidades paraestatales sectorizadas a esta; VII. Implementar y coordinar medidas que permitan conocer la evolución y ejercicio de los recursos asignados a las unidades administrativas de la Secretaría, así como a los órganos administrativos desconcentrados y entidades coordinadas, incluyendo los ingresos propios; VIII. Dictaminar las solicitudes de modificación presupuestaria de la Secretaría y en el caso de adecuaciones internas de sus órganos administrativos desconcentrados, así como de las entidades paraestatales sectorizadas a esta, emitir autorización, así como gestionar su registro ante las instancias competentes; IX. Orientar las actividades inherentes a la concertación de las estructuras programáticas, formulación del programa de mediano plazo, anteproyecto de presupuesto de egresos e ingresos de la Secretaría, sus órganos administrativos desconcentrados, así como de las entidades paraestatales sectorizadas a esta; X. Verificar que las estructuras programáticas, la formulación del programa de mediano plazo, y el anteproyecto de presupuesto de egresos e ingresos, se sujeten a las normas, montos y plazos que establezcan las autoridades competentes y presentarlos al superior jerárquico para que los someta a la aprobación de la persona titular de la Secretaría; XI. Analizar y suscribir las evaluaciones de impacto presupuestario de las iniciativas de Ley o Decreto en relación con el Sector, en apego a las disposiciones aplicables; XII. Comunicar a las unidades administrativas de la Secretaría, sus órganos administrativos desconcentrados, así como de las entidades paraestatales sectorizadas a esta, el presupuesto aprobado por la Cámara de Diputados y en su caso, los calendarios de ingreso-gasto autorizados por la Secretaría de Hacienda y Crédito Público; XIII. Ser el enlace de las unidades administrativas, de la Secretaría, sus órganos administrativos desconcentrados, así como de las entidades paraestatales sectorizadas a esta, ante la Secretaría de Hacienda y Crédito Público para solicitar autorizaciones especiales, a efecto de contraer compromisos de adquisiciones, contratación de servicios y obra pública, con cargo a ejercicios fiscales subsecuentes, de conformidad con la normativa aplicable; XIV. Gestionar ante la Secretaría de Hacienda y Crédito Público, la autorización de los proyectos de infraestructura productiva de largo plazo de sus órganos administrativos desconcentrados, así como de las entidades paraestatales sectorizadas a esta; XV. Fungir como instancia única de las unidades administrativas y órganos administrativos desconcentrados de la Secretaría, así como de las entidades paraestatales sectorizadas a esta, para gestionar las solicitudes que impliquen la afectación o modificación de su presupuesto autorizado, registro y liberación de su programa de inversión, suscripción o renovación de convenios de desempeño, conforme al ámbito de su competencia y en términos de la normatividad aplicable; XVI. Coordinar y administrar los sistemas, trámites y procedimientos administrativos internos para el ejercicio, registro presupuestario, pago o reembolso del gasto y registro contable del mismo, efectuado por las unidades administrativas de la Secretaría. Asimismo, coordinar y gestionar los Sistemas Informáticos en materia programática, presupuestal y contable establecidos por la Secretaría de Hacienda y Crédito Público para la integración y consolidación de la información del Ramo, de conformidad con las disposiciones jurídicas aplicables; XVII. Gestionar las ministraciones de recursos por concepto de subsidios y transferencias a las entidades del sector apoyadas; así como dar seguimiento al ejercicio del gasto, conforme a la normatividad aplicable; XVIII. Coordinar a las unidades administrativas de la Secretaría, sus órganos administrativos desconcentrados, así como de las entidades paraestatales sectorizadas a esta, atendiendo la forma, términos y plazos conforme a los cuales deben proporcionar la información programática, presupuestal, financiera, contable o de otra índole, a fin de cumplir con los requerimientos que presenten las autoridades competentes; XIX. Establecer y administrar la operación del sistema de contabilidad gubernamental de la Secretaría, así como formular, consolidar y presentar ante la Secretaría de Hacienda y Crédito Público, la Cuenta Anual de la Hacienda Pública Federal, conforme a las disposiciones legales y normatividad aplicable; XX. Planear, coordinar, supervisar y asesorar el proceso de registro de las operaciones financieras, presupuestales y patrimoniales de la Secretaría, sus órganos administrativos desconcentrados, así como de las entidades paraestatales sectorizadas a esta, para proporcionar información programática y presupuestal veraz y oportuna, en apoyo de la toma de decisiones y la rendición de cuentas; XXI. Coordinar con las áreas responsables de la Secretaría y de la Secretaría de Hacienda y Crédito Público el funcionamiento y uso de los sistemas informáticos de programación, presupuesto, operación financiera y contabilidad, con apoyo de la Dirección General de Desarrollo de Sistemas, Infraestructura y Comunicaciones; XXII. Fungir como enlace entre las instancias fiscalizadoras y las unidades administrativas y órganos administrativos desconcentrados de la Secretaría, así como de las entidades paraestatales sectorizadas a esta, para la atención y seguimiento de los requerimientos de información y los procesos de auditoría que realicen las instancias fiscalizadoras, y XXIII. Sustentar los trámites programático-presupuestarios que deban realizarse ante la Secretaría de Hacienda y Crédito Público, con base a la información proporcionada por las unidades administrativas de la Secretaría, sus órganos administrativos desconcentrados, así como de las entidades paraestatales sectorizadas a esta, soportada con dictámenes técnicos emitidos por los titulares de las áreas sustantivas competentes de la Secretaría.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LAS UNIDADES ADMINISTRATIVAS ADSCRITAS A LA UNIDAD DE ADMINISTRACIÓN Y FINANZAS","seccion_nombre":null,"orden":50},{"id":"ee523330-3cc0-4bfa-8b71-d36c8c1d85fa","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 50.","contenido":"- Corresponde a la Dirección General de Recursos Humanos, el ejercicio de las atribuciones siguientes: I. Proponer las disposiciones normativas internas para el ingreso, la administración de los recursos humanos, remuneraciones, prestaciones y sistemas de pagos, capacitación, certificación de capacidades, profesionalización, desarrollo organizacional, evaluación del desempeño, certificación y mejora; II. Proponer en coordinación con la Dirección General de Programación y Presupuesto, el anteproyecto del presupuesto anual de la Secretaría, en lo relativo a servicios personales; de procesos de comunicación interna, servicio social y prácticas profesionales, actividades sociales, culturales y recreativas para el personal que requieran las unidades administrativas de la Secretaría; III. Administrar el ejercicio y la aplicación del presupuesto anual de la Secretaría en materia de servicios personales en estricto apego a la normatividad en la materia; IV. Coordinar la planeación de los recursos humanos, desarrollo organizacional y actualización de la estructura orgánica, así como realizar los trámites procedentes ante las autoridades competentes; V. Supervisar la actualización del registro presupuestal de las estructuras orgánicas, ocupacionales y salariales de la Secretaría y verificar que sus unidades administrativas y órganos administrativos desconcentrados se ajusten a lo autorizado; así como para su registro ante la Secretaría Anticorrupción y Buen Gobierno; VI. Proponer a la persona titular de la Unidad de Administración y Finanzas los proyectos de dictamen sobre las reestructuraciones, creaciones, modificaciones o eliminaciones orgánico-funcionales de las unidades administrativas y órganos administrativos desconcentrados de la Secretaría, así como realizar el trámite correspondiente ante las autoridades competentes; VII. Elaborar y emitir, las constancias y nombramientos para autorización y firma conjunta con la persona titular de la Unidad de Administración y Finanzas de las personas servidoras públicas adscritas a la Secretaría; VIII. Planear, organizar y ejecutar los procesos para el ingreso y administración de los recursos humanos; el desarrollo organizacional, las remuneraciones y prestaciones, y los sistemas de pagos; IX. Promover la capacitación, certificación de capacidades, profesionalización, evaluación del desempeño, comunicación interna, servicio social y prácticas profesionales; así como las actividades sociales, culturales y recreativas para las personas servidoras públicas adscritas a la Secretaría; X. Elaborar y proponer el Programa Anual de Capacitación con el fin de someterlo a la revisión y autorización del Comité Técnico de Profesionalización, así como coordinar y ejecutar su implementación; XI. Expedir las constancias de nombramientos, credenciales, hojas de servicios, constancias y demás documentos que correspondan al personal; XII. Revisar y autorizar, previa solicitud, los cambios de adscripción del personal operativo y, en su caso, determinar la procedencia en los casos de terminación sobre los efectos del nombramiento; asimismo, ejecutar y supervisar los trámites, registros y demás diligencias que de ellos se deriven; XIII. Coordinar la contratación del personal eventual y bajo el régimen de honorarios, así como suscribir los contratos respectivos; XIV. Establecer y administrar los sistemas de pago de las remuneraciones del personal, las retenciones, descuentos, pagos a terceros, suspensión y pagos ordenados por las autoridades judiciales, así como dar seguimiento a la recuperación de salarios y otros conceptos no devengados, previa validación presupuestaria, en su caso; XV. Coordinar el sistema de evaluación del desempeño para la entrega de incentivos, estímulos y recompensas al personal adscrito a la Secretaría, así como de los premios por antigüedad; XVI. Coordinar, con el apoyo de la Unidad de Asuntos Jurídicos, la revisión de las Condiciones Generales de Trabajo y revisar la evaluación del impacto presupuestal de las modificaciones a estas, para someterlas a consideración de la persona titular de la Unidad de Administración y Finanzas; XVII. Proponer las Condiciones Generales de Trabajo, con el fin de obtener la autorización de la persona titular de la Secretaría, y tramitar su registro ante las autoridades competentes, así como administrar su aplicación y conducir las relaciones con la representación sindical en coordinación con la Unidad de Asuntos Jurídicos; XVIII. Autorizar licencias al personal de base, en los términos de las Condiciones Generales de Trabajo; XIX. Proponer su aprobación para la designación y remoción de representantes de la Secretaría ante la Comisión Mixta de Escalafón y ante las comisiones mixtas que se integren; así como, mantener actualizado el sistema de escalafón para los trabajadores; XX. Ejecutar para efectos administrativos, en coordinación con las unidades administrativas respectivas, los actos que se deriven de resoluciones, laudos o sentencias relacionadas con el personal; XXI. Imponer las sanciones y medidas disciplinarias al personal que incurra en irregularidades o faltas de carácter laboral, en coordinación con la Unidad de Asuntos Jurídicos, de conformidad con las disposiciones jurídicas aplicables; XXII. Vigilar el cumplimiento del proceso de archivo, conservación, resguardo y consulta de la documentación e información relacionada con el personal, incluyendo sus datos personales; XXIII. Implementar y coordinar la operación del Sistema del Servicio Profesional de Carrera y los subsistemas que lo integran en cumplimiento con las disposiciones jurídicas aplicables, así como verificar el cumplimiento de indicadores; XXIV. Coordinar y supervisar el proceso de comunicación interna, así como la administración de la información de la intranet institucional, de conformidad con las disposiciones jurídicas aplicables y criterios institucionales; XXV. Verificar la integración y el funcionamiento de los comités establecidos en la Ley del Servicio Profesional de Carrera en la Administración Pública Federal; XXVI. Promover, organizar, desarrollar y evaluar programas para el otorgamiento de prestaciones económicas y de previsión social, así como eventos deportivos, culturales y sociales que se proporcionen en beneficio del personal y sus familias; XXVII. Coordinar la elaboración, instrumentación y actualización de los lineamientos internos de organización, funcionamiento y elaboración del Manual de Organización General y demás manuales administrativos; XXVIII. Coordinar los programas de servicio social y prácticas profesionales de la Secretaría, así como la vinculación con las instituciones educativas; XXIX. Establecer los lineamientos generales, así como, los criterios de estructura, forma y contenido para la elaboración y actualización del Manual de Organización General y demás manuales administrativos; XXX. Fungir como ventanilla única de gestión de las unidades administrativas y órganos administrativos desconcentrados de la Secretaría, así como de las entidades paraestatales sectorizadas a esta, en materia de recursos humanos, estructuras orgánicas, y salariales, ante las instancias correspondientes, y XXXI. Administrar el Sistema de Gestión de la Calidad y promover la Mejora de Procesos, así como brindar asesoría para el diseño y la mejora de estos.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LAS UNIDADES ADMINISTRATIVAS ADSCRITAS A LA UNIDAD DE ADMINISTRACIÓN Y FINANZAS","seccion_nombre":null,"orden":51},{"id":"e84744f8-f504-4b4b-9bdb-e2b36f89673e","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo   51.","contenido":"- Corresponde a la Dirección General de Recursos Materiales y Servicios Generales, el ejercicio de las atribuciones siguientes: I. Proponer en coordinación con la Dirección General de Programación y Presupuesto, el anteproyecto del presupuesto anual de la Secretaría, en lo relativo a adquisiciones, servicios generales, arrendamientos, mantenimiento, seguros y obras, así como de los recursos materiales, adquisición de bienes, contratación de servicios y la prestación de servicios generales que requieran las unidades administrativas de la Secretaría; II. Administrar el ejercicio y la aplicación del presupuesto anual de la Secretaría en materia de adquisiciones, arrendamientos, mantenimiento, servicios generales, seguros y obras en estricto apego a la normatividad en la materia; III. Proporcionar los servicios de apoyo administrativo que se requieran en materia de servicios generales, conservación y mantenimiento de bienes muebles e inmuebles, seguridad y vigilancia y aseguramiento de bienes patrimoniales; IV. Proponer para aprobación de la persona titular de la Unidad de Administración y Finanzas y, en su caso, de los Comités respectivos según corresponda, los Programas Anuales de Recursos Materiales y Servicios Generales, Adquisiciones, Arrendamientos y Servicios, Disposición Final de los Bienes Muebles y de Trabajo relacionado a Uso Eficiente de la Energía, con base en los requerimientos que presenten las unidades administrativas, así como coordinar y evaluar su desarrollo; V. Someter a consideración de la persona titular de la Unidad de Administración y Finanzas, la propuesta de políticas de recursos materiales y servicios generales que se estime conveniente instrumentar en la Secretaría; VI. Proporcionar los servicios de apoyo administrativo que se requieran en materia de servicios generales, conservación y mantenimiento de bienes muebles e inmuebles, seguridad y vigilancia y aseguramiento de bienes patrimoniales; VII. Dirigir los procedimientos relativos a la adquisición, arrendamiento y contratación de bienes, y servicios, obra pública y servicios relacionados con las mismas, que requiera la Secretaría y, cuando proceda, de sus órganos administrativos desconcentrados, de conformidad con la normatividad aplicable; VIII. Suscribir, dar por terminados y rescindir los contratos, convenios y demás instrumentos jurídicos que determinen obligaciones a la Secretaría o que afecten su presupuesto, con la opinión de la Unidad de Asuntos Jurídicos; IX. Verificar el funcionamiento de los comités establecidos en la Ley de Adquisiciones, Arrendamientos y Servicios del Sector Público, Ley de Obras Públicas y Servicios Relacionados con las Mismas, Ley General de Bienes Nacionales y demás disposiciones normativas que le resulten aplicables; X. Administrar y mantener actualizado el inventario de los bienes muebles e inmuebles de que dispone la Secretaría, con la participación de las unidades administrativas que los tengan asignados, de conformidad con las disposiciones jurídicas aplicables; XI. Proponer para aprobación de la persona titular de la Unidad de Administración y Finanzas el Programa Inmobiliario; XII. Conducir las relaciones con el Instituto de Administración y Avalúos de Bienes Nacionales y demás autoridades competentes en materia de bienes muebles e inmuebles; XIII. Administrar los almacenes e inventarios y distribuir los bienes e insumos entre las unidades administrativas de la Secretaría; XIV. Administrar, asegurar, mantener y conservar los activos de la Secretaría para su funcionamiento y resguardo, así como representar a la Secretaría ante las instancias competentes y darle destino final a los bienes muebles; XV. Proponer el Programa Anual de Mantenimiento de las instalaciones, inmuebles, mobiliario y equipo de la Secretaría, así como coordinar su ejecución; XVI. Coordinar los servicios generales de la Secretaría; XVII. Coordinar la ejecución del Programa de Seguridad Institucional de la Secretaría; XVIII. Proponer el Programa Interno de Protección Civil para salvaguardar el personal, instalaciones, bienes e información de la Secretaría, así como coordinar la aplicación de las normas y disposiciones que emita la Secretaría de Gobernación para la operación, desarrollo y vigilancia de dicho programa, y XIX. Supervisar los procedimientos relativos para el registro, afectación, disposición final y baja de bienes que no resulten útiles, de conformidad con las disposiciones jurídicas aplicables.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LA SUBSECRETARÍA DE PLANEACIÓN Y TRANSICIÓN ENERGÉTICA Y SUS UNIDADES ADMINISTRATIVAS","seccion_nombre":null,"orden":52},{"id":"fe075d62-1dbe-419d-a296-6de5c5af3df3","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 52.","contenido":"- Corresponde a la Dirección General de Desarrollo de Sistemas, Infraestructura y Comunicaciones, el ejercicio de las atribuciones siguientes: I. Dirigir y supervisar la aplicación de los ordenamientos legales y demás normas jurídicas en materia de tecnologías de información y comunicaciones, así como emitir las políticas internas, criterios, manuales, procedimientos y demás instrumentos para el cumplimiento de sus atribuciones, y, en su caso, coordinarse con la Agencia de Transformación Digital y Telecomunicaciones; II. Proponer las medidas de implementación de tecnologías de información y comunicaciones para la integración, uso, aprovechamiento y comunicación de la información con las unidades administrativas y órganos administrativos desconcentrados de la Secretaría; III. Elaborar, administrar y ejecutar la estrategia digital de la Secretaría, con la participación de las unidades administrativas de la Secretaría, así como coordinar su evaluación y seguimiento; IV. Proponer mecanismos de simplificación, modernización, automatización y arquitectura de procesos, para el mejor uso y aprovechamiento de las tecnologías de información y comunicaciones en la Secretaría y sus órganos administrativos desconcentrados; V. Dirigir, supervisar, controlar y evaluar las actividades, programas, objetivos y metas de la Secretaría en materia de tecnologías de información y comunicaciones; VI. Establecer los estándares de la Secretaría en materia de seguridad, autentificación, privacidad y operación de los servicios de tecnologías de información y comunicaciones, así como los relacionados con el desarrollo de aplicaciones, infraestructura y arquitectura en las materias señaladas; VII. Determinar y valorar técnicamente las características de los bienes y servicios que deban ser adquiridos o contratados, en materia de tecnologías de la información y comunicaciones; así como gestionar la dictaminación técnica por parte de la autoridad competente; VIII. Administrar la infraestructura y los servicios de tecnologías de la información y comunicaciones que se proporcionen a las unidades administrativas de la Secretaría; IX. Proponer las adecuaciones a los sistemas de información y bases de datos de la Secretaría; X. Dirigir los protocolos de seguridad de la información en medios tecnológicos de la Secretaría y sus órganos administrativos desconcentrados, de conformidad con las disposiciones jurídicas aplicables, para asegurar la confidencialidad, integridad y disponibilidad de la información, y, en su caso, coordinarse con la Agencia de Transformación Digital y Telecomunicaciones; XI. Proporcionar los medios necesarios para la transmisión de voz, información e imágenes que requieran las unidades administrativas de la Secretaría; XII. Fungir como enlace de la Secretaría con dependencias, entidades, instituciones y empresas tanto nacionales como internacionales relacionadas con las tecnologías de información y las comunicaciones; XIII. Aprobar la asignación y la gestión de la baja de los bienes informáticos, así como de las cuentas de las personas usuarias en la Secretaría, en el ámbito de su competencia; XIV. Instrumentar y administrar los medios y aplicaciones para la publicación de información a través de internet e intranet; XV. Aprobar y dirigir en coordinación con las unidades administrativas de la Secretaría, proyectos para la innovación y automatización de procesos para optimizar su operación; XVI. Suscribir, en el ámbito de su competencia, los convenios, contratos, bases de colaboración, acuerdos y demás instrumentos en materia de tecnologías de información y comunicaciones, y de seguridad de la información, que no tengan por objeto generar obligaciones de pago; XVII. Coordinar a las direcciones generales de tecnologías y comunicaciones u homólogas en sus órganos administrativos desconcentrados, así como de las entidades paraestatales sectorizadas a esta, así como solicitar la información que se requiera para atender los asuntos de su competencia; XVIII. Validar y aprobar las adecuaciones necesarias a los sistemas de información y bases de datos de los órganos administrativos desconcentrados de la Secretaría cuando así se requiera, y XIX. Validar y Aprobar la asignación y la gestión de la baja de los bienes informáticos, así como de las cuentas de las personas usuarias en los órganos administrativos desconcentrados de la Secretaría, en el ámbito de su competencia. CAPÍTULO X DE LAS UNIDADES ADMINISTRATIVAS ADSCRITAS A LA OFICINA DE LA PERSONA TITULAR DE LA SECRETARÍA","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LA SUBSECRETARÍA DE PLANEACIÓN Y TRANSICIÓN ENERGÉTICA Y SUS UNIDADES ADMINISTRATIVAS","seccion_nombre":null,"orden":53},{"id":"e94d32a9-8397-4ca6-a2b9-c5cf62771ffa","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 53.","contenido":"- Corresponde a la Unidad de Asuntos Jurídicos, el ejercicio de las atribuciones siguientes: I. Asesorar jurídicamente a la persona titular de la Secretaría, a las unidades administrativas de la Secretaría y actuar como órgano de consulta de estas, para el cumplimiento de las leyes, reglamentos, decretos, acuerdos, circulares y demás disposiciones jurídicas en el ámbito de su competencia; II. Asesorar jurídicamente a las entidades paraestatales y empresas públicas del Estado sectorizadas a la Secretaría, así como a los órganos administrativos desconcentrados de dicha dependencia, respecto de los asuntos relativos a las funciones de la Secretaría o cualquier otra materia de su competencia; III. Revisar e instruir la elaboración de documentos que suscriba la persona titular de la Secretaría; IV. Revisar y emitir opinión sobre proyectos de instrumentos legales que deban ser suscritos por la persona titular de la Secretaría; V. Revisar y emitir opinión sobre los instrumentos jurídicos y disposiciones legales en las materias competencia de la Secretaría, que las unidades administrativas de la Secretaría sometan a su consideración; VI. Emitir opinión jurídica y coordinar el trámite de la publicación en el Diario Oficial de la Federación de las disposiciones normativas que expidan las unidades administrativas de la Secretaría; VII. Validar el trámite de la publicación en el Diario Oficial de la Federación de las disposiciones normativas que expidan entidades paraestatales y empresas públicas del Estado sectorizadas a la Secretaría, así como a los órganos administrativos desconcentrados de dicha dependencia, previa opinión de las unidades administrativas competentes; VIII. Interpretar el presente Reglamento, las leyes y demás ordenamientos legales competencia de la Secretaría para efectos jurídicos; IX. Revisar y emitir opinión sobre proyectos de reglamentos, decretos, acuerdos, circulares y demás disposiciones jurídicas que deban ser suscritos por la persona titular de la Secretaría; X. Revisar y, en su caso, instruir la elaboración de los proyectos de iniciativas de leyes, decretos, reglamentos y demás disposiciones jurídicas relacionados con la competencia de la Secretaría; XI. Revisar y validar las disposiciones normativas que emita n las unidades administrativas y los órganos administrativos desconcentrados de la Secretaría, así como de las entidades paraestatales sectorizadas a esta; XII. Revisar y validar la emisión, modificación y cancelación de normas oficiales mexicanas, procedimientos de evaluación de la conformidad, procedimientos de homologación, así como de otras disposiciones normativas competencia de las unidades administrativas y los órganos administrativos desconcentrados de la Secretaría, así como de las entidades paraestatales sectorizadas a esta; XIII. Dirigir la tramitación de los análisis de impacto regulatorio relativos a los proyectos de regulación que emita la Secretaría y remitirlos al responsable oficial de mejora regulatoria; XIV. Dirigir la integración y, en su caso, ejecución de la agenda de mejora regulatoria y del programa de mejora regulatoria a cargo de la Secretaría; XV. Coordinar y participar en los comités consultivos nacionales de normalización para el sector energético o cualquier otra materia competencia de la Secretaría; XVI. Participar en los comités técnicos de estandarización para el sector eléctrico, sector hidrocarburos y en las materias de planeación y transición energética o cualquier otra materia competencia de la Secretaría; XVII. Representar legalmente en los juicios de amparo a la persona titular de la Secretaría o cuando ésta represente a la persona titular del Ejecutivo Federal; XVIII. Representar legalmente a la Secretaría, a la persona titular de esta y a las unidades administrativas que tiene adscritas, en toda clase de procedimientos judiciales, jurisdiccionales, contenciosos administrativos y laborales que se tramiten ante las autoridades judiciales y jurisdiccionales competentes; XIX. Fungir como enlace de la Secretaría con los organismos de protección de los derechos humanos; XX. Formular denuncias o querellas en representación de la Secretaría o de las unidades administrativas que tiene adscritas, coadyuvar con el Ministerio Público en el ejercicio de la acción penal y, en su caso, otorgar el perdón legal; XXI. Conducir y dirigir el trámite y substanciación de los recursos de revisión que deban ser resueltos por la persona titular de la Secretaría, así como instruir la realización de todos los actos procesales necesarios; XXII. Promover e intervenir en las reclamaciones, juicios y procedimientos en que la Secretaría tenga interés y, en general, en aquellos asuntos cuyas resoluciones puedan afectar los bienes asignados a esta, sin perjuicio de las atribuciones que correspondan a la Fiscalía General de la República; XXIII. Asistir y asesorar a las unidades administrativas de la Secretaría, en el levantamiento de las actas administrativas; XXIV. Dirigir y coadyuvar en las acciones necesarias para la atención de los mecanismos alternativos de solución de controversias en los que la Secretaría sea parte, así como negociar la solución más conveniente a los intereses de ésta; XXV. Representar legalmente a la Secretaría en todo tipo de procedimientos de arbitraje en México o en el extranjero en el que sea parte; XXVI. Coordinar y solicitar a las entidades paraestatales y empresas públicas del Estado sectorizadas a la Secretaría, así como a los órganos administrativos desconcentrados de dicha dependencia, la información y documentación para la estrategia legal en todo tipo de procedimientos jurisdiccionales y de arbitraje en México o en el extranjero; XXVII. Someter a consideración del Comité de Asignaciones, Contratos y Permisos, a solicitud de las unidades administrativas de la Secretaría competentes, el inicio y resolución del procedimiento administrativo de sanción; XXVIII. Dirigir la substanciación y tramitación de los procedimientos administrativos de revocación, caducidad y sanción e imposición de sanciones derivados de la ejecución o incumplimiento de las autorizaciones, permisos, asignaciones, contratos u obligaciones establecidas en las leyes, así como de otros actos competencia de la Secretaría; XXIX. Notificar las resoluciones que apruebe y emita el Comité de Asignaciones, Contratos y Permisos y, en su caso, ejecutar lo ordenado en estas con el apoyo de las unidades administrativas competentes de la Secretaría; XXX. Determinar la existencia y actualización de las causales de caso fortuito o fuerza mayor, de rescisión administrativa o contractual, terminación anticipada e imposición de penas convencionales y sanciones, derivadas de las asignaciones y contratos en materia de hidrocarburos, previa solicitud de las unidades administrativas de la Secretaría competentes; XXXI. Coordinar a las unidades de asuntos jurídicos de las entidades paraestatales y empresas públicas del Estado sectorizadas a la Secretaría, así como a los órganos administrativos desconcentrados de dicha dependencia, así como solicitar la información que se requiera para resolver los asuntos de su competencia, y XXXII. Solicitar a las unidades administrativas de la Secretaría, la formulación de argumentos técnicos, así como la remisión de información y documentación correspondiente, para la adecuada representación y defensa en los asuntos jurisdiccionales y la resolución de los procedimientos administrativos de su competencia.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LAS UNIDADES ADMINISTRATIVAS ADSCRITAS A LA OFICINA DE LA PERSONA TITULAR DE LA SECRETARÍA","seccion_nombre":null,"orden":54},{"id":"68165f06-1116-4698-ba60-01ba04fbe58c","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 54.","contenido":"- Corresponde a la Dirección General de lo Consultivo, el ejercicio de las atribuciones siguientes: I. Asesorar jurídicamente a la persona titular de la Secretaría, a las unidades administrativas de la Secretaría y actuar como órgano de consulta de éstas, para el cumplimiento de las leyes, reglamentos, decretos, acuerdos, circulares y demás disposiciones jurídicas en el ámbito de su competencia; II. Asesorar jurídicamente a las entidades paraestatales y empresas públicas del Estado sectorizadas a la Secretaría, así como a los órganos administrativos desconcentrados de dicha dependencia, respecto de los asuntos relativos a las funciones de la Secretaría o cualquier otra materia de su competencia; III. Revisar y coordinar la elaboración de documentos que suscriba la persona titular de la Secretaría; IV. Revisar y emitir opinión sobre proyectos de instrumentos legales que deban ser suscritos por la persona titular de la Secretaría; V. Revisar y emitir opinión sobre los instrumentos jurídicos y disposiciones legales en las materias competencia de la Secretaría, que las unidades administrativas de la Secretaría sometan a su consideración; VI. Emitir opinión jurídica y coordinar el trámite de la publicación en el Diario Oficial de la Federación de las disposiciones normativas que expidan las unidades administrativas de la Secretaría; VII. Coordinar la revisión del trámite de la publicación en el Diario Oficial de la Federación de las disposiciones normativas que expidan las entidades paraestatales y empresas públicas del Estado sectorizadas a la Secretaría, así como a los órganos administrativos desconcentrados de dicha dependencia, previa opinión de las unidades administrativas competentes, y VIII. Interpretar el presente Reglamento, las leyes y demás ordenamientos legales competencia de la Secretaría para efectos jurídicos.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LAS UNIDADES ADMINISTRATIVAS ADSCRITAS A LA OFICINA DE LA PERSONA TITULAR DE LA SECRETARÍA","seccion_nombre":null,"orden":55},{"id":"2ade6bc3-ca74-4ed7-aa68-95dc2dc60f67","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 55.","contenido":"- Corresponde a la Dirección General de Normatividad, el ejercicio de las atribuciones siguientes: I. Revisar y emitir opinión sobre proyectos de reglamentos, decretos, acuerdos, circulares y demás disposiciones jurídicas que deban ser suscritos por la persona titular de la Secretaría; II. Revisar y coordinar la elaboración de los proyectos de ordenamientos jurídicos que corresponda emitir a la persona titular de la Secretaría; III. Revisar y, en su caso, coordinar la elaboración de los proyectos de iniciativas de leyes, decretos, reglamentos y demás disposiciones jurídicas relacionados con la competencia de la Secretaría; IV. Revisar y emitir la opinión sobre las disposiciones normativas que emitan las unidades administrativas y los órganos administrativos desconcentrados de la Secretaría, así como de las entidades paraestatales sectorizadas a esta; V. Revisar y validar la emisión, modificación y cancelación de normas oficiales mexicanas, procedimientos de evaluación de la conformidad, procedimientos de homologación, así como de otras disposiciones normativas competencia de las unidades administrativas y los órganos administrativos desconcentrados de la Secretaría, así como de las entidades paraestatales sectorizadas a esta; VI. Coordinar la tramitación de los análisis de impacto regulatorio relativos a los proyectos de regulación que emita la Secretaría y remitirlos al responsable oficial de mejora regulatoria; VII. Coordinar la integración y, en su caso, ejecución de la agenda de mejora regulatoria y del programa de mejora regulatoria a cargo de la Secretaría; VIII. Supervisar la tramitación de los análisis de impacto regulatorio relativos a los proyectos de regulación que emita la Secretaría; IX. Colaborar en la integración de la solicitud de registro de los trámites que deban ser inscritos en el Registro Federal de Trámites y Servicios, con el apoyo de las unidades administrativas correspondientes; X. Coordinar y participar en los comités consultivos nacionales de normalización para el sector energético o cualquier otra materia competencia de la Secretaría, y XI. Participar en los comités técnicos de estandarización para el sector eléctrico, sector hidrocarburos y en las materias de planeación y transición energética o cualquier otra materia competencia de la Secretaría.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LAS UNIDADES ADMINISTRATIVAS ADSCRITAS A LA OFICINA DE LA PERSONA TITULAR DE LA SECRETARÍA","seccion_nombre":null,"orden":56},{"id":"ce918ec9-61d4-452e-8d6d-a7da6d2dd0d0","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo   56.","contenido":"- Corresponde a la Dirección General de Representación Legal y de lo Contencioso, el ejercicio de las atribuciones siguientes: I. Representar legalmente en los juicios de amparo a la persona titular de la Secretaría o cuando ésta represente a la persona titular del Ejecutivo Federal; II. Representar legalmente a la Secretaría, a la persona titular de esta y a las unidades administrativas que tiene adscritas, en toda clase de procedimientos judiciales, contenciosos administrativos y laborales que se tramiten ante las autoridades judiciales y jurisdiccionales competentes; III. Fungir como enlace de la Secretaría con los organismos de protección de los derechos humanos; IV. Formular denuncias o querellas en representación de la Secretaría o de las unidades administrativas que tiene adscritas, coadyuvar con el Ministerio Público en el ejercicio de la acción penal y, en su caso, otorgar el perdón legal; V. Coordinar el trámite y substanciación de los recursos de revisión que deban ser resueltos por la persona titular de la Secretaría, así como instruir la realización de todos los actos procesales necesarios; VI. Promover e intervenir en las reclamaciones, juicios y procedimientos en que la Secretaría tenga interés y, en general, en aquellos asuntos cuyas resoluciones puedan afectar los bienes asignados a esta, sin perjuicio de las atribuciones que correspondan a la Fiscalía General de la República; VII. Asistir y asesorar a las unidades administrativas de la Secretaría, en el levantamiento de las actas administrativas; VIII. Coordinar y coadyuvar en las acciones necesarias para la atención de los mecanismos alternativos de solución de controversias en los que la Secretaría sea parte, así como negociar la solución más conveniente a los intereses de ésta; IX. Representar legalmente a la Secretaría en todo tipo de procedimientos de arbitraje en México o en el extranjero en el que sea parte; X. Coordinar y solicitar a las entidades paraestatales y empresas públicas del Estado sectorizadas a la Secretaría, así como a los órganos administrativos desconcentrados de dicha dependencia, la información y documentación para la estrategia legal en todo tipo de procedimientos jurisdiccionales y de arbitraje en México o en el extranjero; XI. Someter a consideración del Comité de Asignaciones, Contratos y Permisos, a solicitud de las unidades administrativas de la Secretaría competentes, el inicio y resolución del procedimiento administrativo de sanción de los asuntos de su competencia; XII. Substanciar y tramitar los procedimientos administrativos de revocación, caducidad y sanción e imposición de sanciones derivados de la ejecución o incumplimiento de las autorizaciones, permisos, asignaciones, contratos u obligaciones esta b lecidas en las leyes, así como de otros actos competencia de la Secretaría; XIII. Notificar las resoluciones que apruebe y emita el Comité de Asignaciones, Contratos y Permisos y, en su caso, ejecutar lo ordenado en éstas con el apoyo de las unidades administrativas de la Secretaría competentes; XIV. Determinar la existencia y actualización de las causales de caso fortuito o fuerza mayor, de rescisión administrativa o contractual, terminación anticipada e imposición de penas convencionales y sanciones, derivadas de las asignaciones y contratos en materia de hidrocarburos, previa solicitud de las unidades administrativas competentes de la Secretaría; XV. Coordinar a las unidades de asuntos jurídicos de las entidades paraestatales y empresas públicas del Estado sectorizadas a la Secretaría, así como a los órganos administrativos desconcentrados de dicha dependencia, así como solicitar la información que se requiera para resolver los asuntos de su competencia, y XVI. Solicitar a las unidades administrativas de la Secretaría, la formulación de argumentos técnicos, así como la remisión de información y documentación correspondiente, para la adecuada representación y defensa en los asuntos jurisdiccionales y la resolución de los procedimientos administrativos de su competencia.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LA SUBSECRETARÍA DE PLANEACIÓN Y TRANSICIÓN ENERGÉTICA Y SUS UNIDADES ADMINISTRATIVAS","seccion_nombre":null,"orden":57},{"id":"087ef499-f612-4739-bc2a-e724cbffeab3","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 57.","contenido":"- Corresponde a la Unidad de Enlace Legislativo, el ejercicio de las atribuciones siguientes: I. Fungir como Enlace Legislativo con el Congreso de la Unión, a través de sus Cámaras, Órganos de Gobierno, Mesa Directiva, Junta de Coordinación Política, Comisiones y Legisladores; así como con las legislaturas de las entidades federativas y de la Ciudad de México, para el desahogo de procedimientos legislativos relacionados con asuntos del ámbito de competencia de la Secretaría; II. Coordinar y supervisar la integración de la información y documentación necesaria sobre aquellos asuntos legislativos de interés y competencia de las unidades administrativas y órganos administrativos desconcentrados de la Secretaría, así como de las entidades paraestatales y empresas públicas del Estado sectorizadas a esta, que se presenten ante el Congreso de la Unión y los Congresos locales; III. Promover e impulsar todas aquellas acciones tendientes al fortalecimiento de las relaciones con Congreso de la Unión y los Congresos locales, mediante el cabildeo que propicie los consensos y acuerdos, así como con instituciones públicas o privadas, que fortalezcan los temas en materia energética; IV. Implementar y fortalecer los mecanismos de comunicación efectiva y diálogo con el Congreso de la Unión, en sus Cámaras, Comisiones, Grupos Parlamentarios, Grupos de Amistad, grupos de trabajo; así como, los Congresos locales y municipios; incluyendo la organización y seguimiento de reuniones entre estos y las unidades administrativas de la Secretaría; V. Promover y fomentar todas aquellas actividades que originen y construyan acuerdos con el Congreso de la Unión, los Congresos locales, instituciones públicas y privadas en temas de interés y competencia de las unidades administrativas y órganos administrativos desconcentrados de la Secretaría, así como de las entidades paraestatales y empresas públicas del Estado sectorizadas esta; VI. Solicitar e integrar toda aquella información a las unidades administrativas y órganos administrativos desconcentrados de la Secretaría, así como de las entidades paraestatales y empresas públicas del Estado sectorizadas a esta, con el fin de construir los informes que por mandato legal est é obligada la persona titular de la Secretaría, a presentar ante en el Congreso de la Unión; VII. Participar con las unidades administrativas de la Secretaría en la integración de información que la persona titular de la Secretaría requiera con motivo de giras de trabajo o eventos públicos en su ámbito de competencia; VIII. Orientar a la persona titular de la Secretaría y a las unidades administrativas en la atención de asuntos de carácter legislativo, en el ámbito de su competencia, y IX. Coordinar y revisar, con el apoyo de la Unidad de Asuntos Jurídicos, todos aquellos instrumentos de carácter legislativo que elaboren las unidades administrativas de la Secretaría para su presentación y seguimiento ante el Congreso de la Unión y los Congresos locales.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LAS UNIDADES ADMINISTRATIVAS ADSCRITAS A LA OFICINA DE LA PERSONA TITULAR DE LA SECRETARÍA","seccion_nombre":null,"orden":58},{"id":"b224dffd-c0c3-4385-8b67-18f9c411ef1c","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 58.","contenido":"- Corresponde a la Unidad de Estrategia, Vinculación Interinstitucional y Seguimiento de Proyectos e Inversiones, el ejercicio de las atribuciones siguientes: I. Diseñar e implementar la estrategia institucional, para dar seguimiento a las políticas públicas, planes y programas de trabajo institucionales de la Secretaría, alineados con los objetivos rectores y estrategias establecidos en el Plan Nacional de Desarrollo e instrumentos de planeación del sector energético; II. Establecer canales de comunicación institucionales y mecanismos de coordinación con las dependencias, órganos desconcentrados, organismos descentralizados, Empresas Públicas del Estado y demás autoridades del sector energético, así como con representantes de los sectores académico, social y privado, para el seguimiento de las políticas públicas, planes, programas de trabajo institucionales y demás temas inherentes al sector energético; III. Implementar mecanismos de comunicación y coordinación con las autoridades de los tres órdenes de gobierno para el seguimiento de las políticas públicas, planes y programas de trabajo institucionales del sector energético y demás temas inherentes al sector energético; IV. Conducir la integración de información coordinando a las unidades administrativas de la Secretaría, para las reuniones, comparecencias, eventos, foros, reuniones de trabajo y presentaciones a cargo de la persona titular de la Secretaría; V. Coordinar a las unidades administrativas de la Secretaría, a efecto de dar seguimiento a los acuerdos alcanzados por la persona titular de la Secretaría durante las reuniones de trabajo, actividades y eventos institucionales; VI. Someter a la consideración de la persona titular de la Secretaría, las propuestas de reuniones de trabajo, actividades y eventos institucionales en las que corresponda participar u organizar a la Secretaría, así como su seguimiento; VII. Validar los planes y programas de trabajo institucionales de la Secretaría, en coordinación con las unidades administrativas competentes, para la revisión y aprobación de la persona titular de la Secretaría; VIII. Dirigir la revisión y seguimiento al cumplimiento de metas institucionales de las unidades administrativas de la Secretaría, para someterlo a consideración de la persona titular de la Secretaría; IX. Fungir como enlace de la Secretaría ante la Secretaría Técnica del Gabinete de la Presidencia, con el fin de atender los asuntos relacionados con el sector energético; X. Dar seguimiento al cumplimiento de los compromisos, acuerdos e instrucciones dictados en las sesiones de gabinete, respecto del sector energético, así como de las órdenes y directrices cuyo seguimiento le encomiende la persona titular de la Secretaría; XI. Formular y establecer los mecanismos para integrar y elaborar los informes, reportes, análisis y estudios, responsabilidad de las unidades administrativas, que deban ser aprobados, publicados o presentados por la persona titular de la Secretaría, ante el Congreso de la Unión, medios, foros o eventos públicos; XII. Consolidar la integración de la cartera de proyectos estratégicos y de infraestructura del sector energético; XIII. Administrar el sistema de registro y seguimiento de la cartera de proyectos estratégicos y de infraestructura del sector energético; XIV. Dirigir el análisis, diagnóstico y evaluación sobre la viabilidad financiera, presupuestal, económica, normativa y técnica de los proyectos estratégicos y de infraestructura del sector energético, así como respecto de su alineación a la política energética nacional; XV. Implementar la ventanilla digital para la simplificación administrativa y agilidad técnica del sector energético e instruir su adopción a los órganos administrativos desconcentrados, organismos descentralizados y empresas públicas del Estado del sector energético y, en su caso, coordinarse con la Agencia de Transformación Digital y Telecomunicaciones; así como promover su interoperabilidad con otros mecanismos similares en la Administración Pública Federal; XVI. Asegurar la integración de los trámites que deban ser inscritos en el Registro Federal de Trámites y Servicios, en coordinación con las unidades administrativas competentes y la Unidad de Asuntos Jurídicos para la obtención del registro, y XVII. Establecer e implementar un sistema de seguimiento y evaluación del desarrollo de los proyectos que conformen la cartera de proyectos estratégicos y de infraestructura del sector energético.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LAS UNIDADES ADMINISTRATIVAS ADSCRITAS A LA OFICINA DE LA PERSONA TITULAR DE LA SECRETARÍA","seccion_nombre":null,"orden":59},{"id":"bc510700-51b4-4080-80b9-efae0ad2f34e","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 59.","contenido":"- Corresponde a la Dirección General de Evaluación, Análisis y Seguimiento de Proyectos, el ejercicio de las atribuciones siguientes: I. Dirigir la elaboración del diagnóstico sobre la viabilidad financiera y económica de los proyectos estratégicos y de infraestructura del sector energético, así como su alineación a la política energética nacional; II. Dirigir la elaboración del diagnóstico sobre la viabilidad normativa de los proyectos estratégicos y de infraestructura del sector energético, así como respecto de su alineación a la política energética nacional; III. Dirigir la elaboración del diagnóstico sobre la prefactibilidad técnica, de los proyectos estratégicos y de infraestructura del sector energético, así como respecto de su alineación a la política energética nacional; IV. Proponer a la persona titular de la Unidad de Estrategia, Vinculación Interinstitucional y Seguimiento de Proyectos e Inversiones, aquellos proyectos susceptibles de formar parte de la cartera de proyectos estratégicos y de infraestructura del sector energético; V. Diseñar e instrumentar mecanismos de seguimiento para la ejecución de los proyectos estratégicos y de infraestructura del sector energético que integren la cartera; VI. Organizar y dirigir mesas técnicas con autoridades, empresas públicas del Estado y participantes del sector energético; VII. Formular los requerimientos de información y documentación a las unidades administrativas de la Secretaría, órganos administrativos desconcentrados, organismos descentralizados y empresas públicas del Estado, para la elaboración de diagnósticos relativos a los proyectos estratégicos y de infraestructura del sector energético; VIII. Evaluar la ejecución, desarrollo o ambas de los proyectos estratégicos y de infraestructura del sector energético y proponer la integración de los resultados en las actualizaciones de los instrumentos de planeación del sector energético; IX. Formular el análisis sobre la viabilidad presupuestal de los proyectos estratégicos y de infraestructura públicos del sector energético, y X. Emitir opinión, para consideración de las unidades administrativas de la Secretaría, concerniente al contenido nacional acorde con las características de los proyectos estratégicos y de infraestructura del sector energético, y, en su caso, coordinarse con la Secretaría de Economía.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LA SUBSECRETARÍA DE ELECTRICIDAD Y SUS UNIDADES ADMINISTRATIVAS","seccion_nombre":null,"orden":60},{"id":"6a63acf1-bc77-423c-bc06-a0c4cc04a723","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 60.","contenido":"- Corresponde a la Dirección General de Estrategia y Vinculación Interinstitucional, el ejercicio de las atribuciones siguientes: I. Proponer la estrategia institucional para el seguimiento a la implementación de políticas, planes y programas de trabajo institucionales de la Secretaría, alineados con los objetivos rectores y estrategias establecidos en el Plan Nacional de Desarrollo y los instrumentos de planeación del sector energético; II. Dirigir la integración del programa de trabajo de la Secretaría, en coordinación con las unidades administrativas competentes, para la revisión y aprobación de la persona titular de la Secretaría; III. Colaborar en la revisión y seguimiento al cumplimiento de metas institucionales de las unidades administrativas de la Secretaría; IV. Supervisar la integración de los documentos que elaboren las unidades administrativas de la Secretaría que contenga información del sector que deba presentar la persona titular de la Secretaría, tales como informes, reportes, análisis, estudios y opiniones, ante los gobiernos federal, estatales y municipales, así como con instituciones públicas o privadas; V. Diseñar los mecanismos e instrumentos que proporcionen a las unidades administrativas de la Secretaría, las instrucciones y guía para la elaboración de documentos con información ordenada y concisa que deba presentar la persona titular de la Secretaría en actividades institucionales de carácter público o privado; VI. Integrar la información y documentación sobre los acuerdos alcanzados por la persona titular de la Secretaría en las reuniones de trabajo, actividades y eventos institucionales, con el fin de turnarlas a las unidades administrativas competentes para su atención, seguimiento y resolución para su posterior reporte de conclusión; VII. Proponer a la persona titular de la Unidad de Estrategia, Vinculación Interinstitucional y Seguimiento de Proyectos e Inversiones, la realización de reuniones de trabajo, actividades y eventos relacionados con las políticas, planes y programas de trabajo institucionales; VIII. Colaborar en la organización de reuniones de trabajo, actividades y eventos relacionados con las políticas, planes y programas de trabajo institucionales; IX. Colaborar en la implementación de vínculos, canales de comunicación institucionales y mecanismos de coordinación con las dependencias, órganos desconcentrados, organismos descentralizados, Empresas Públicas del Estado y demás autoridades del sector energético, así como con representantes de los sectores académico, social y privado, para el seguimiento de las políticas públicas, planes, programas de trabajo institucionales y demás temas inherentes al sector energético, y X. Validar la información contenida en informes, reportes, análisis y estudios solicitados por la persona titular de la Secretaría, en coordinación con las unidades administrativas competentes.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LAS UNIDADES ADMINISTRATIVAS ADSCRITAS A LA OFICINA DE LA PERSONA TITULAR DE LA SECRETARÍA","seccion_nombre":null,"orden":61},{"id":"0de2918e-c53c-41b0-813b-aa705a83d597","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 61.","contenido":"- Corresponde a la Dirección General de Innovación y Gobierno Ágil, el ejercicio de las atribuciones siguientes: I. Diseñar, coordinar y desarrollar los instrumentos que permitan implementar los mecanismos de desarrollo de estrategias, programas y soluciones interinstitucionales a través de la agilidad técnica que propicie la modernización y simplificación administrativa, con el objeto de optimizar la gestión y eficiencia operativa que permita el fomento a la inversión; II. Definir y dirigir los procedimientos de coordinación de sus órganos administrativos desconcentrados, así como de las entidades paraestatales y empresas públicas del Estado sectorizadas a esta, para la implementación de la ventanilla digital, así como de soluciones para la gestión y seguimiento de proyectos de inversión, que reduzcan la carga administrativa y fortalezcan la trazabilidad e interoperabilidad de datos, documentos y sistemas del sector con la Administración Pública Federal, y, en su caso, en coordinación con la Agencia de Transformación Digital y Telecomunicaciones; III. Formular propuestas regulatorias para la implementación de estrategias, programas y soluciones interinstitucionales de simplificación administrativa y agilidad técnica, y, en su caso, en coordinación con la Agencia de Transformación Digital y Telecomunicaciones; IV. Vigilar la ventanilla digital implementada por la Secretaría, así como los sistemas que se desarrollen e implementen para este objeto; V. Definir los trámites, estrategias, programas y soluciones digitales que progresivamente se llevarán a cabo por medio de la ventanilla digital en colaboración con la Dirección General de Desarrollo de Sistemas, Infraestructura y Comunicaciones; VI. Dirigir el registro e identificación de proyectos y usuarios de la ventanilla digital; VII. Asegurar la recopilación sistemática de información de la ejecución de la ventanilla digital, así como de los trámites, estrategias, programas y soluciones digitales e interinstitucionales implementados por la Secretaría, y dirigir la mejora continua con base en reportes periódicos de seguimiento; VIII. Coordinar programas de formación o capacitaciones orientados a la implementación de la ventanilla digital, así como de los trámites, estrategias, programas y soluciones digitales e interinstitucionales implementados por la Secretaría, así como para la adopción de metodologías ágiles, procesos simplificados, y la difusión de buenas prácticas regulatorias, y, en su caso, en coordinación con la Agencia de Transformación Digital y Telecomunicaciones; IX. Fomentar propuestas que promuevan la innovación y el desarrollo tecnológico para el cumplimiento de metas y proyectos de los instrumentos de planeación; X. Promover la coordinación entre sus órganos administrativos desconcentrados, así como de las entidades paraestatales y empresas públicas del Estado sectorizadas a esta, para propiciar que su desempeño sea eficaz, eficiente, transparente, coordinado y que cumplan con los instrumentos de planeación, y XI. Dirigir la integración de los trámites que deban ser inscritos en el Registro Federal de Trámites y Servicios, en coordinación con las unidades administrativas competentes y la Unidad de Asuntos Jurídicos para la obtención del registro.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LAS UNIDADES ADMINISTRATIVAS ADSCRITAS A LA OFICINA DE LA PERSONA TITULAR DE LA SECRETARÍA","seccion_nombre":null,"orden":62},{"id":"a2cbac67-0147-4a2b-a546-f56bf82bb1e7","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 62.","contenido":"- Corresponde a la Dirección General de Asuntos Internacionales, el ejercicio de las atribuciones siguientes: I. Proponer a la persona titular de la Secretaría la política y los lineamientos en materia energética en el ámbito internacional, aprobada por la persona titular del Ejecutivo Federal a través de la Secretaría de Relaciones Exteriores, en el que se procuren los objetivos de los planes y programas nacionales de la materia; II. Orientar a la persona titular de la Secretaría, a las unidades administrativas y órganos administrativos desconcentrados de la Secretaría, así como de las entidades paraestatales y empresas públicas del Estado sectorizadas a esta, en la atención de los asuntos de carácter internacional, en el ámbito de su competencia; III. Promover la representación y participación del sector energético, en el ámbito internacional, en coordinación con la Secretaría de Relaciones Exteriores; IV. Representar a la Secretaría en los foros bilaterales, regionales y multilaterales en materia energética y ante órganos gubernamentales extranjeros u organismos internacionales, de conformidad con las disposiciones jurídicas aplicables; V. Coordinar la participación de la Secretaría y de su sector coordinado en las convocatorias o invitaciones a reuniones, asambleas y foros internacionales convocados por los organismos en la materia; VI. Fungir como Oficina Nacional de Enlace ante el Organismo Internacional de Energía Atómica, como autoridad competente para coordinar e identificar las principales actividades de colaboración y participación, así como autorizar las solicitudes de cooperación técnica con este organismo; VII. Integrar el programa anual de participación de las personas servidoras públicas de la Secretaría en reuniones, asambleas y foros internacionales, y, en su caso, tramitar las autorizaciones correspondientes conforme a las disposiciones jurídicas aplicables; VIII. Promover, conducir y coordinar la cooperación técnica y científica que la Secretaría desarrolla a nivel bilateral, regional y multilateral; IX. Colaborar con las unidades administrativas de la Secretaría en la organización de seminarios, mesas redondas, conferencias y otras actividades de cooperación que requieran la presencia de expertos internacionales en temas de interés del sector; X. Dirigir y coordinar el procedimiento para la negociación y celebración de acuerdos internacionales, en el ámbito de competencia de la Secretaría y, en su caso, suscribir dichos acuerdos, previo dictamen favorable de la Secretaría de Relaciones Exteriores, así como llevar el registro de los instrumentos y demás documentos correspondientes; XI. Proponer a la persona titular de la Secretaría, a las personas servidoras públicas y las funciones que estas deben desempeñar ante representaciones diplomáticas o consulares, foros, organismos y mecanismos internacionales; XII. Coordinar con las unidades administrativas y órganos administrativos desconcentrados de la Secretaría, así como de las entidades paraestatales y empresas públicas del Estado sectorizadas a esta, el seguimiento y la observancia de los tratados e instrumentos internacionales en el ámbito de competencia de la Secretaría, y XIII. Proponer a la persona titular de la Secretaría las personas servidoras públicas ante representaciones diplomáticas o consulares, foros, organismos y mecanismos internacionales, y determinar sus funciones.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LAS UNIDADES ADMINISTRATIVAS ADSCRITAS A LA OFICINA DE LA PERSONA TITULAR DE LA SECRETARÍA","seccion_nombre":null,"orden":63},{"id":"fe3e0e14-7205-484b-ad9a-05db9e94ab67","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 63.","contenido":"- Corresponde a Dirección General de Comunicación Social, el ejercicio de las atribuciones siguientes: I. Aplicar los ordenamientos legales y demás normas jurídicas que de éstos deriven, cuyas disposiciones sean competencia de la Secretaría en materia de comunicación social, así como elaborar los proyectos de programas en dichas materias para consideración de la persona titular de la Secretaría, previo a su remisión a la Secretaría de Gobernación; II. Dirigir y coordinar todas las acciones en materia de comunicación social que establezca la Secretaría en el marco de la política que para tales efectos emita la Secretaria de Gobernación y la oficina de la persona titular del Ejecutivo Federal; así como elaborar las líneas efectivas de comunicación interna, programas y proyectos para validación y autorización de la persona titular de la Secretaría, o de la autoridad competente; III. Someter a consideración de la persona titular de la Secretaría la política de comunicación social de la Secretaría y su sector coordinado en materia de relaciones públicas, enlace con la fuente de medios de comunicación nacional y local; diseñar y elaborar materiales informativos y de difusión sobre las actividades institucionales, y las demás que disponga la persona titular de la Secretaría; IV. Coordinar y evaluar los programas y actividades de información, difusión, divulgación en materia de comunicación social de las unidades administrativas y órganos administrativos desconcentrados de la Secretaría, así como de las entidades paraestatales y empresas públicas del Estado sectorizadas a esta; V. Gestionar ante la Presidencia de la República y la Secretaría de Gobernación, las autorizaciones correspondientes en materia de comunicación social de las unidades administrativas y órganos administrativos desconcentrados de la Secretaría, así como de las entidades paraestatales y empresas públicas del Estado sectorizadas a esta, conforme a las leyes y lineamientos vigentes en la materia; VI. Conducir las relaciones con los medios de comunicación, así como intervenir en los contratos y supervisión de dichos medios; VII. Organiza r y superv isar las actividades en medios de comunicación y redes sociodigitales de las unidades administrativas y órganos administrativos desconcentrados de la Secretaría, así como de las entidades paraestatales y empresas públicas del Estado sectorizadas a esta y, elaborar y difundir notas, boletines de prensa, desplegados y contenido digital que divulguen sus acciones y actividades institucionales; VIII. Orientar en materia de comunicación social a las unidades administrativas y órganos administrativos desconcentrados de la Secretaría, así como de las entidades paraestatales y empresas públicas del Estado sectorizadas a esta; IX. Elaborar y coordinar la estrategia de comunicación social, programas, campañas, emisión de boletines y comunicados a los medios de comunicación de las unidades administrativas de la Secretaría, para cuyos efectos emitirá los lineamientos que correspondan; X. Fungir como enlace de las unidades administrativas y órganos administrativos desconcentrados de la Secretaría, así como de las entidades paraestatales y empresas públicas del Estado sectorizadas a esta, con las unidades administrativas adscritas a la Oficina de la Presidencia de la República, responsables de la política de comunicación social, imagen institucional y medios sociodigitales con el fin de someter a su consideración y, en su caso, la autorización de su imagen institucional; XI. Integrar los programas de información, difusión, comunicación y relaciones públicas de las unidades administrativas de la Secretaría y dirigir los servicios de apoyo en esta materia; XII. Difundir los programas y actividades que generen las distintas unidades administrativas de la Secretaría; XIII. Establecer enlaces con las unidades administrativas y órganos administrativos desconcentrados de la Secretaría, así como de las entidades paraestatales y empresas públicas del Estado sectorizadas a esta, para divulgar la información de programas y actividades que se generen en el sector o por fuentes externas para garantizar un flujo informativo eficiente; XIV. Enlazar a la Secretaría con las áreas de comunicación social de las dependencias y entidades de la Administración Pública Federal y de la Presidencia de la República, respecto de los programas y actividades de información, difusión y divulgación que se realicen; XV. Conducir y supervisar el uso correcto de la imagen institucional, la producción de materiales impresos y audiovisuales de la Secretaría, así como coordinar su edición e impresión de acuerdo con los lineamientos vigentes; XVI. Elaborar y difundir los lineamientos generales que regulen el diseño y la producción de materiales digitales, impresos, sonoros, audiovisuales, electrónicos y demás formas de comunicación y difusión de las unidades administrativas y órganos administrativos desconcentrados de la Secretaría, así como de las entidades paraestatales a esta, así como, coordinar su efectiva edición; XVII. Coadyuvar en la integración e impresión del informe y memoria anual de la Secretaría, conforme a los lineamientos fijados para tal efecto; XVIII. Coordinar la integración, actualización, conservación y preservación de los archivos en materia de comunicación social de la Secretaría, los cuales comprenden comunicados, registros de video y fotografía; XIX. Coordinar el diseño y actualización de la página de Internet de la Secretaría, con el apoyo técnico de la Dirección General de Desarrollo de Sistemas, Infraestructura y Comunicaciones de la Unidad de Administración y Finanzas; XX. Coordinar la imagen institucional de las páginas de Internet del sector, con el fin de que cumpla con la normativa aplicable; XXI. Coordinar la estrategia de Comunicación Digital y redes sociodigitales con las unidades administrativas y órganos administrativos desconcentrados de la Secretaría, así como de las entidades paraestatales y empresas públicas del Estado sectorizadas a esta, para fomentar la adopción y el desarrollo de tecnologías de la información y comunicación que promuevan la innovación, apertura, transparencia, colaboración y participación ciudadana; XXII. Diseñar, coordinar e implementar la difusión de información de la Secretaría a través de los medios de comunicación impresos, electrónicos, digitales y complementarios, así como de las redes sociodigitales; XXIII. Evaluar las campañas de las unidades administrativas y órganos administrativos desconcentrados de la Secretaría, así como de las entidades paraestatales sectorizadas a esta; XXIV. Coordinar la edición de libros y publicaciones digitales e impresas, competencia de la Secretaría, de acuerdo con los lineamientos vigentes; XXV. Coordinar las relaciones públicas de los actos, eventos y giras en las que participe la persona titular de la Secretaría y demás personas servidoras públicas de la Dependencia, y difundir la información o declaraciones que deriven de esa participación, y XXVI. Coordinar e integrar la información proveniente de los medios de comunicación, relativos a los acontecimientos de interés de las unidades administrativas y órganos administrativos desconcentrados de la Secretaría, así como de las entidades paraestatales y empresas públicas del Estado sectorizadas a esta.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LAS UNIDADES ADMINISTRATIVAS ADSCRITAS A LA OFICINA DE LA PERSONA TITULAR DE LA SECRETARÍA","seccion_nombre":null,"orden":64},{"id":"3c5ba6aa-05b2-4bfa-bfea-553daa6de1a1","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 64.","contenido":"- Corresponde a la Dirección General de Impacto Social, Consulta Previa y Ocupación Superficial, el ejercicio de las atribuciones siguientes: I. Aplicar los ordenamientos jurídicos y demás normas que de estos deriven, cuyas disposiciones regulen el impacto social, la ocupación superficial y la consulta previa, libre e informada en donde se pretendan desarrollar proyectos de infraestructura del sector energético; II. Proponer la política pública en materia de justicia energética, derechos humanos y sostenibilidad del sector energético y participar en su formulación en coordinación con las dependencias y entidades competentes; III. Emitir las disposiciones administrativas, incluyendo metodologías y disposiciones técnico-operativas, en materia de consulta previa, impacto social, las relativas a la ocupación superficial, y las demás que se requieran para el ejercicio de sus atribuciones; IV. Emitir opinión técnica en los temas de ocupación superficial, impacto social y consulta previa, libre e informada y las demás que se requieran para el ejercicio de sus atribuciones; V. Proponer la celebración de acuerdos de colaboración y coordinación necesarios en materia de consulta previa, libre e informada, impacto social, las relativas a la ocupación superficial y las demás que se requieran para el ejercicio de sus atribuciones; VI. Emitir, con la opinión en su caso de la Unidad de Asuntos Jurídicos, los lineamientos y modelos de contrato que podrán ser utilizados en el marco de la negociación para el uso, goce, afectación o, en su caso, adquisición de los terrenos, bienes o derechos para el sector Hidrocarburos y para el sector Eléctrico; VII. Recibir los avisos de inicio de negociación que presenten las empresas públicas del Estado, las personas asignatarias, contratistas, permisionarias o personas interesadas, para el uso, goce o afectación de los terrenos, bienes o derechos necesarios para la ocupación superficial; VIII. Recibir las solicitudes de mediación y prever, en su caso, la participación de testigos sociales en los procesos de mediación en los términos que señalen las disposiciones jurídicas aplicables; IX. Atender y sugerir, con el apoyo de los testigos sociales, la forma o modalidad de adquisición, uso, goce o afectación, así como los montos de la contraprestación, en los casos de mediación, en los términos que establezcan las disposiciones jurídicas; X. Solicitar al Instituto de Administración y Avalúos de Bienes Nacionales, en caso de mediación, la designación de un perito del padrón de valuadores del sector energético; XI. Recibir copia de los acuerdos alcanzados o las medidas decretadas por el ejecutivo federal o los tribunales competentes, en materia de uso y ocupación superficial; XII. Emitir las disposiciones administrativas respecto de los contenidos específicos, características y modalidades de las manifestaciones de impacto social, así como los elementos para definir el monto de inversión anual de los planes de gestión social; XIII. Elaborar el estudio de impacto social respecto del área objeto de asignaciones y contratos de exploración y extracción de hidrocarburos; XIV. Determinar sobre la presencia de pueblos y comunidades indígenas y afromexicanas en las áreas en que se llevarán a cabo las actividades para la ejecución de proyectos en materia energética, así como los proyectos o actividades en materia de biocombustibles, geotermia y cualquiera otra competencia de la Secretaría; XV. Recibir las manifestaciones de impacto social del sector energético que se presenten para desarrollar proyectos en materia energética; XVI. Poner a disposición del público las manifestaciones de impacto social del sector energético en los términos establecidos en la regulación aplicable; XVII. Emitir, otorgar, negar, revocar o modificar la autorización sobre las manifestaciones de impacto social del sector energético que se presenten para desarrollar proyectos en materia energética; XVIII. Resolver respecto de la presentación, excepciones o improcedencias de las manifestaciones de impacto social; XIX. Recibir la información sobre los cambios y modificaciones a los proyectos autorizados en materia de manifestaciones de impacto social del sector energético, así como cualquier otra relacionada con los términos y condicionantes de las autorizaciones; XX. Recibir el informe de la implementación del Plan de Gestión Social de los proyectos autorizados en materia de manifestaciones de impacto social del sector energético; XXI. Realizar visitas de inspección, supervisión y verificación sobre el cumplimiento de los términos y condicionantes en materia de impacto social; XXII. Dirigir y coordinar la integración del expediente y proponer a la Unidad de Asuntos Jurídicos la tramitación del procedimiento administrativo de sanción. XXIII. Habilitar días y horas inhábiles para la práctica de notificaciones, actuaciones y diligencias administrativas, incluidas visitas de verificación en materia de su competencia, con base en las disposiciones jurídicas aplicables; XXIV. Ordenar la práctica de notificaciones, actuaciones y diligencias administrativas, incluidas visitas de verificación en materia de su competencia, así como habilitar a los notificadores y verificadores para realizarlas y facultarlos, cuando proceda, para imponer, ejecutar, modificar o revocar los actos administrativos previstos en las disposiciones jurídicas aplicables; XXV. Llevar a cabo los procedimientos de consulta previa, libre e informada, así como cualquier otra actividad necesaria para la salvaguarda de los derechos e intereses de los pueblos y comunidades indígenas y afromexicanas, en las actividades de los sectores eléctrico, hidrocarburos, litio, geotermia, así como en cualquier otra que dispongan las normas correspondientes y, en su caso, en coordinación con el Instituto Nacional de los Pueblos Indígenas; XXVI. Fungir como responsable de los procedimientos de consulta previa, libre e informada de las actividades de los sectores eléctrico, hidrocarburos, litio, geotermia, así como en cualquier otra que dispongan las normas correspondientes; XXVII. Representar a la Secretaría en los procedimientos de consulta previa, libre e informada y, en su caso, designar a las personas servidoras públicas facultadas para tal efecto; XXVIII. Prever las gestiones necesarias para la participación de las dependencias, entidades, empresas y particulares, entre otros, en los procedimientos de consulta previa, libre e informada; XXIX. Diseñar y proponer los protocolos de consulta previa, libre e informada para las actividades de los sectores eléctrico, hidrocarburos, litio, geotermia, así como en cualquier otra que dispongan las normas correspondientes, siguiendo los principios de sostenibilidad y de derechos humanos; XXX. Requerir información sobre el seguimiento y monitoreo de acuerdos alcanzados en los procedimientos de consulta previa, libre e informada; XXXI. Fomentar la justicia energética en su vertiente de ampliación de espacios de participación inclusiva, en las cadenas productivas locales de los proyectos energéticos; XXXII. Requerir información necesaria para el desarrollo de sus funciones a las dependencias, incluidos sus órganos administrativos desconcentrados, y entidades paraestatales de la Administración Pública Federal y, en general, a toda persona física o moral que realice cualquiera de las actividades a que se refieren la Ley del Sector Hidrocarburos, la Ley del Sector Eléctrico y demás ordenamientos aplicables; XXXIII. Proporcionar la información y documentación necesarias para que la Unidad de Asuntos Jurídicos cuente con los elementos relacionados con los procedimientos jurisdiccionales o no jurisdiccionales en las materias de su competencia; XXXIV. Interpretar para efectos administrativos las disposiciones materia de su competencia; XXXV. Revisar y aprobar el proyecto de programa anual de trabajo, anteproyecto anual de presupuesto, así como los proyectos de manuales de organización y de procedimientos en la materia de su competencia; XXXVI. Suscribir los actos administrativos y demás documentos relativos al ejercicio de sus facultades en materia de impacto social, consulta previa , libre e informada , y ocupación superficial, o de las que le sean delegadas o le correspondan por suplencia; XXXVII. Ejercer en el territorio nacional las facultades que este Reglamento y demás ordenamientos jurídicos aplicables le confieran; XXXVIII. Coadyuvar, en el ámbito de competencia a las actividades de la planeación vinculante del sector energético prevista en las disposiciones jurídicas aplicables.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LAS UNIDADES ADMINISTRATIVAS ADSCRITAS A LA OFICINA DE LA PERSONA TITULAR DE LA SECRETARÍA","seccion_nombre":null,"orden":65},{"id":"6eca6816-bf6c-4c72-adc5-a1517d3fe8c1","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 65.","contenido":"- Corresponde a la Dirección General de Transparencia y Protección de Datos Personales, el ejercicio de las atribuciones siguientes: I. Verificar el debido cumplimiento de las obligaciones, procedimientos y responsabilidades establecidas en la Ley General de Transparencia y Acceso a la Información Pública, a través de la atención, gestión y trámite de las solicitudes de acceso a información pública y de los recursos de revisión, prevaleciendo el principio de certeza y máxima publicidad; II. Dirigir las acciones para solventar en tiempo y forma los requerimientos, observaciones, recomendaciones y/o criterios en materia de transparencia y acceso a la información pública; III. Consolidar informes, reportes o estadísticas sobre la gestión de las solicitudes de información y atención de recursos de revisión; IV. Proponer al Comité de Transparencia los procedimientos internos que aseguren la mayor eficiencia en la gestión de las solicitudes de acceso a la información pública, conforme a la normatividad aplicable; V. Coordinar las acciones para la publicación y actualización de las obligaciones de transparencia que sean aplicables de acuerdo con las facultades y atribuciones de cada unidad administrativa, en la página de internet y en los respectivos medios electrónicos que señale la normatividad vigente; VI. Fomentar políticas de transparencia con sentido social, impulsar la profesionalización y capacitación de las personas servidoras públicas en materia de transparencia, protección de datos personales, organización de archivos y temas afines; VII. Vigilar la aplicación de las disposiciones de la Ley General de Protección de Datos Personales en Posesión de Sujetos Obligados, bajo las bases, principios y procedimientos establecidos en el ejercicio de los derechos de Acceso, Rectificación, Cancelación y Oposición (Derechos ARCO) de los datos personales bajo resguardo de las unidades administrativas; VIII. Coordinar la atención oportuna de las solicitudes de datos personales, así como los recursos de revisión que deriven de estas, garantizando los principios de licitud, finalidad, lealtad, consentimiento, calidad, proporcionalidad, información y responsabilidad en el tratamiento de datos personales, y IX. Atender los requerimientos de verificación, denuncias, investigaciones y cualquier procedimiento en materia de datos personales. CAPÍTULO XI DE LA SUPLENCIA DE LAS PERSONAS SERVIDORAS PÚBLICAS DE LA SECRETARÍA","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LAS UNIDADES ADMINISTRATIVAS ADSCRITAS A LA OFICINA DE LA PERSONA TITULAR DE LA SECRETARÍA","seccion_nombre":null,"orden":66},{"id":"63d258eb-3d9b-4cee-b53b-ebfe8fe17758","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 66.","contenido":"- La persona titular de la Secretaría será suplida en sus ausencias, por las personas titulares de la Subsecretaría de Planeación y Transición Energética, de la Subsecretaría de Hidrocarburos, de la Subsecretaría de Electricidad, o de la Unidad de Administración y Finanzas, en el orden indicado. A falta de las personas servidoras públicas referidas en el párrafo anterior, las ausencias de la persona titular de la Secretaría será suplida por las personas servidoras públicas señaladas en el artículo 2, apartado E, de este Reglamento, en el orden indicado en dicho precepto. En las controversias constitucionales o acciones de inconstitucionalidad será suplida por las personas servidoras públicas antes señaladas y, sólo en ausencia de estas, por la persona titular de la Unidad de Asuntos Jurídicos, quienes pueden promover los recursos que correspondan y los medios de defensa legales que resulten procedentes.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LA SUPLENCIA DE LAS PERSONAS SERVIDORAS PÚBLICAS DE LA SECRETARÍA","seccion_nombre":null,"orden":67},{"id":"cc5c14af-df8f-4656-ac81-57a33c9c6738","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 67.","contenido":"- Las personas titulares de las Subsecretarías y la persona titular de la Unidad de Administración y Finanzas serán suplidas en sus ausencias, para el despacho de los asuntos de su competencia, por las personas titulares de Unidad y Direcciones Generales adscritas, en el orden que aparecen citadas en el artículo 2 de este Reglamento.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LA SUPLENCIA DE LAS PERSONAS SERVIDORAS PÚBLICAS DE LA SECRETARÍA","seccion_nombre":null,"orden":68},{"id":"fd6b0d05-5147-4f12-a1dc-aab65bfae790","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 68.","contenido":"- La ausencia de las personas titulares de la Unidad de Asuntos Jurídicos y de las Direcciones Generales, será suplida por las personas servidoras públicas de jerarquía inmediata inferior en el ámbito de su competencia.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LA SUPLENCIA DE LAS PERSONAS SERVIDORAS PÚBLICAS DE LA SECRETARÍA","seccion_nombre":null,"orden":69},{"id":"824d063a-126d-4c08-975f-ae1087a70eca","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 69.","contenido":"- Las ausencias de las personas titulares de la Comisión Nacional de Seguridad Nuclear y Salvaguardias, de la Comisión Nacional para el Uso Eficiente de la Energía y de la Comisión Nacional de Energía, serán suplidas por las personas servidoras publicas jerárquicamente inferiores conforme lo establezca su Manual de Organización.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LA SUPLENCIA DE LAS PERSONAS SERVIDORAS PÚBLICAS DE LA SECRETARÍA","seccion_nombre":null,"orden":70},{"id":"06c9e8b1-2558-474c-b1a3-885780d2b0d6","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 70.","contenido":"- Las personas servidoras públicas que actúen en suplencia en términos de las disposiciones de este Capítulo y las que de ellas emanen, contarán con las funciones y responsabilidades de la persona servidora pública a la que suplen. Tratándose de personas servidoras públicas que actúen en suplencia por orden, delegación de responsabilidades o asignación de funciones, contarán con las funciones y responsabilidades de la persona servidora pública a la que suplen. CAPÍTULO XII DE LOS ÓRGANOS ADMINISTRATIVOS DESCONCENTRADOS","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LA SUPLENCIA DE LAS PERSONAS SERVIDORAS PÚBLICAS DE LA SECRETARÍA","seccion_nombre":null,"orden":71},{"id":"60fb2a61-42f9-451e-9d3c-607cf34fe018","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 71.","contenido":"- Para la eficaz atención y el eficiente despacho de los asuntos de su competencia, la Secretaría cuenta con los órganos administrativos desconcentrados que le están jerárquicamente subordinados y a los que se les otorga autonomía técnica y operativa, facultades ejecutivas para resolver sobre materias específicas dentro del ámbito de competencia que se determine en cada caso, con apego a la normativa que al efecto se establezca en el instrumento legal correspondiente.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LOS ÓRGANOS ADMINISTRATIVOS DESCONCENTRADOS","seccion_nombre":null,"orden":72},{"id":"4906c4ad-1456-42bb-8902-2afec7d79c6a","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 72-","contenido":"La Comisión Nacional de Seguridad Nuclear y Salvaguardias, y la Comisión Nacional para el Uso Eficiente de la Energía, tienen la organización y las atribuciones que establecen los ordenamientos legales y reglamentarios por los que fueron creados o que regulan su organización y funcionamiento.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LOS ÓRGANOS ADMINISTRATIVOS DESCONCENTRADOS","seccion_nombre":null,"orden":73},{"id":"090f1bb6-af6f-4816-a22d-f5c92aed7693","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 73.","contenido":"- Al frente de la Comisión Nacional de Seguridad Nuclear y Salvaguardias existe una Dirección General, cuya persona titular se auxilia por las personas servidoras públicas quienes deben ejercer sus facultades y funciones en términos de su Manual de Organización.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LOS ÓRGANOS ADMINISTRATIVOS DESCONCENTRADOS","seccion_nombre":null,"orden":74},{"id":"4cb2108c-0857-4a3f-9a4e-878fb4ec85fa","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 74.","contenido":"- Corresponde a la Dirección General de la Comisión Nacional de Seguridad Nuclear y Salvaguardias, el ejercicio de las atribuciones siguientes: I. Representar a la Comisión Nacional de Seguridad Nuclear y Salvaguardias, ejercer el presupuesto autorizado y celebrar los actos jurídicos que se requieran para el cumplimiento de su objeto; para la mejor distribución y desarrollo del trabajo, podrá autorizar por escrito a los servidores públicos subalternos para que realicen actos y suscriban documentos; II. Planear, programar, organizar, dirigir, ejecutar, controlar y evaluar las actividades encomendadas a la unidad administrativa a su cargo; III. Representar a la Comisión Nacional de Seguridad Nuclear y Salvaguardias, ante los órganos jurisdiccionales y administrativos. La representación a que se refiere esta fracción se ejercerá ante los tribunales judiciales federales y del fuero común, las autoridades del trabajo, y ante cualquier otra autoridad jurisdiccional. La representación a que se hace referencia, la podrá realizar el titular del área de asuntos jurídicos, pudiendo delegarla mediante escrito a otros servidores públicos; IV. Suscribir títulos y operaciones de crédito relativos a la administración de los recursos del órgano desconcentrado que representa; V. Nombrar y remover al personal técnico y administrativo, así como intervenir en el desarrollo, capacitación, promoción y adscripción del personal a su cargo; autorizar los movimientos internos del personal, así como licencias considerando las necesidades del servicio, y participar directamente o a través de un representante en los casos de sanciones, remoción y cese de su personal en los términos de las disposiciones jurídicas aplicables y de las Condiciones Generales de Trabajo; VI. Coordinar los trabajos y la administración de los recursos humanos, financieros y materiales; VII. Elaborar los manuales de organización, de procedimientos y de servicios al público, correspondientes a la unidad administrativa a su cargo, conforme a los lineamientos establecidos; VIII. Expedir normas oficiales mexicanas, así como presidir, y en su caso , designar al Presidente del Comité Consultivo Nacional de Normalización de Seguridad Nuclear y Salvaguardias; IX. Participar en los Comités Consultivos Nacionales de Normalización en las materias relacionadas con el ejercicio de sus atribuciones, así como en los subcomités y grupos de trabajo respectivos; X. Participar, en su caso, con las unidades administrativas de la Secretaría, en la elaboración de los anteproyectos de normas oficiales mexicanas que les correspondan; XI. Certificar, verificar, supervisar, vigilar e inspeccionar la aplicación y el cumplimiento de las normas oficiales mexicanas, que en la materia de su competencia se expidan; XII. Realizar la evaluación de la conformidad de las normas oficiales mexicanas, relativas a las materias de su competencia; XIII. Aprobar y, en su caso, revocar a los Organismos de Evaluación de la Conformidad acreditados que se requieran para la evaluación de la conformidad; XIV. Ejercer con estricto apego a los ordenamientos jurídicos y administrativos aplicables en materia de adquisiciones, arrendamientos de bienes muebles y prestación de servicios de cualquier naturaleza, las atribuciones siguientes: a) Emitir las políticas, bases y lineamientos para la planeación, programación, presupuestación, contratación, gasto y control de las adquisiciones y arrendamientos de bienes muebles y la prestación de servicios de cualquier naturaleza; b) Autorizar la erogación para la contratación de servicios de consultorías, asesorías, estudios e investigaciones; c) Dictaminar directamente, previo a la iniciación del procedimiento, sobre la procedencia de no celebrar licitaciones públicas por encontrarse en alguno de los supuestos de excepción; d) Recibir para su consideración las políticas, bases y lineamientos en materia de adquisiciones, arrendamientos y servicios, así como las propuestas de autorizaciones de los supuestos no previstos en dichas políticas, bases y lineamientos que le presente el comité respectivo, de conformidad con la Ley de Adquisiciones, Arrendamientos y Servicios del Sector Público; e) En el caso de excepción a las licitaciones públicas, determinar al servidor público que deberá autorizar los proyectos de investigación científica y desarrollo tecnológico, y f) Suscribir convenios y contratos relacionados con el cumplimiento de sus facultades. XV. Ejercer con estricto apego a los ordenamientos jurídicos y administrativos aplicables en materia de obras públicas y servicios relacionados con las mismas, las atribuciones siguientes: a) Emitir las políticas, bases y lineamientos para la planeación, programación, presupuestación, contratación, gasto, ejecución y control de las Obras Públicas y Servicios Relacionados con las Mismas; b) Establecer, en caso de requerirse, el comité de obras públicas, en términos de las disposiciones jurídicas aplicables; c) Designar a las personas servidoras públicas que pueden ordenar la suspensión de los trabajos contratados y determinar, en su caso, la temporalidad de ésta, en términos del artículo 60 de la Ley de Obras Públicas y Servicios Relacionados con las Mismas, y d) Suscribir convenios y contratos relacionados con el cumplimiento de sus atribuciones, en materia de la Ley de Obras Públicas y Servicios Relacionados con las Mismas. XVI. Vigilar que la exploración, explotación y beneficio de minerales radiactivos, el aprovechamiento de los combustibles nucleares, los usos de la energía nuclear y, en general, que todas las actividades relacionadas con esta, se lleven a cabo con apego a las disposiciones jurídicas sobre seguridad nuclear, radiológica, física y de salvaguardias en las instalaciones nucleares o radiactivas, de manera que se eviten riesgos a la salud humana y se asegure la preservación del equilibrio ecológico y la protección al ambiente; XVII. Expedir, revalidar, reponer, modificar, suspender y revocar los permisos y licencias para las instalaciones radiactivas y prestadores de servicios de estas, así como al personal que en ellas laboren; XVIII. Revisar, evaluar y autorizar las bases para el emplazamiento, diseño, construcción, operación, modificación, cese de operaciones, cierre definitivo y desmantelamiento de instalaciones nucleares y radiactivas; XIX. Otorgar, modificar, suspender y revocar los permisos para la realización de actividades en las instalaciones nucleares; así como otorgar las licencias al personal que labore en ellas; XX. Autorizar el emplazamiento, diseño, construcción, operación, modificación, cese de operaciones, cierre definitivo y desmantelamiento de las instalaciones nucleares; XXI. Autorizar las importaciones y exportaciones de materiales radiactivos y equipos que los contengan, para los efectos de seguridad, registro y control; XXII. Regular y autorizar la gestión de residuos nucleares y radiactivos, así como su almacenamiento y depósito; XXIII. Autorizar la importación, exportación, posesión, transferencia, almacenamiento, transporte, destino o disposición final de materiales y combustibles nucleares, con la participación que corresponda a otras dependencias; XXIV. Intervenir y suscribir convenios, acuerdos y compromisos internacionales de carácter bilateral y multilateral, en materia de seguridad nuclear, seguridad radiológica, seguridad física y salvaguardias; XXV. Ejecutar y dar seguimiento a tratados y convenciones en materia de seguridad nuclear, seguridad radiológica, seguridad física y salvaguardias, así como a los convenios, acuerdos y compromisos internacionales a que se refiere la fracción anterior; XXVI. Participar en los comités, grupos de trabajo y en toda clase de foros y eventos con otras autoridades y dependencias del Ejecutivo Federal en materia de seguridad nuclear, seguridad radiológica, seguridad física y salvaguardias; XXVII. Emitir la regulación y vigilar la aplicación de las normas de seguridad nuclear, radiológica, física y las salvaguardias; así como celebrar los convenios necesarios para su fortalecimiento y mejora; XXVIII. Integrar los avances tecnológicos en seguridad nuclear, radiológica, física y de salvaguardias en sus funciones de regulador, así como realizar desarrollos tecnológicos propios para sustentar técnicamente la toma de decisiones; XXIX. Promover la investigación y desarrollo tecnológico en aspectos de seguridad nuclear, radiológica, física y de salvaguardias en institutos y laboratorios, nacionales e internacionales y en centros de educación superior del país; XXX. Ejercer las atribuciones previstas en las disposiciones jurídicas aplicables en materia de salud, seguridad radiológica y transporte de materiales y residuos nucleares y radiactivos, respecto a la expedición de licencias, autorizaciones, normas, manuales y demás actos señalados en dichas disposiciones, de forma individual o coordinada, con las autoridades competentes que correspondan; XXXI. Expedir y ordenar la publicación en el Diario Oficial de la Federación, de declaratorias relativas a las determinaciones de combustible nuclear, material básico, material fisionable especial y mineral radiactivo; XXXII. Expedir las normas que regularán el empleo de reactores nucleares, así como vigilar el cumplimiento de dichas normas; XXXIII. Emitir la regulación en materia de almacenamiento, transporte, y depósito de combustibles nucleares y de desechos radiactivos; XXXIV. Emitir, cuando sea procedente conforme a las disposiciones jurídicas aplicables, las autorizaciones para la producción, el uso y aplicación de radioisótopos distintos de los fabricados a partir de combustible nuclear; XXXV. Recoger y retirar, en su caso, los utensilios, equipos, materiales existentes y, en general, cualquier bien mueble contaminado, en las instalaciones radiactivas; XXXVI. Dictar las disposiciones a que se sujetará el uso tanto energético como no energético de los materiales radiactivos; XXXVII. Emitir, cuando sea procedente conforme a las disposiciones jurídicas aplicables, las autorizaciones para el manejo y custodia de materiales radiactivos; XXXVIII. Autorizar a los organismos públicos correspondientes el almacenamiento temporal de combustibles nucleares y de desechos radiactivos derivados de su utilización; XXXIX. Emitir las autorizaciones para la producción de radioisótopos, a partir del uso de combustible nuclear; XL. Emitir las autorizaciones para la fabricación de componentes del sistema nuclear de suministro de vapor; XLI. Emitir las autorizaciones para el manejo, uso, transporte, almacenamiento, custodia y reprocesamiento de materiales y combustibles nucleares; XLII. Otorgar, modificar, suspender y revocar los permisos para la realización de actividades en las instalaciones nucleares, así como otorgar las licencias al personal que labore en ellas; XLIII. Emitir las autorizaciones para la adquisición, importación, exportación, posesión, uso, transferencia, transporte, almacenamiento y destino o disposición final de material radiactivo y dispositivos generadores de radiación ionizante, así como para la importación y exportación de combustibles y materiales nucleares, y XLIV. Las demás que le señalen otras disposiciones jurídicas aplicables, las que les confiera el superior jerárquico y las que correspondan a sus áreas administrativas.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LOS ÓRGANOS ADMINISTRATIVOS DESCONCENTRADOS","seccion_nombre":null,"orden":75},{"id":"d27385f1-1c19-49ae-9285-419ed0544880","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 75.","contenido":"- Al frente de la Comisión Nacional para el Uso Eficiente de la Energía, existe una Dirección General, cuya persona titular se auxilia de las personas servidoras públicas quienes deben ejercer sus facultades y funciones en términos de su Manual de Organización.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LOS ÓRGANOS ADMINISTRATIVOS DESCONCENTRADOS","seccion_nombre":null,"orden":76},{"id":"11b52162-b3a7-4434-b823-320befb1d4c1","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 76.","contenido":"- Corresponde a la Dirección General de la Comisión Nacional para el Uso Eficiente de la Energía, el ejercicio de las facultades previstas en la Ley de Planeación y Transición Energética, así como las funciones previstas en su Manual de Organización.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LOS ÓRGANOS ADMINISTRATIVOS DESCONCENTRADOS","seccion_nombre":null,"orden":77},{"id":"5f694cbc-38e9-4a9b-828b-b61750b9b05a","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 77.","contenido":"- Al frente de la Comisión Nacional de Energía, existe una Dirección General, cuya persona titular se auxilia de las personas servidoras públicas quienes deben ejercer sus facultades y funciones en términos de su Manual de Organización.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LOS ÓRGANOS ADMINISTRATIVOS DESCONCENTRADOS","seccion_nombre":null,"orden":78},{"id":"f7150d19-2ff3-4f1a-95c7-e4f1e086d70e","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Artículo 78.","contenido":"- Corresponde a la Comisión Nacional de Energía, el ejercicio de las facultades previstas en la Ley de la Comisión Nacional de Energía, su Reglamento, así como las funciones previstas en su Manual de Organización.","tipo_articulo":"ordinario","titulo_nombre":null,"capitulo_nombre":"DE LOS ÓRGANOS ADMINISTRATIVOS DESCONCENTRADOS","seccion_nombre":null,"orden":79},{"id":"e8f0a441-11e5-44e5-859c-d7e242429d74","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Transitorio PRIMERO.","contenido":"- El presente decreto entrará en vigor al día siguiente al de su publicación en el Diario Oficial de la Federación.","tipo_articulo":"transitorio","titulo_nombre":null,"capitulo_nombre":"DE LOS ÓRGANOS ADMINISTRATIVOS DESCONCENTRADOS","seccion_nombre":null,"orden":80},{"id":"9aa0c822-9739-4353-bc90-837862bd6270","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Transitorio SEGUNDO.","contenido":"- Se abroga el Reglamento Interior de la Secretaría de Energía publicado en el Diario Oficial de la Federación el 31 de octubre de 2014 y se derogan todas las disposiciones que se opongan al presente ordenamiento.","tipo_articulo":"transitorio","titulo_nombre":null,"capitulo_nombre":"DE LOS ÓRGANOS ADMINISTRATIVOS DESCONCENTRADOS","seccion_nombre":null,"orden":81},{"id":"6984065d-70d0-45f5-8cf1-c38b72a63327","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Transitorio TERCERO.","contenido":"- Se deberán expedir los manuales de organización y los de procedimientos de la Secretaría, necesarios para el funcionamiento de la dependencia, dentro de los 90 días hábiles contados a partir de la entrada en vigor de este decreto.","tipo_articulo":"transitorio","titulo_nombre":null,"capitulo_nombre":"DE LOS ÓRGANOS ADMINISTRATIVOS DESCONCENTRADOS","seccion_nombre":null,"orden":82},{"id":"7590c6ac-a206-48a6-9585-c2e7a62ae79a","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Transitorio CUARTO.","contenido":"- Los asuntos en trámite por parte de las unidades administrativas que se eliminan, en virtud de la entrada en vigor del presente Reglamento, serán atendidos y resueltos por las unidades administrativas a las que se les da la competencia correspondiente en este ordenamiento. Dichas unidades administrativas notificarán a los interesados el cambio respectivo. En el caso de que las unidades administrativas no se eliminen, pero sus facultades sean modificadas, corresponderá a la unidad administrativa competente conforme al Reglamento Interior abrogado, terminar la sustanciación de los asuntos que se encuentren en trámite y, en su caso, dictar la resolución que corresponda.","tipo_articulo":"transitorio","titulo_nombre":null,"capitulo_nombre":"DE LOS ÓRGANOS ADMINISTRATIVOS DESCONCENTRADOS","seccion_nombre":null,"orden":83},{"id":"6deaaf3c-6306-4fad-982a-7f2607d3d167","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Transitorio QUINTO.","contenido":"- Las referencias que se hacen y las atribuciones o facultades que se otorgan en reglamentos, decretos, acuerdos, manuales y demás disposiciones a las unidades administrativas que cambian de denominación o desaparecen por virtud del presente ordenamiento, se entenderán hechas o conferidas a las unidades administrativas que correspondan conforme a lo establecido en el mismo.","tipo_articulo":"transitorio","titulo_nombre":null,"capitulo_nombre":"DE LOS ÓRGANOS ADMINISTRATIVOS DESCONCENTRADOS","seccion_nombre":null,"orden":84},{"id":"be98630c-ba00-4910-80ce-bbbebf74e7ef","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Transitorio SEXTO.","contenido":"- La Unidad de Administración y Finanzas realizará las acciones necesarias para que los recursos humanos, financieros y materiales asignados a las unidades o áreas que se modifican o desaparecen, sean transferidos a las unidades administrativas que correspondan, en los términos del presente ordenamiento y de conformidad con las normas aplicables y la disponibilidad presupuestaria.","tipo_articulo":"transitorio","titulo_nombre":null,"capitulo_nombre":"DE LOS ÓRGANOS ADMINISTRATIVOS DESCONCENTRADOS","seccion_nombre":null,"orden":85},{"id":"2091dd5d-64a3-469c-8f79-13a7bc677ba3","ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","identificador":"Transitorio SÉPTIMO.","contenido":"- Las erogaciones que se generen con motivo de la entrada en vigor del presente Reglamento deberán ser cubiertas con cargo al presupuesto aprobado a la Secretaría de Energía en el Presupuesto de Egresos de la Federación para el ejercicio fiscal que corresponda, por lo que no se incrementará su presupuesto y no se autorizarán recursos adicionales para el presente ejercicio fiscal. Dado en la residencia del Poder Ejecutivo Federal, en Ciudad de México, a 14 de abril de 2025.- La Presidenta de los Estados Unidos Mexicanos , Claudia Sheinbaum Pardo .- Rúbrica.- La Secretaria de Energía , Luz Elena González Escobar .- Rúbrica.","tipo_articulo":"transitorio","titulo_nombre":null,"capitulo_nombre":"DE LOS ÓRGANOS ADMINISTRATIVOS DESCONCENTRADOS","seccion_nombre":null,"orden":86}],"remove":["6af52cfe-fef1-5a68-ab3d-9a10a283fcce"],"themes_before":[{"nivel":"capitulo","nombre":"CAPÍTULO I DE LA COMPETENCIA Y ORGANIZACIÓN DE LA SECRETARÍA","orden":0},{"nivel":"capitulo","nombre":"CAPÍTULO II DE LAS FACULTADES DE LA PERSONA TITULAR DE LA SECRETARÍA","orden":1},{"nivel":"capitulo","nombre":"CAPÍTULO III DE LAS FACULTADES GENÉRICAS DE LAS PERSONAS TITULARES DE LAS SUBSECRETARÍAS Y DE LA UNIDAD DE ADMINISTRACIÓN Y FINANZAS","orden":2},{"nivel":"capitulo","nombre":"CAPÍTULO IV DE LAS FACULTADES DE LA PERSONA TITULAR DE LA UNIDAD DE ADMINISTRACIÓN Y FINANZAS","orden":3},{"nivel":"capitulo","nombre":"CAPÍTULO V DE LAS FACULTADES GENÉRICAS DE LAS PERSONAS TITULARES DE LAS JEFATURAS DE UNIDAD Y DE LAS DIRECCIONES GENERALES","orden":4},{"nivel":"capitulo","nombre":"CAPÍTULO VI DE LA SUBSECRETARÍA DE PLANEACIÓN Y TRANSICIÓN ENERGÉTICA Y SUS UNIDADES ADMINISTRATIVAS","orden":5},{"nivel":"capitulo","nombre":"CAPÍTULO VII DE LA SUBSECRETARÍA DE ELECTRICIDAD Y SUS UNIDADES ADMINISTRATIVAS","orden":6},{"nivel":"capitulo","nombre":"CAPÍTULO VIII DE LA SUBSECRETARÍA DE HIDROCARBUROS Y SUS UNIDADES ADMINISTRATIVAS","orden":7},{"nivel":"capitulo","nombre":"CAPÍTULO IX DE LAS UNIDADES ADMINISTRATIVAS ADSCRITAS A LA UNIDAD DE ADMINISTRACIÓN Y FINANZAS","orden":8},{"nivel":"capitulo","nombre":"CAPÍTULO X DE LAS UNIDADES ADMINISTRATIVAS ADSCRITAS A LA OFICINA DE LA PERSONA TITULAR DE LA SECRETARÍA","orden":9},{"nivel":"capitulo","nombre":"CAPÍTULO XI DE LA SUPLENCIA DE LAS PERSONAS SERVIDORAS PÚBLICAS DE LA SECRETARÍA","orden":10},{"nivel":"capitulo","nombre":"CAPÍTULO XII DE LOS ÓRGANOS ADMINISTRATIVOS DESCONCENTRADOS","orden":11}],"themes_after":[{"id":338,"ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","nivel":"capitulo","nombre":"DE LA COMPETENCIA Y ORGANIZACIÓN DE LA SECRETARÍA","orden":0},{"id":339,"ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","nivel":"capitulo","nombre":"6/10/25, 14:13 DOF - Diario Oficial de la Federación","orden":1},{"id":340,"ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","nivel":"capitulo","nombre":"DE LAS FACULTADES GENÉRICAS DE LAS PERSONAS TITULARES DE LAS SUBSECRETARÍAS Y DE LA UNIDAD","orden":2},{"id":341,"ley_id":"266f38c4-c576-4244-9c45-0c79886cb748","nivel":"capitulo","nombre":"DE LAS FACULTADES DE LA PERSONA TITULAR DE LA UNIDAD DE ADMINISTRACIÓN Y FINANZAS","or